-- R1 exact recognition review and fixed installation contract. PostgreSQL 17, trusted application search_path.
BEGIN;
SELECT finance_assert_r1_definitions(pg_catalog.current_schema());
-- Generation input for 241. Its enclosing transaction and fixed installation
-- contract are emitted together by build-recognition-ddl.mjs.
DO $$ BEGIN
 IF current_setting('server_version_num')::integer/10000<>17 OR current_schema() IS NULL
   OR current_schema() !~ '^[a-z][a-z0-9_]*$' OR current_schema() LIKE 'pg_%' THEN
  RAISE EXCEPTION 'R1 installation requires a trusted application schema and PostgreSQL 17' USING ERRCODE='55000';
 END IF;
END $$;

ALTER TABLE transaction_invoice_recognitions ADD COLUMN IF NOT EXISTS applied_review_id text;
ALTER TABLE transaction_invoice_recognitions ADD COLUMN IF NOT EXISTS review_version integer NOT NULL DEFAULT 0;

CREATE TABLE IF NOT EXISTS recognition_review_revisions (
 review_id text PRIMARY KEY CHECK(length(review_id)>0),
 recognition_id text NOT NULL REFERENCES transaction_invoice_recognitions(recognition_id),
 review_version integer NOT NULL CHECK(review_version>0),
 previous_review_id text UNIQUE,
 before_projection_json jsonb NOT NULL,
 before_projection_hash text NOT NULL CHECK(before_projection_hash ~ '^[0-9a-f]{64}$'),
 after_projection_json jsonb NOT NULL,
 after_projection_hash text NOT NULL CHECK(after_projection_hash ~ '^[0-9a-f]{64}$'),
 basis_json jsonb NOT NULL,
 basis_hash text NOT NULL CHECK(basis_hash ~ '^[0-9a-f]{64}$'),
 execution_result_json jsonb NOT NULL,
 target_entry_id text NOT NULL CHECK(length(target_entry_id)>0),
 target_source_kind text NOT NULL CHECK(target_source_kind='hometax_invoice'),
 target_source_id text NOT NULL CHECK(length(target_source_id)>0),
 request_id text NOT NULL UNIQUE CHECK(length(request_id)>0),
 actor_user_id text NOT NULL CHECK(length(actor_user_id)>0),
 created_at text NOT NULL CHECK(length(created_at)>0),
 apply_xid xid8 NOT NULL DEFAULT pg_current_xact_id(),
 UNIQUE(recognition_id,review_version),
 UNIQUE(review_id,recognition_id,review_version),
 UNIQUE(review_id,recognition_id,request_id,actor_user_id),
 UNIQUE(recognition_id,apply_xid),
 FOREIGN KEY(previous_review_id) REFERENCES recognition_review_revisions(review_id),
 CHECK((review_version=1)=(previous_review_id IS NULL))
);
CREATE TABLE IF NOT EXISTS recognition_review_requests (
 request_id text PRIMARY KEY CHECK(length(request_id)>0),
 action text NOT NULL CHECK(action='apply'),
 recognition_id text NOT NULL,
 review_id text NOT NULL UNIQUE,
 actor_user_id text NOT NULL CHECK(length(actor_user_id)>0),
 payload_hash text NOT NULL CHECK(payload_hash ~ '^[0-9a-f]{64}$'),
 result_json jsonb NOT NULL,
 created_at text NOT NULL CHECK(length(created_at)>0),
 FOREIGN KEY(review_id,recognition_id,request_id,actor_user_id)
  REFERENCES recognition_review_revisions(review_id,recognition_id,request_id,actor_user_id)
  DEFERRABLE INITIALLY DEFERRED
);
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='transaction_invoice_recognitions'::regclass AND conname='r1_recognition_review_pointer') THEN
  ALTER TABLE transaction_invoice_recognitions ADD CONSTRAINT r1_recognition_review_pointer
   CHECK(review_version>=0 AND ((review_version=0 AND applied_review_id IS NULL) OR (review_version>0 AND applied_review_id IS NOT NULL)));
 END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='transaction_invoice_recognitions'::regclass AND conname='r1_recognition_review_fk') THEN
  ALTER TABLE transaction_invoice_recognitions ADD CONSTRAINT r1_recognition_review_fk
   FOREIGN KEY(applied_review_id,recognition_id,review_version)
   REFERENCES recognition_review_revisions(review_id,recognition_id,review_version) DEFERRABLE INITIALLY DEFERRED;
 END IF;
END $$;

CREATE OR REPLACE FUNCTION r1_require(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION '%',message USING ERRCODE='23514'; END IF; END $$;

CREATE OR REPLACE FUNCTION r1_json_keys(value jsonb,keys text[]) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
 IF jsonb_typeof(value) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
 RETURN (SELECT array_agg(k ORDER BY k COLLATE "C") FROM jsonb_object_keys(value) k)
  IS NOT DISTINCT FROM (SELECT array_agg(k ORDER BY k COLLATE "C") FROM unnest(keys) k);
END $$;
CREATE OR REPLACE FUNCTION r1_json_integer(value jsonb,low_value numeric,high_value numeric) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE n numeric;
BEGIN
 IF jsonb_typeof(value) IS DISTINCT FROM 'number' THEN RETURN false; END IF;
 n:=(value#>>'{}')::numeric;
 RETURN n=trunc(n) AND n BETWEEN low_value AND high_value;
END $$;

CREATE OR REPLACE FUNCTION r1_recognition_projection(r transaction_invoice_recognitions) RETURNS jsonb LANGUAGE sql STABLE AS $$
 SELECT jsonb_build_object('schemaVersion','r1-recognition-projection-v1',
  'recognitionId',r.recognition_id,'canonicalInvoiceKey',r.canonical_invoice_key,'sourceKind',r.source_kind,'sourceId',r.source_id,
  'sourceHash',r.source_hash,'sourceSnapshotText',r.source_snapshot::text,'expenseAccount',r.expense_account,
  'reason',r.reason,'evidence',r.evidence,'creationRequestId',r.request_id,'createdBy',r.created_by,'createdAt',r.created_at,
  'appliedReviewId',r.applied_review_id,'reviewVersion',r.review_version)
$$;
CREATE OR REPLACE FUNCTION r1_recognition_projection_hash(r transaction_invoice_recognitions) RETURNS text LANGUAGE sql STABLE AS $$
 SELECT vat_followup_hash_v2(r1_recognition_projection(r))
$$;

CREATE OR REPLACE FUNCTION r1_assert_recognition_current(p_recognition_id text) RETURNS jsonb LANGUAGE plpgsql STABLE AS $$
DECLARE r transaction_invoice_recognitions%ROWTYPE; v recognition_review_revisions%ROWTYPE;
BEGIN
 SELECT * INTO r FROM transaction_invoice_recognitions WHERE recognition_id=p_recognition_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'R1 recognition missing' USING ERRCODE='55000'; END IF;
 SELECT * INTO v FROM recognition_review_revisions WHERE recognition_id=p_recognition_id ORDER BY review_version DESC LIMIT 1;
 IF r.review_version=0 AND r.applied_review_id IS NULL AND NOT FOUND THEN RETURN NULL; END IF;
 IF v.review_id IS NULL OR r.review_version<=0 OR r.applied_review_id IS DISTINCT FROM v.review_id
  OR r.review_version IS DISTINCT FROM v.review_version OR r1_recognition_projection(r) IS DISTINCT FROM v.after_projection_json
  OR r1_recognition_projection_hash(r) IS DISTINCT FROM v.after_projection_hash
  OR vat_followup_hash_v2(v.basis_json) IS DISTINCT FROM v.basis_hash THEN
  RAISE EXCEPTION 'R1 recognition current review inconsistent' USING ERRCODE='55000';
 END IF;
 RETURN jsonb_build_object('schemaVersion',1,'reviewId',v.review_id,'reviewVersion',v.review_version,'basisHash',v.basis_hash);
END $$;

-- The legacy branch drops only the new keys after verifying absence of history.
-- Existing 233 proof remains version 1; reviewed rows explicitly carry review identity.
CREATE OR REPLACE FUNCTION r1_recognition_followup_projection(r transaction_invoice_recognitions) RETURNS jsonb LANGUAGE plpgsql STABLE AS $$
DECLARE review jsonb;
BEGIN
 review:=r1_assert_recognition_current(r.recognition_id);
 IF review IS NULL THEN RETURN to_jsonb(r)-'applied_review_id'-'review_version'; END IF;
 RETURN to_jsonb(r)||jsonb_build_object('review',review);
END $$;

CREATE OR REPLACE FUNCTION vat_followup_database_proof(card_id text,invoice_id text,
 legacy_return_id text DEFAULT NULL,basis_snapshot_id text DEFAULT NULL,fact_revision_id text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE card_row jsonb; invoice_row jsonb; official text; proof jsonb;
BEGIN
 SELECT to_jsonb(t) INTO STRICT card_row FROM card_transactions t WHERE t.card_txn_id=vat_followup_database_proof.card_id;
 SELECT to_jsonb(t),btrim(t.nts_send_key) INTO STRICT invoice_row,official FROM hometax_tax_invoices t WHERE t.hti_id=vat_followup_database_proof.invoice_id;
 proof:=jsonb_build_object('card',card_row,'invoice',invoice_row,
  'cardReview',(SELECT to_jsonb(r) FROM card_tax_reviews r WHERE r.card_txn_id=vat_followup_database_proof.card_id),
  'merchant',(SELECT to_jsonb(m) FROM card_merchant_corrections m WHERE m.card_txn_id=vat_followup_database_proof.card_id ORDER BY m.version DESC LIMIT 1),
  'refundPeers',COALESCE((SELECT jsonb_agg(jsonb_build_object('source',to_jsonb(t),'review',to_jsonb(r)) ORDER BY t.card_txn_id)
   FROM card_transactions t LEFT JOIN card_tax_reviews r ON r.card_txn_id=t.card_txn_id
   WHERE r.original_card_txn_id=vat_followup_database_proof.card_id OR (t.card_id=card_row->>'card_id' AND NULLIF(t.approval_num,'')=NULLIF(card_row->>'approval_num',''))),'[]'::jsonb),
  'hometaxAliases',COALESCE((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.hti_id) FROM hometax_tax_invoices t WHERE btrim(t.nts_send_key)=official),'[]'::jsonb),
  'appAliases',COALESCE((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.invoice_id) FROM tax_invoices t WHERE btrim(t.nts_send_key)=official),'[]'::jsonb),
  'links',COALESCE((SELECT jsonb_agg(to_jsonb(l) ORDER BY l.link_id) FROM transaction_links l
   WHERE (l.left_kind='card' AND l.left_id=vat_followup_database_proof.card_id) OR (l.right_kind='hometax' AND l.right_id=vat_followup_database_proof.invoice_id)
     OR l.right_snapshot->>'canonicalKey'='invoice:'||official),'[]'::jsonb),
  'recognitions',COALESCE((SELECT jsonb_agg(r1_recognition_followup_projection(r) ORDER BY r.recognition_id) FROM transaction_invoice_recognitions r
   WHERE r.canonical_invoice_key='invoice:'||official),'[]'::jsonb),
  'legacy',(SELECT to_jsonb(r) FROM vat_returns r WHERE r.return_id=vat_followup_database_proof.legacy_return_id),
  'basis',(SELECT to_jsonb(b) FROM vat_filing_basis_snapshots b WHERE b.snapshot_id=vat_followup_database_proof.basis_snapshot_id),
  'fact',(SELECT to_jsonb(f) FROM vat_filing_fact_revisions f WHERE f.revision_id=vat_followup_database_proof.fact_revision_id),
  'consumptions',COALESCE((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.consumption_id) FROM vat_filing_basis_consumptions c
   WHERE c.snapshot_id=vat_followup_database_proof.basis_snapshot_id AND c.revision_id=vat_followup_database_proof.fact_revision_id),'[]'::jsonb));
 RETURN jsonb_build_object('version','vat-followup-db-v1','digest',vat_followup_hash(proof));
END $$;

CREATE OR REPLACE FUNCTION r1_revision_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE old_r transaction_invoice_recognitions%ROWTYPE; p jsonb; b jsonb; e jsonb; s jsonb; snap jsonb; item jsonb;
 h hometax_tax_invoices%ROWTYPE; subject_r vat_filing_subject_revisions%ROWTYPE;
 old_p jsonb; prior recognition_review_revisions%ROWTYPE; line_count integer; expected_tax numeric; expected_total numeric;
BEGIN
 PERFORM r1_require(NEW.apply_xid=pg_current_xact_id(),'R1 apply transaction identity mismatch');
 SELECT * INTO old_r FROM transaction_invoice_recognitions WHERE recognition_id=NEW.recognition_id FOR UPDATE;
 PERFORM r1_require(FOUND,'R1 existing recognition required');
 PERFORM r1_assert_recognition_current(NEW.recognition_id);
 old_p:=r1_recognition_projection(old_r); p:=NEW.after_projection_json; b:=NEW.basis_json; e:=NEW.execution_result_json;
 PERFORM r1_require(NEW.review_version=old_r.review_version+1 AND NEW.previous_review_id IS NOT DISTINCT FROM old_r.applied_review_id,'R1 review lineage mismatch');
 PERFORM r1_require(NEW.before_projection_json=old_p AND NEW.before_projection_hash=r1_recognition_projection_hash(old_r),'R1 before projection CAS mismatch');
 PERFORM r1_require(r1_json_keys(p,ARRAY['schemaVersion','recognitionId','canonicalInvoiceKey','sourceKind','sourceId','sourceHash','sourceSnapshotText','expenseAccount','reason','evidence','creationRequestId','createdBy','createdAt','appliedReviewId','reviewVersion']),'R1 after projection keys invalid');
 PERFORM r1_require(p->>'schemaVersion'='r1-recognition-projection-v1' AND r1_json_integer(p->'reviewVersion',1,2147483647)
  AND (p->>'reviewVersion')::integer=NEW.review_version AND p->>'appliedReviewId'=NEW.review_id,'R1 after projection review invalid');
 PERFORM r1_require((p-ARRAY['sourceHash','sourceSnapshotText','reason','evidence','appliedReviewId','reviewVersion'])
  =(old_p-ARRAY['sourceHash','sourceSnapshotText','reason','evidence','appliedReviewId','reviewVersion']),'R1 stable recognition identity changed');
 PERFORM r1_require(jsonb_typeof(p->'sourceHash')='string' AND p->>'sourceHash' ~ '^[0-9a-f]{64}$'
  AND jsonb_typeof(p->'sourceSnapshotText')='string' AND jsonb_typeof(p->'reason')='string' AND jsonb_typeof(p->'evidence')='string','R1 after projection type invalid');
 PERFORM r1_require(vat_followup_hash_v2(p)=NEW.after_projection_hash,'R1 after projection hash mismatch');
 PERFORM r1_require(r1_json_keys(b,ARRAY['schemaVersion','recognitionId','reviewId','reviewVersion','previousReviewId','beforeProjectionHash','afterProjectionHash','representative','dates','subjectProof','reviewDocument','reason','requestId','actorUserId','reviewConfirmed']),'R1 basis keys invalid');
 PERFORM r1_require(b->>'schemaVersion'='r1-review-basis-v1' AND b->>'recognitionId'=NEW.recognition_id
  AND b->>'reviewId'=NEW.review_id AND b->'reviewVersion'=to_jsonb(NEW.review_version)
  AND b->'previousReviewId'=COALESCE(to_jsonb(NEW.previous_review_id),'null'::jsonb)
  AND b->>'beforeProjectionHash'=NEW.before_projection_hash AND b->>'afterProjectionHash'=NEW.after_projection_hash
  AND b->>'requestId'=NEW.request_id AND b->>'actorUserId'=NEW.actor_user_id AND b->'reviewConfirmed'='true'::jsonb
  AND vat_followup_hash_v2(b)=NEW.basis_hash,'R1 basis metadata/hash mismatch');
 PERFORM r1_require(r1_json_keys(b->'representative',ARRAY['sourceKind','sourceId','canonicalKey','journalKind','journalId'])
  AND b->'representative'=jsonb_build_object('sourceKind',old_r.source_kind,'sourceId',old_r.source_id,
   'canonicalKey',old_r.canonical_invoice_key,'journalKind',NEW.target_source_kind,'journalId',NEW.target_source_id)
  AND old_r.source_kind='hometax' AND NEW.target_source_id=old_r.source_id,'R1 representative not supported');
 PERFORM r1_require(r1_json_keys(b->'dates',ARRAY['accountingDate','taxDate'])
  AND b->'dates'->>'accountingDate'=old_r.source_snapshot->>'date' AND b->'dates'->>'taxDate'=old_r.source_snapshot->>'taxDate'
  AND b->'dates'->>'accountingDate'=b->'dates'->>'taxDate','R1 accounting/VAT dates changed');
 SELECT * INTO h FROM hometax_tax_invoices WHERE hti_id=old_r.source_id FOR SHARE;
 PERFORM r1_require(FOUND AND h.direction='purchase' AND COALESCE(h.excluded,0)=0 AND COALESCE(h.modify_code,'')=''
  AND h.write_date::text=b->'dates'->>'accountingDate' AND 'invoice:'||btrim(h.nts_send_key)=old_r.canonical_invoice_key
  AND h.amount_total>0 AND h.tax_total>=0 AND h.total_amount=h.amount_total+h.tax_total
  AND h.vat_deductible IN (0,1),'R1 current HTI source unsupported');
 snap:=(p->>'sourceSnapshotText')::jsonb;
 PERFORM r1_require(jsonb_typeof(snap)='object' AND snap::text=p->>'sourceSnapshotText'
  AND snap->>'sourceHash'=p->>'sourceHash' AND snap->>'kind'='hometax' AND snap->>'id'=h.hti_id
  AND snap->>'canonicalKey'=old_r.canonical_invoice_key AND snap->>'journalKind'=NEW.target_source_kind AND snap->>'journalId'=NEW.target_source_id
  AND snap->>'date'=b->'dates'->>'accountingDate' AND snap->>'taxDate'=b->'dates'->>'taxDate'
  AND snap->>'direction'='purchase' AND snap->'vatDeductible'=to_jsonb(h.vat_deductible)
  AND r1_json_integer(snap->'supply',1,9007199254740991) AND r1_json_integer(snap->'tax',0,9007199254740991)
  AND r1_json_integer(snap->'total',1,9007199254740991)
  AND (snap->>'supply')::numeric=h.amount_total AND (snap->>'tax')::numeric=h.tax_total AND (snap->>'total')::numeric=h.total_amount,'R1 current source projection mismatch');
 PERFORM r1_require(NOT EXISTS(SELECT 1 FROM transaction_links l WHERE l.state='active' AND
  (l.canonical_invoice_key=old_r.canonical_invoice_key OR l.right_snapshot->>'canonicalKey'=old_r.canonical_invoice_key
   OR (l.right_kind='hometax' AND l.right_id=old_r.source_id))),'R1 active relationship is unsupported');
 PERFORM r1_require(EXISTS(SELECT 1 FROM journal_accounts a WHERE a.account_code=old_r.expense_account AND a.is_active=1),'R1 expense account unavailable');
 PERFORM r1_require(r1_json_keys(b->'reviewDocument',ARRAY['documentId','subjectId','evidenceRef','evidenceHash','location'])
  AND b->'reviewDocument'->>'evidenceRef'='vat-document:'||(b->'reviewDocument'->>'documentId')
  AND length(btrim(b->'reviewDocument'->>'location'))>0
  AND vat_followup_server_document(b->'reviewDocument'->>'evidenceRef',b->'reviewDocument'->>'evidenceHash',b->'reviewDocument'->>'subjectId'),'R1 review document invalid');
 PERFORM r1_require(jsonb_typeof(b->'reason')='string' AND length(btrim(b->>'reason'))>0 AND p->>'reason'=btrim(b->>'reason')
  AND p->>'evidence'=(b->'reviewDocument'->>'evidenceRef')||' / '||(b->'reviewDocument'->>'location'),'R1 review reason/evidence mismatch');
 PERFORM r1_require(jsonb_typeof(b->'subjectProof')='array' AND jsonb_array_length(b->'subjectProof')=1,'R1 subject proof must cover the supported business date');
 FOR item IN SELECT value FROM jsonb_array_elements(b->'subjectProof') LOOP
  PERFORM r1_require(r1_json_keys(item,ARRAY['date','subjectId','revisionId','corpNum','revisionHash','evidenceRef','evidenceHash'])
   AND item->>'date'=b->'dates'->>'accountingDate' AND item->>'subjectId'=b->'reviewDocument'->>'subjectId'
   AND jsonb_typeof(item->'corpNum')='string' AND item->>'corpNum' ~ '^[0-9]{10}$' AND item->>'corpNum'<>'0000000000','R1 subject proof metadata invalid');
  SELECT * INTO subject_r FROM vat_filing_subject_revisions WHERE revision_id=item->>'revisionId' AND subject_id=item->>'subjectId';
  PERFORM r1_require(FOUND AND vat_followup_hash_v2(subject_r.payload_json)=item->>'revisionHash'
   AND subject_r.payload_json->>'state'='verified' AND subject_r.payload_json->>'entityType'='corporation'
   AND subject_r.payload_json->>'vatRegime'='general' AND subject_r.payload_json->>'filingUnit'='single_business_place'
   AND subject_r.payload_json->>'corpNum'=item->>'corpNum'
   AND subject_r.payload_json->>'evidenceRef'=item->>'evidenceRef' AND subject_r.payload_json->>'evidenceHash'=item->>'evidenceHash'
   AND vat_followup_server_document(item->>'evidenceRef',item->>'evidenceHash',item->>'subjectId'),'R1 subject document or revision invalid');
 END LOOP;
 PERFORM r1_require(r1_json_keys(e,ARRAY['schemaVersion','entry','lines','snapshot']) AND e->'schemaVersion'='1'::jsonb,'R1 execution result shape invalid');
 PERFORM r1_require(r1_json_keys(e->'entry',ARRAY['entry_id','entry_date','source_kind','source_id','description','party_name','status','doc_id','confirmed_by','confirmed_at','memo','created_at','updated_at'])
  AND e->'entry'->>'entry_id'=NEW.target_entry_id AND e->'entry'->>'source_kind'=NEW.target_source_kind AND e->'entry'->>'source_id'=NEW.target_source_id
  AND e->'entry'->>'entry_date'=b->'dates'->>'accountingDate' AND e->'entry'->>'status'='auto'
  AND e->'entry'->'confirmed_by'='null'::jsonb AND e->'entry'->'confirmed_at'='null'::jsonb
  AND e->'entry'->'memo'='null'::jsonb AND e->'entry'->'updated_at'='null'::jsonb
  AND e->'entry'->>'created_at'=NEW.created_at,'R1 execution entry mismatch');
 PERFORM r1_require(NEW.target_entry_id='je-'||substr(encode(sha256(convert_to(NEW.target_source_kind||':'||NEW.target_source_id,'UTF8')),'hex'),1,12),'R1 target entry identity mismatch');
 PERFORM r1_require(NOT EXISTS(SELECT 1 FROM journal_entries WHERE entry_id=NEW.target_entry_id AND status IN ('confirmed','excluded')),'R1 protected journal entry');
 PERFORM r1_require(r1_json_keys(e->'snapshot',ARRAY['entry_id','snapshot_version','source_hash','source_json','captured_at'])
  AND e->'snapshot'->>'entry_id'=NEW.target_entry_id AND e->'snapshot'->'snapshot_version'='1'::jsonb
  AND e->'snapshot'->>'captured_at'=NEW.created_at
  AND e->'snapshot'->>'source_hash'=vat_followup_hash_v2(e->'snapshot'->'source_json'),'R1 execution snapshot mismatch');
 s:=e->'snapshot'->'source_json';
 PERFORM r1_require(s->>'sourceKind'=NEW.target_source_kind AND s->>'sourceId'=NEW.target_source_id AND s->>'entryDate'=b->'dates'->>'accountingDate'
  AND s->'evidence'->>'invoice'=p->>'sourceHash'
  AND s->'evidence'->'recognition'->>'id'=NEW.recognition_id AND s->'evidence'->'recognition'->>'sourceHash'=p->>'sourceHash'
  AND s->'evidence'->'recognition'->'review'=jsonb_build_object('schemaVersion',1,'reviewId',NEW.review_id,'reviewVersion',NEW.review_version,'basisHash',NEW.basis_hash),'R1 journal review evidence mismatch');
 expected_tax:=CASE WHEN h.vat_deductible=1 THEN h.tax_total ELSE 0 END; expected_total:=h.total_amount;
 PERFORM r1_require(jsonb_typeof(e->'lines')='array' AND jsonb_array_length(e->'lines')=CASE WHEN expected_tax>0 THEN 3 ELSE 2 END,'R1 journal line count mismatch');
 line_count:=0;
 FOR item IN SELECT value FROM jsonb_array_elements(e->'lines') LOOP
  line_count:=line_count+1;
  PERFORM r1_require(r1_json_keys(item,ARRAY['line_id','entry_id','line_no','account_code','debit','credit','memo'])
   AND item->>'entry_id'=NEW.target_entry_id AND item->'line_no'=to_jsonb(line_count)
   AND item->>'line_id'='jl-'||substr(encode(sha256(convert_to(NEW.target_entry_id||':'||line_count::text,'UTF8')),'hex'),1,12)
   AND r1_json_integer(item->'debit',0,9007199254740991) AND r1_json_integer(item->'credit',0,9007199254740991),'R1 execution line metadata invalid');
  PERFORM r1_require(item->>'account_code'=CASE WHEN line_count=1 THEN old_r.expense_account WHEN line_count=2 AND expected_tax>0 THEN '135' ELSE '251' END
   AND (item->>'debit')::numeric=CASE WHEN line_count=1 THEN expected_total-expected_tax WHEN line_count=2 AND expected_tax>0 THEN expected_tax ELSE 0 END
   AND (item->>'credit')::numeric=CASE WHEN line_count=jsonb_array_length(e->'lines') THEN expected_total ELSE 0 END,'R1 execution line amount mismatch');
 END LOOP;
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION r1_recognition_write_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v recognition_review_revisions%ROWTYPE;
BEGIN
 IF TG_OP='INSERT' THEN
  PERFORM r1_require(NEW.review_version=0 AND NEW.applied_review_id IS NULL,'R1 reviewed recognition cannot be inserted'); RETURN NEW;
 ELSIF TG_OP='DELETE' THEN
  PERFORM r1_require(OLD.review_version=0 AND OLD.applied_review_id IS NULL AND NOT EXISTS(SELECT 1 FROM recognition_review_revisions WHERE recognition_id=OLD.recognition_id),'R1 reviewed recognition cannot be deleted'); RETURN OLD;
 END IF;
 IF to_jsonb(NEW)=to_jsonb(OLD) THEN PERFORM r1_assert_recognition_current(OLD.recognition_id); RETURN NEW; END IF;
 SELECT * INTO v FROM recognition_review_revisions WHERE recognition_id=OLD.recognition_id AND apply_xid=pg_current_xact_id();
 IF NOT FOUND AND OLD.review_version=0 AND OLD.applied_review_id IS NULL AND NEW.review_version=0 AND NEW.applied_review_id IS NULL
  AND NOT EXISTS(SELECT 1 FROM recognition_review_revisions WHERE recognition_id=OLD.recognition_id) THEN RETURN NEW; END IF;
 PERFORM r1_require(v.review_id IS NOT NULL AND r1_recognition_projection(OLD)=v.before_projection_json
  AND r1_recognition_projection(NEW)=v.after_projection_json AND r1_recognition_projection_hash(NEW)=v.after_projection_hash,'R1 recognition update requires exact current-transaction revision');
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION r1_history_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'R1 review history is immutable' USING ERRCODE='23514'; END $$;

CREATE OR REPLACE FUNCTION r1_assert_recognition_agreement(p_recognition_id text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE v recognition_review_revisions%ROWTYPE; request_row recognition_review_requests%ROWTYPE; actual jsonb; expected_result jsonb; expected_audit jsonb; count_audit integer;
BEGIN
 SELECT * INTO v FROM recognition_review_revisions WHERE recognition_id=p_recognition_id AND apply_xid=pg_current_xact_id();
 IF NOT FOUND THEN
  IF EXISTS(SELECT 1 FROM transaction_invoice_recognitions WHERE recognition_id=p_recognition_id) THEN PERFORM r1_assert_recognition_current(p_recognition_id); END IF;
  RETURN;
 END IF;
 BEGIN
  PERFORM r1_assert_recognition_current(p_recognition_id);
 EXCEPTION WHEN SQLSTATE '55000' THEN
  RAISE EXCEPTION 'R1 projection agreement failed' USING ERRCODE='23514';
 END;
 SELECT jsonb_build_object('schemaVersion',1,'entry',to_jsonb(e),
  'lines',COALESCE((SELECT jsonb_agg(to_jsonb(l) ORDER BY l.line_no,l.line_id) FROM journal_lines l WHERE l.entry_id=v.target_entry_id),'[]'::jsonb),
  'snapshot',(SELECT to_jsonb(s) FROM journal_source_snapshots s WHERE s.entry_id=v.target_entry_id))
  INTO actual FROM journal_entries e WHERE e.entry_id=v.target_entry_id;
 PERFORM r1_require(actual IS NOT NULL AND actual=v.execution_result_json,'R1 exact journal execution agreement failed');
 expected_result:=jsonb_build_object('recognitionId',v.recognition_id,'reviewId',v.review_id,'reviewVersion',v.review_version,
  'basisHash',v.basis_hash,'entryId',v.target_entry_id,'sourceHash',v.execution_result_json->'snapshot'->>'source_hash','status','restored','replayed',false);
 SELECT * INTO request_row FROM recognition_review_requests WHERE request_id=v.request_id;
 PERFORM r1_require(FOUND AND request_row.review_id=v.review_id AND request_row.recognition_id=v.recognition_id
  AND request_row.actor_user_id=v.actor_user_id AND request_row.action='apply' AND request_row.result_json=expected_result,'R1 request agreement failed');
 expected_audit:=expected_result-'status'-'replayed';
 SELECT count(*) INTO count_audit FROM audit_log a WHERE a.action='finance_recognition_review' AND a.target_table='recognition_review_revisions'
  AND a.target_id=v.review_id AND a.actor_user_id=v.actor_user_id AND a.before_json=v.before_projection_json AND a.after_json=expected_audit;
 PERFORM r1_require(count_audit=1,'R1 audit agreement failed');
END $$;

CREATE OR REPLACE FUNCTION r1_row_agreement() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE old_key text; new_key text; v record;
BEGIN
 IF TG_TABLE_NAME IN ('transaction_invoice_recognitions','recognition_review_revisions','recognition_review_requests') THEN
  IF TG_OP<>'INSERT' THEN old_key:=OLD.recognition_id; END IF;
  IF TG_OP<>'DELETE' THEN new_key:=NEW.recognition_id; END IF;
  IF old_key IS NOT NULL THEN PERFORM r1_assert_recognition_agreement(old_key); END IF;
  IF new_key IS NOT NULL AND new_key IS DISTINCT FROM old_key THEN PERFORM r1_assert_recognition_agreement(new_key); END IF;
 ELSE
  IF TG_OP<>'INSERT' THEN old_key:=CASE WHEN TG_TABLE_NAME='audit_log' THEN to_jsonb(OLD)->>'target_id' ELSE to_jsonb(OLD)->>'entry_id' END; END IF;
  IF TG_OP<>'DELETE' THEN new_key:=CASE WHEN TG_TABLE_NAME='audit_log' THEN to_jsonb(NEW)->>'target_id' ELSE to_jsonb(NEW)->>'entry_id' END; END IF;
  FOR v IN SELECT recognition_id FROM recognition_review_revisions WHERE apply_xid=pg_current_xact_id()
   AND CASE WHEN TG_TABLE_NAME='audit_log' THEN review_id IN (old_key,new_key) ELSE target_entry_id IN (old_key,new_key) END LOOP
   PERFORM r1_assert_recognition_agreement(v.recognition_id);
  END LOOP;
 END IF;
 RETURN NULL;
END $$;

CREATE OR REPLACE FUNCTION r1_truncate_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_TABLE_NAME IN ('recognition_review_revisions','recognition_review_requests')
  OR (TG_TABLE_NAME='transaction_invoice_recognitions' AND EXISTS(SELECT 1 FROM recognition_review_revisions))
  OR EXISTS(SELECT 1 FROM recognition_review_revisions WHERE apply_xid=pg_current_xact_id()) THEN
  RAISE EXCEPTION 'R1 protected transaction/history cannot be truncated' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $$;

DROP TRIGGER IF EXISTS r1_revision_insert ON recognition_review_revisions;
CREATE TRIGGER r1_revision_insert BEFORE INSERT ON recognition_review_revisions FOR EACH ROW EXECUTE FUNCTION r1_revision_guard();
DROP TRIGGER IF EXISTS r1_recognition_write ON transaction_invoice_recognitions;
CREATE TRIGGER r1_recognition_write BEFORE INSERT OR UPDATE OR DELETE ON transaction_invoice_recognitions FOR EACH ROW EXECUTE FUNCTION r1_recognition_write_guard();
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['recognition_review_revisions','recognition_review_requests'] LOOP
  EXECUTE format('DROP TRIGGER IF EXISTS r1_immutable ON %I',t);
  EXECUTE format('CREATE TRIGGER r1_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION r1_history_immutable()',t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['transaction_invoice_recognitions','recognition_review_revisions','recognition_review_requests','journal_entries','journal_lines','journal_source_snapshots','audit_log'] LOOP
  EXECUTE format('DROP TRIGGER IF EXISTS r1_agreement ON %I',t);
  EXECUTE format('CREATE CONSTRAINT TRIGGER r1_agreement AFTER INSERT OR UPDATE OR DELETE ON %I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION r1_row_agreement()',t);
  EXECUTE format('DROP TRIGGER IF EXISTS r1_no_truncate ON %I',t);
  EXECUTE format('CREATE TRIGGER r1_no_truncate BEFORE TRUNCATE ON %I FOR EACH STATEMENT EXECUTE FUNCTION r1_truncate_guard()',t);
 END LOOP;
END $$;

CREATE OR REPLACE FUNCTION r1_installation_catalog(p_schema text,p_relations text[],p_strict_relations text[])
RETURNS jsonb LANGUAGE sql STABLE AS $$
 SELECT jsonb_build_object(
 'relations',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind::text,
  'rowSecurity',c.relrowsecurity,'forceRowSecurity',c.relforcerowsecurity,
  'policies',COALESCE((SELECT jsonb_agg(p.polname ORDER BY p.polname COLLATE "C") FROM pg_catalog.pg_policy p WHERE p.polrelid=c.oid),'[]'::jsonb)) ORDER BY c.relname COLLATE "C")
  FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname=p_schema AND c.relname=ANY(p_relations)),'[]'::jsonb),
 'structures',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',c.relname,
  'columns',COALESCE((SELECT jsonb_agg(jsonb_build_object('position',a.attnum,'name',a.attname,
   'type',pg_catalog.format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,
   'default',pg_catalog.pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity::text,'generated',a.attgenerated::text,
   'collation',CASE WHEN a.attcollation=0 THEN NULL ELSE (SELECT cn.nspname||'.'||co.collname FROM pg_catalog.pg_collation co JOIN pg_catalog.pg_namespace cn ON cn.oid=co.collnamespace WHERE co.oid=a.attcollation) END)
   ORDER BY a.attnum) FROM pg_catalog.pg_attribute a LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
   WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'[]'::jsonb),
  'constraints',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',k.conname,'type',k.contype::text,
   'definition',pg_catalog.pg_get_constraintdef(k.oid,true),'validated',k.convalidated,'deferrable',k.condeferrable,'initiallyDeferred',k.condeferred,
   'target',CASE WHEN k.confrelid=0 THEN NULL ELSE (SELECT CASE WHEN tn.nspname=p_schema THEN '<self>' ELSE tn.nspname END||'.'||tc.relname FROM pg_catalog.pg_class tc JOIN pg_catalog.pg_namespace tn ON tn.oid=tc.relnamespace WHERE tc.oid=k.confrelid) END,
   'keys',k.conkey,'targetKeys',k.confkey,'updateAction',k.confupdtype::text,'deleteAction',k.confdeltype::text,'match',k.confmatchtype::text)
   ORDER BY k.conname COLLATE "C") FROM pg_catalog.pg_constraint k WHERE k.conrelid=c.oid),'[]'::jsonb),
  'indexes',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',ic.relname,'accessMethod',am.amname,
   'unique',i.indisunique,'primary',i.indisprimary,'exclusion',i.indisexclusion,'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive,
   'immediate',i.indimmediate,'nullsNotDistinct',i.indnullsnotdistinct,'keyCount',i.indnkeyatts,'attributeCount',i.indnatts,
   'columns',(SELECT jsonb_agg(pg_catalog.pg_get_indexdef(i.indexrelid,pos,true) ORDER BY pos) FROM generate_series(1,i.indnatts) pos),
   'options',i.indoption::text,'predicate',pg_catalog.pg_get_expr(i.indpred,i.indrelid),
   'operatorClasses',(SELECT jsonb_agg(onsp.nspname||'.'||op.opcname ORDER BY x.ord) FROM unnest(i.indclass::oid[]) WITH ORDINALITY x(opoid,ord) JOIN pg_catalog.pg_opclass op ON op.oid=x.opoid JOIN pg_catalog.pg_namespace onsp ON onsp.oid=op.opcnamespace))
   ORDER BY ic.relname COLLATE "C") FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class ic ON ic.oid=i.indexrelid JOIN pg_catalog.pg_am am ON am.oid=ic.relam WHERE i.indrelid=c.oid),'[]'::jsonb),
  'triggers',COALESCE((SELECT jsonb_agg(x.definition ORDER BY x.definition::text COLLATE "C") FROM
   (SELECT jsonb_build_object('name',CASE WHEN t.tgisinternal THEN NULL ELSE t.tgname END,'internal',t.tgisinternal,
    'type',t.tgtype,'enabled',t.tgenabled::text,'updateColumns',t.tgattr::text,'arguments',encode(t.tgargs,'hex'),
    'when',pg_catalog.pg_get_expr(t.tgqual,t.tgrelid),'deferrable',t.tgdeferrable,'initiallyDeferred',t.tginitdeferred,
    'oldTransition',t.tgoldtable,'newTransition',t.tgnewtable,
    'function',CASE WHEN fn.nspname=p_schema THEN '<self>' ELSE fn.nspname END||'.'||f.proname||'('||pg_catalog.oidvectortypes(f.proargtypes)||')',
    'constraint',CASE WHEN t.tgconstraint=0 THEN NULL ELSE (SELECT jsonb_build_object('name',co.conname,'relation',rc.relname,'schema',CASE WHEN rn.nspname=p_schema THEN '<self>' ELSE rn.nspname END) FROM pg_catalog.pg_constraint co JOIN pg_catalog.pg_class rc ON rc.oid=co.conrelid JOIN pg_catalog.pg_namespace rn ON rn.oid=rc.relnamespace WHERE co.oid=t.tgconstraint) END) AS definition
    FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_proc f ON f.oid=t.tgfoid JOIN pg_catalog.pg_namespace fn ON fn.oid=f.pronamespace WHERE t.tgrelid=c.oid) x),'[]'::jsonb),
  'rules',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',rw.rulename,'type',rw.ev_type::text,'enabled',rw.ev_enabled::text,'instead',rw.is_instead,
   'definition',pg_catalog.pg_get_ruledef(rw.oid,true)) ORDER BY rw.rulename COLLATE "C") FROM pg_catalog.pg_rewrite rw WHERE rw.ev_class=c.oid),'[]'::jsonb)
 ) ORDER BY c.relname COLLATE "C") FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname=p_schema AND c.relname=ANY(p_strict_relations)),'[]'::jsonb))
$$;

CREATE OR REPLACE FUNCTION finance_assert_r1_definitions(p_schema text) RETURNS jsonb LANGUAGE plpgsql AS $r1$
DECLARE expected jsonb := '{"version":"r1-recognition-installation-v1","postgresMajor":17,"functions":[{"cost":"100","kind":"f","name":"payroll_line_tax_review_invalidate","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE target_entry text; target_item text;\nBEGIN\n  -- Preserve the reviewed input/actor in the events table; never retain a valid flag after editing.\n  IF TG_OP <> ''INSERT'' THEN\n    target_entry := OLD.entry_id; target_item := OLD.item_id;\n    IF target_item IN (''income-tax'',''local-tax'') OR EXISTS(SELECT 1 FROM payroll_item_defs WHERE item_id=target_item AND kind=''pay'') THEN\n      UPDATE payroll_entries SET tax_review=jsonb_build_object(''status'',''pending'',''reason'',''지급액 또는 세액 변경 후 재계산·근거 확인 필요'')\n       WHERE entry_id=target_entry;\n    END IF;\n  END IF;\n  IF TG_OP <> ''DELETE'' THEN\n    target_entry := NEW.entry_id; target_item := NEW.item_id;\n    IF target_item IN (''income-tax'',''local-tax'') OR EXISTS(SELECT 1 FROM payroll_item_defs WHERE item_id=target_item AND kind=''pay'') THEN\n      UPDATE payroll_entries SET tax_review=jsonb_build_object(''status'',''pending'',''reason'',''지급액 또는 세액 변경 후 재계산·근거 확인 필요'')\n       WHERE entry_id=target_entry;\n    END IF;\n  END IF;\n  RETURN NULL;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"payroll_used_item_kind_guard","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nBEGIN\n  IF NEW.kind IS DISTINCT FROM OLD.kind AND EXISTS (\n    SELECT 1 FROM payroll_entry_lines WHERE item_id=OLD.item_id\n  ) THEN\n    RAISE EXCEPTION ''사용 중인 급여 항목은 지급/공제 종류를 변경할 수 없습니다.'' USING ERRCODE=''23514'';\n  END IF;\n  RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"payroll_write_lock","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nBEGIN\n  PERFORM pg_advisory_xact_lock(724301, 1);\n  RETURN NULL;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"prevent_card_merchant_correction_rewrite","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nBEGIN\n  RAISE EXCEPTION ''Card merchant correction history is append-only; record a new correction or withdrawal'' USING ERRCODE=''23514'';\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"r1_assert_recognition_agreement","rows":"0","binary":null,"config":null,"result":"void","source":"\nDECLARE v recognition_review_revisions%ROWTYPE; request_row recognition_review_requests%ROWTYPE; actual jsonb; expected_result jsonb; expected_audit jsonb; count_audit integer;\nBEGIN\n SELECT * INTO v FROM recognition_review_revisions WHERE recognition_id=p_recognition_id AND apply_xid=pg_current_xact_id();\n IF NOT FOUND THEN\n  IF EXISTS(SELECT 1 FROM transaction_invoice_recognitions WHERE recognition_id=p_recognition_id) THEN PERFORM r1_assert_recognition_current(p_recognition_id); END IF;\n  RETURN;\n END IF;\n BEGIN\n  PERFORM r1_assert_recognition_current(p_recognition_id);\n EXCEPTION WHEN SQLSTATE ''55000'' THEN\n  RAISE EXCEPTION ''R1 projection agreement failed'' USING ERRCODE=''23514'';\n END;\n SELECT jsonb_build_object(''schemaVersion'',1,''entry'',to_jsonb(e),\n  ''lin