me'',c.relname,''kind'',c.relkind::text,\n  ''rowSecurity'',c.relrowsecurity,''forceRowSecurity'',c.relforcerowsecurity,\n  ''policies'',COALESCE((SELECT jsonb_agg(p.polname ORDER BY p.polname COLLATE \"C\") FROM pg_catalog.pg_policy p WHERE p.polrelid=c.oid),''[]''::jsonb)) ORDER BY c.relname COLLATE \"C\")\n  FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace\n  WHERE n.nspname=p_schema AND c.relname=ANY(p_relations)),''[]''::jsonb),\n ''structures'',COALESCE((SELECT jsonb_agg(jsonb_build_object(''name'',c.relname,\n  ''columns'',COALESCE((SELECT jsonb_agg(jsonb_build_object(''position'',a.attnum,''name'',a.attname,\n   ''type'',pg_catalog.format_type(a.atttypid,a.atttypmod),''notNull'',a.attnotnull,\n   ''default'',pg_catalog.pg_get_expr(d.adbin,d.adrelid),''identity'',a.attidentity::text,''generated'',a.attgenerated::text,\n   ''collation'',CASE WHEN a.attcollation=0 THEN NULL ELSE (SELECT cn.nspname||''.''||co.collname FROM pg_catalog.pg_collation co JOIN pg_catalog.pg_namespace cn ON cn.oid=co.collnamespace WHERE co.oid=a.attcollation) END)\n   ORDER BY a.attnum) FROM pg_catalog.pg_attribute a LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum\n   WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),''[]''::jsonb),\n  ''constraints'',COALESCE((SELECT jsonb_agg(jsonb_build_object(''name'',k.conname,''type'',k.contype::text,\n   ''definition'',pg_catalog.pg_get_constraintdef(k.oid,true),''validated'',k.convalidated,''deferrable'',k.condeferrable,''initiallyDeferred'',k.condeferred,\n   ''target'',CASE WHEN k.confrelid=0 THEN NULL ELSE (SELECT CASE WHEN tn.nspname=p_schema THEN ''<self>'' ELSE tn.nspname END||''.''||tc.relname FROM pg_catalog.pg_class tc JOIN pg_catalog.pg_namespace tn ON tn.oid=tc.relnamespace WHERE tc.oid=k.confrelid) END,\n   ''keys'',k.conkey,''targetKeys'',k.confkey,''updateAction'',k.confupdtype::text,''deleteAction'',k.confdeltype::text,''match'',k.confmatchtype::text)\n   ORDER BY k.conname COLLATE \"C\") FROM pg_catalog.pg_constraint k WHERE k.conrelid=c.oid),''[]''::jsonb),\n  ''indexes'',COALESCE((SELECT jsonb_agg(jsonb_build_object(''name'',ic.relname,''accessMethod'',am.amname,\n   ''unique'',i.indisunique,''primary'',i.indisprimary,''exclusion'',i.indisexclusion,''valid'',i.indisvalid,''ready'',i.indisready,''live'',i.indislive,\n   ''immediate'',i.indimmediate,''nullsNotDistinct'',i.indnullsnotdistinct,''keyCount'',i.indnkeyatts,''attributeCount'',i.indnatts,\n   ''columns'',(SELECT jsonb_agg(pg_catalog.pg_get_indexdef(i.indexrelid,pos,true) ORDER BY pos) FROM generate_series(1,i.indnatts) pos),\n   ''options'',i.indoption::text,''predicate'',pg_catalog.pg_get_expr(i.indpred,i.indrelid),\n   ''operatorClasses'',(SELECT jsonb_agg(onsp.nspname||''.''||op.opcname ORDER BY x.ord) FROM unnest(i.indclass::oid[]) WITH ORDINALITY x(opoid,ord) JOIN pg_catalog.pg_opclass op ON op.oid=x.opoid JOIN pg_catalog.pg_namespace onsp ON onsp.oid=op.opcnamespace))\n   ORDER BY ic.relname COLLATE \"C\") FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class ic ON ic.oid=i.indexrelid JOIN pg_catalog.pg_am am ON am.oid=ic.relam WHERE i.indrelid=c.oid),''[]''::jsonb),\n  ''triggers'',COALESCE((SELECT jsonb_agg(x.definition ORDER BY x.definition::text COLLATE \"C\") FROM\n   (SELECT jsonb_build_object(''name'',CASE WHEN t.tgisinternal THEN NULL ELSE t.tgname END,''internal'',t.tgisinternal,\n    ''type'',t.tgtype,''enabled'',t.tgenabled::text,''updateColumns'',t.tgattr::text,''arguments'',encode(t.tgargs,''hex''),\n    ''when'',pg_catalog.pg_get_expr(t.tgqual,t.tgrelid),''deferrable'',t.tgdeferrable,''initiallyDeferred'',t.tginitdeferred,\n    ''oldTransition'',t.tgoldtable,''newTransition'',t.tgnewtable,\n    ''function'',CASE WHEN fn.nspname=p_schema THEN ''<self>'' ELSE fn.nspname END||''.''||f.proname||''(''||pg_catalog.oidvectortypes(f.proargtypes)||'')'',\n    ''constraint'',CASE WHEN t.tgconstraint=0 THEN NULL ELSE (SELECT jsonb_build_object(''name'',co.conname,''relation'',rc.relname,''schema'',CASE WHEN rn.nspname=p_schema THEN ''<self>'' ELSE rn.nspname END) FROM pg_catalog.pg_constraint co JOIN pg_catalog.pg_class rc ON rc.oid=co.conrelid JOIN pg_catalog.pg_namespace rn ON rn.oid=rc.relnamespace WHERE co.oid=t.tgconstraint) END) AS definition\n    FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_proc f ON f.oid=t.tgfoid JOIN pg_catalog.pg_namespace fn ON fn.oid=f.pronamespace WHERE t.tgrelid=c.oid) x),''[]''::jsonb),\n  ''rules'',COALESCE((SELECT jsonb_agg(jsonb_build_object(''name'',rw.rulename,''type'',rw.ev_type::text,''enabled'',rw.ev_enabled::text,''instead'',rw.is_instead,\n   ''definition'',pg_catalog.pg_get_ruledef(rw.oid,true)) ORDER BY rw.rulename COLLATE \"C\") FROM pg_catalog.pg_rewrite rw WHERE rw.ev_class=c.oid),''[]''::jsonb)\n ) ORDER BY c.relname COLLATE \"C\") FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace\n WHERE n.nspname=p_schema AND c.relname=ANY(p_strict_relations)),''[]''::jsonb))\n","strict":false,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"p_schema text, p_relations text[], p_strict_relations text[]","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"text, text[], text[]","securityDefiner":false},{"cost":"100","kind":"f","name":"r1_json_integer","rows":"0","binary":null,"config":null,"result":"boolean","source":"\nDECLARE n numeric;\nBEGIN\n IF jsonb_typeof(value) IS DISTINCT FROM ''number'' THEN RETURN false; END IF;\n n:=(value#>>''{}'')::numeric;\n RETURN n=trunc(n) AND n BETWEEN low_value AND high_value;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"value jsonb, low_value numeric, high_value numeric","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"jsonb, numeric, numeric","securityDefiner":false},{"cost":"100","kind":"f","name":"r1_json_keys","rows":"0","binary":null,"config":null,"result":"boolean","source":"\nBEGIN\n IF jsonb_typeof(value) IS DISTINCT FROM ''object'' THEN RETURN false; END IF;\n RETURN (SELECT array_agg(k ORDER BY k COLLATE \"C\") FROM jsonb_object_keys(value) k)\n  IS NOT DISTINCT FROM (SELECT array_agg(k ORDER BY k COLLATE \"C\") FROM unnest(keys) k);\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"value jsonb, keys text[]","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"jsonb, text[]","securityDefiner":false},{"cost":"100","kind":"f","name":"r1_recognition_followup_projection","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE review jsonb;\nBEGIN\n review:=r1_assert_recognition_current(r.recognition_id);\n IF review IS NULL THEN RETURN to_jsonb(r)-''applied_review_id''-''review_version''; END IF;\n RETURN to_jsonb(r)||jsonb_build_object(''review'',review);\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"r transaction_invoice_recognitions","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"transaction_invoice_recognitions","securityDefiner":false},{"cost":"100","kind":"f","name":"r1_recognition_projection","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\n SELECT jsonb_build_object(''schemaVersion'',''r1-recognition-projection-v1'',\n  ''recognitionId'',r.recognition_id,''canonicalInvoiceKey'',r.canonical_invoice_key,''sourceKind'',r.source_kind,''sourceId'',r.source_id,\n  ''sourceHash'',r.source_hash,''sourceSnapshotText'',r.source_snapshot::text,''expenseAccount'',r.expense_account,\n  ''reason'',r.reason,''evidence'',r.evidence,''creationRequestId'',r.request_id,''createdBy'',r.created_by,''createdAt'',r.created_at,\n  ''appliedReviewId'',r.applied_review_id,''reviewVersion'',r.review_version)\n","strict":false,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"r transaction_invoice_recognitions","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"transaction_invoice_recognitions","securityDefiner":false},{"cost":"100","kind":"f","name":"r1_recognition_projection_hash","rows":"0","binary":null,"config":null,"result":"text","source":"\n SELECT vat_followup_hash_v2(r1_recognition_projection(r))\n","strict":false,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"r transaction_invoice_recognitions","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"transaction_invoice_recognitions","securityDefiner":false},{"cost":"100","kind":"f","name":"r1_recognition_write_guard","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE v recognition_review_revisions%ROWTYPE;\nBEGIN\n IF TG_OP=''INSERT'' THEN\n  PERFORM r1_require(NEW.review_version=0 AND NEW.applied_review_id IS NULL,''R1 reviewed recognition cannot be inserted''); RETURN NEW;\n ELSIF TG_OP=''DELETE'' THEN\n  PERFORM r1_require(OLD.review_version=0 AND OLD.applied_review_id IS NULL AND NOT EXISTS(SELECT 1 FROM recognition_review_revisions WHERE recognition_id=OLD.recognition_id),''R1 reviewed recognition cannot be deleted''); RETURN OLD;\n END IF;\n IF to_jsonb(NEW)=to_jsonb(OLD) THEN PERFORM r1_assert_recognition_current(OLD.recognition_id); RETURN NEW; END IF;\n SELECT * INTO v FROM recognition_review_revisions WHERE recognition_id=OLD.recognition_id AND apply_xid=pg_current_xact_id();\n IF NOT FOUND AND OLD.review_version=0 AND OLD.applied_review_id IS NULL AND NEW.review_version=0 AND NEW.applied_review_id IS NULL\n  AND NOT EXISTS(SELECT 1 FROM recognition_review_revisions WHERE recognition_id=OLD.recognition_id) THEN RETURN NEW; END IF;\n PERFORM r1_require(v.review_id IS NOT NULL AND r1_recognition_projection(OLD)=v.before_projection_json\n  AND r1_recognition_projection(NEW)=v.after_projection_json AND r1_recognition_projection_hash(NEW)=v.after_projection_hash,''R1 recognition update requires exact current-transaction revision'');\n RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"r1_require","rows":"0","binary":null,"config":null,"result":"void","source":"\nBEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION ''%'',message USING ERRCODE=''23514''; END IF; END ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"ok boolean, message text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"boolean, text","securityDefiner":false},{"cost":"100","kind":"f","name":"r1_revision_guard","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE old_r transaction_invoice_recognitions%ROWTYPE; p jsonb; b jsonb; e jsonb; s jsonb; snap jsonb; item jsonb;\n h hometax_tax_invoices%ROWTYPE; subject_r vat_filing_subject_revisions%ROWTYPE;\n old_p jsonb; prior recognition_review_revisions%ROWTYPE; line_count integer; expected_tax numeric; expected_total numeric;\nBEGIN\n PERFORM r1_require(NEW.apply_xid=pg_current_xact_id(),''R1 apply transaction identity mismatch'');\n SELECT * INTO old_r FROM transaction_invoice_recognitions WHERE recognition_id=NEW.recognition_id FOR UPDATE;\n PERFORM r1_require(FOUND,''R1 existing recognition required'');\n PERFORM r1_assert_recognition_current(NEW.recognition_id);\n old_p:=r1_recognition_projection(old_r); p:=NEW.after_projection_json; b:=NEW.basis_json; e:=NEW.execution_result_json;\n PERFORM r1_require(NEW.review_version=old_r.review_version+1 AND NEW.previous_review_id IS NOT DISTINCT FROM old_r.applied_review_id,''R1 review lineage mismatch'');\n PERFORM r1_require(NEW.before_projection_json=old_p AND NEW.before_projection_hash=r1_recognition_projection_hash(old_r),''R1 before projection CAS mismatch'');\n PERFORM r1_require(r1_json_keys(p,ARRAY[''schemaVersion'',''recognitionId'',''canonicalInvoiceKey'',''sourceKind'',''sourceId'',''sourceHash'',''sourceSnapshotText'',''expenseAccount'',''reason'',''evidence'',''creationRequestId'',''createdBy'',''createdAt'',''appliedReviewId'',''reviewVersion'']),''R1 after projection keys invalid'');\n PERFORM r1_require(p->>''schemaVersion''=''r1-recognition-projection-v1'' AND r1_json_integer(p->''reviewVersion'',1,2147483647)\n  AND (p->>''reviewVersion'')::integer=NEW.review_version AND p->>''appliedReviewId''=NEW.review_id,''R1 after projection review invalid'');\n PERFORM r1_require((p-ARRAY[''sourceHash'',''sourceSnapshotText'',''reason'',''evidence'',''appliedReviewId'',''reviewVersion''])\n  =(old_p-ARRAY[''sourceHash'',''sourceSnapshotText'',''reason'',''evidence'',''appliedReviewId'',''reviewVersion'']),''R1 stable recognition identity changed'');\n PERFORM r1_require(jsonb_typeof(p->''sourceHash'')=''string'' AND p->>''sourceHash'' ~ ''^[0-9a-f]{64}$''\n  AND jsonb_typeof(p->''sourceSnapshotText'')=''string'' AND jsonb_typeof(p->''reason'')=''string'' AND jsonb_typeof(p->''evidence'')=''string'',''R1 after projection type invalid'');\n PERFORM r1_require(vat_followup_hash_v2(p)=NEW.after_projection_hash,''R1 after projection hash mismatch'');\n PERFORM r1_require(r1_json_keys(b,ARRAY[''schemaVersion'',''recognitionId'',''reviewId'',''reviewVersion'',''previousReviewId'',''beforeProjectionHash'',''afterProjectionHash'',''representative'',''dates'',''subjectProof'',''reviewDocument'',''reason'',''requestId'',''actorUserId'',''reviewConfirmed'']),''R1 basis keys invalid'');\n PERFORM r1_require(b->>''schemaVersion''=''r1-review-basis-v1'' AND b->>''recognitionId''=NEW.recognition_id\n  AND b->>''reviewId''=NEW.review_id AND b->''reviewVersion''=to_jsonb(NEW.review_version)\n  AND b->''previousReviewId''=COALESCE(to_jsonb(NEW.previous_review_id),''null''::jsonb)\n  AND b->>''beforeProjectionHash''=NEW.before_projection_hash AND b->>''afterProjectionHash''=NEW.after_projection_hash\n  AND b->>''requestId''=NEW.request_id AND b->>''actorUserId''=NEW.actor_user_id AND b->''reviewConfirmed''=''true''::jsonb\n  AND vat_followup_hash_v2(b)=NEW.basis_hash,''R1 basis metadata/hash mismatch'');\n PERFORM r1_require(r1_json_keys(b->''representative'',ARRAY[''sourceKind'',''sourceId'',''canonicalKey'',''journalKind'',''journalId''])\n  AND b->''representative''=jsonb_build_object(''sourceKind'',old_r.source_kind,''sourceId'',old_r.source_id,\n   ''canonicalKey'',old_r.canonical_invoice_key,''journalKind'',NEW.target_source_kind,''journalId'',NEW.target_source_id)\n  AND old_r.source_kind=''hometax'' AND NEW.target_source_id=old_r.source_id,''R1 representative not supported'');\n PERFORM r1_require(r1_json_keys(b->''dates'',ARRAY[''accountingDate'',''taxDate''])\n  AND b->''dates''->>''accountingDate''=old_r.source_snapshot->>''date'' AND b->''dates''->>''taxDate''=old_r.source_snapshot->>''taxDate''\n  AND b->''dates''->>''accountingDate''=b->''dates''->>''taxDate'',''R1 accounting/VAT dates changed'');\n SELECT * INTO h FROM hometax_tax_invoices WHERE hti_id=old_r.source_id FOR SHARE;\n PERFORM r1_require(FOUND AND h.direction=''purchase'' AND COALESCE(h.excluded,0)=0 AND COALESCE(h.modify_code,'''')=''''\n  AND h.write_date::text=b->''dates''->>''accountingDate'' AND ''invoice:''||btrim(h.nts_send_key)=old_r.canonical_invoice_key\n  AND h.amount_total>0 AND h.tax_total>=0 AND h.total_amount=h.amount_total+h.tax_total\n  AND h.vat_deductible IN (0,1),''R1 current HTI source unsupported'');\n snap:=(p->>''sourceSnapshotText'')::jsonb;\n PERFORM r1_require(jsonb_typeof(snap)=''object'' AND snap::text=p->>''sourceSnapshotText''\n  AND snap->>''sourceHash''=p->>''sourceHash'' AND snap->>''kind''=''hometax'' AND snap->>''id''=h.hti_id\n  AND snap->>''canonicalKey''=old_r.canonical_invoice_key AND snap->>''journalKind''=NEW.target_source_kind AND snap->>''journalId''=NEW.target_source_id\n  AND snap->>''date''=b->''dates''->>''accountingDate'' AND snap->>''taxDate''=b->''dates''->>''taxDate''\n  AND snap->>''direction''=''purchase'' AND snap->''vatDeductible''=to_jsonb(h.vat_deductible)\n  AND r1_json_integer(snap->''supply'',1,9007199254740991) AND r1_json_integer(snap->''tax'',0,9007199254740991)\n  AND r1_json_integer(snap->''total'',1,9007199254740991)\n  AND (snap->>''supply'')::numeric=h.amount_total AND (snap->>''tax'')::numeric=h.tax_total AND (snap->>''total'')::numeric=h.total_amount,''R1 current source projection mismatch'');\n PERFORM r1_require(NOT EXISTS(SELECT 1 FROM transaction_links l WHERE l.state=''active'' AND\n  (l.canonical_invoice_key=old_r.canonical_invoice_key OR l.right_snapshot->>''canonicalKey''=old_r.canonical_invoice_key\n   OR (l.right_kind=''hometax'' AND l.right_id=old_r.source_id))),''R1 active relationship is unsupported'');\n PERFORM r1_require(EXISTS(SELECT 1 FROM journal_accounts a WHERE a.account_code=old_r.expense_account AND a.is_active=1),''R1 expense account unavailable'');\n PERFORM r1_require(r1_json_keys(b->''reviewDocument'',ARRAY[''documentId'',''subjectId'',''evidenceRef'',''evidenceHash'',''location''])\n  AND b->''reviewDocument''->>''evidenceRef''=''vat-document:''||(b->''reviewDocument''->>''documentId'')\n  AND length(btrim(b->''reviewDocument''->>''location''))>0\n  AND vat_followup_server_document(b->''reviewDocument''->>''evidenceRef'',b->''reviewDocument''->>''evidenceHash'',b->''reviewDocument''->>''subjectId''),''R1 review document invalid'');\n PERFORM r1_require(jsonb_typeof(b->''reason'')=''string'' AND length(btrim(b->>''reason''))>0 AND p->>''reason''=btrim(b->>''reason'')\n  AND p->>''evidence''=(b->''reviewDocument''->>''evidenceRef'')||'' / ''||(b->''reviewDocument''->>''location''),''R1 review reason/evidence mismatch'');\n PERFORM r1_require(jsonb_typeof(b->''subjectProof'')=''array'' AND jsonb_array_length(b->''subjectProof'')=1,''R1 subject proof must cover the supported business date'');\n FOR item IN SELECT value FROM jsonb_array_elements(b->''subjectProof'') LOOP\n  PERFORM r1_require(r1_json_keys(item,ARRAY[''date'',''subjectId'',''revisionId'',''corpNum'',''revisionHash'',''evidenceRef'',''evidenceHash''])\n   AND item->>''date''=b->''dates''->>''accountingDate'' AND item->>''subjectId''=b->''reviewDocument''->>''subjectId''\n   AND jsonb_typeof(item->''corpNum'')=''string'' AND item->>''corpNum'' ~ ''^[0-9]{10}$'' AND item->>''corpNum''<>''0000000000'',''R1 subject proof metadata invalid'');\n  SELECT * INTO subject_r FROM vat_filing_subject_revisions WHERE revision_id=item->>''revisionId'' AND subject_id=item->>''subjectId'';\n  PERFORM r1_require(FOUND AND vat_followup_hash_v2(subject_r.payload_json)=item->>''revisionHash''\n   AND subject_r.payload_json->>''state''=''verified'' AND subject_r.payload_json->>''entityType''=''corporation''\n   AND subject_r.payload_json->>''vatRegime''=''general'' AND subject_r.payload_json->>''filingUnit''=''single_business_place''\n   AND subject_r.payload_json->>''corpNum''=item->>''corpNum''\n   AND subject_r.payload_json->>''evidenceRef''=item->>''evidenceRef'' AND subject_r.payload_json->>''evidenceHash''=item->>''evidenceHash''\n   AND vat_followup_server_document(item->>''evidenceRef'',item->>''evidenceHash'',item->>''subjectId''),''R1 subject document or revision invalid'');\n END LOOP;\n PERFORM r1_require(r1_json_keys(e,ARRAY[''schemaVersion'',''entry'',''lines'',''snapshot'']) AND e->''schemaVersion''=''1''::jsonb,''R1 execution result shape invalid'');\n PERFORM r1_require(r1_json_keys(e->''entry'',ARRAY[''entry_id'',''entry_date'',''source_kind'',''source_id'',''description'',''party_name'',''status'',''doc_id'',''confirmed_by'',''confirmed_at'',''memo'',''created_at'',''updated_at''])\n  AND e->''entry''->>''entry_id''=NEW.target_entry_id AND e->''entry''->>''source_kind''=NEW.target_source_kind AND e->''entry''->>''source_id''=NEW.target_source_id\n  AND e->''entry''->>''entry_date''=b->''dates''->>''accountingDate'' AND e->''entry''->>''status''=''auto''\n  AND e->''entry''->''confirmed_by''=''null''::jsonb AND e->''entry''->''confirmed_at''=''null''::jsonb\n  AND e->''entry''->''memo''=''null''::jsonb AND e->''entry''->''updated_at''=''null''::jsonb\n  AND e->''entry''->>''created_at''=NEW.created_at,''R1 execution entry mismatch'');\n PERFORM r1_require(NEW.target_entry_id=''je-''||substr(encode(sha256(convert_to(NEW.target_source_kind||'':''||NEW.target_source_id,''UTF8'')),''hex''),1,12),''R1 target entry identity mismatch'');\n PERFORM r1_require(NOT EXISTS(SELECT 1 FROM journal_entries WHERE entry_id=NEW.target_entry_id AND status IN (''confirmed'',''excluded'')),''R1 protected journal entry'');\n PERFORM r1_require(r1_json_keys(e->''snapshot'',ARRAY[''entry_id'',''snapshot_version'',''source_hash'',''source_json'',''captured_at''])\n  AND e->''snapshot''->>''entry_id''=NEW.target_entry_id AND e->''snapshot''->''snapshot_version''=''1''::jsonb\n  AND e->''snapshot''->>''captured_at''=NEW.created_at\n  AND e->''snapshot''->>''source_hash''=vat_followup_hash_v2(e->''snapshot''->''source_json''),''R1 execution snapshot mismatch'');\n s:=e->''snapshot''->''source_json'';\n PERFORM r1_require(s->>''sourceKind''=NEW.target_source_kind AND s->>''sourceId''=NEW.target_source_id AND s->>''entryDate''=b->''dates''->>''accountingDate''\n  AND s->''evidence''->>''invoice''=p->>''sourceHash''\n  AND s->''evidence''->''recognition''->>''id''=NEW.recognition_id AND s->''evidence''->''recognition''->>''sourceHash''=p->>''sourceHash''\n  AND s->''evidence''->''recognition''->''review''=jsonb_build_object(''schemaVersion'',1,''reviewId'',NEW.review_id,''reviewVersion'',NEW.review_version,''basisHash'',NEW.basis_hash),''R1 journal review evidence mismatch'');\n expected_tax:=CASE WHEN h.vat_deductible=1 THEN h.tax_total ELSE 0 END; expected_total:=h.total_amount;\n PERFORM r1_require(jsonb_typeof(e->''lines'')=''array'' AND jsonb_array_length(e->''lines'')=CASE WHEN expected_tax>0 THEN 3 ELSE 2 END,''R1 journal line count mismatch'');\n line_count:=0;\n FOR item IN SELECT value FROM jsonb_array_elements(e->''lines'') LOOP\n  line_count:=line_count+1;\n  PERFORM r1_require(r1_json_keys(item,ARRAY[''line_id'',''entry_id'',''line_no'',''account_code'',''debit'',''credit'',''memo''])\n   AND item->>''entry_id''=NEW.target_entry_id AND item->''line_no''=to_jsonb(line_count)\n   AND item->>''line_id''=''jl-''||substr(encode(sha256(convert_to(NEW.target_entry_id||'':''||line_count::text,''UTF8'')),''hex''),1,12)\n   AND r1_json_integer(item->''debit'',0,9007199254740991) AND r1_json_integer(item->''credit'',0,9007199254740991),''R1 execution line metadata invalid'');\n  PERFORM r1_require(item->>''account_code''=CASE WHEN line_count=1 THEN old_r.expense_account WHEN line_count=2 AND expected_tax>0 THEN ''135'' ELSE ''251'' END\n   AND (item->>''debit'')::numeric=CASE WHEN line_count=1 THEN expected_total-expected_tax WHEN line_count=2 AND expected_tax>0 THEN expected_tax ELSE 0 END\n   AND (item->>''credit'')::numeric=CASE WHEN line_count=jsonb_array_length(e->''lines'') THEN expected_total ELSE 0 END,''R1 execution line amount mismatch'');\n END LOOP;\n RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"r1_row_agreement","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE old_key text; new_key text; v record;\nBEGIN\n IF TG_TABLE_NAME IN (''transaction_invoice_recognitions'',''recognition_review_revisions'',''recognition_review_requests'') THEN\n  IF TG_OP<>''INSERT'' THEN old_key:=OLD.recognition_id; END IF;\n  IF TG_OP<>''DELETE'' THEN new_key:=NEW.recognition_id; END IF;\n  IF old_key IS NOT NULL THEN PERFORM r1_assert_recognition_agreement(old_key); END IF;\n  IF new_key IS NOT NULL AND new_key IS DISTINCT FROM old_key THEN PERFORM r1_assert_recognition_agreement(new_key); END IF;\n ELSE\n  IF TG_OP<>''INSERT'' THEN old_key:=CASE WHEN TG_TABLE_NAME=''audit_log'' THEN to_jsonb(OLD)->>''target_id'' ELSE to_jsonb(OLD)->>''entry_id'' END; END IF;\n  IF TG_OP<>''DELETE'' THEN new_key:=CASE WHEN TG_TABLE_NAME=''audit_log'' THEN to_jsonb(NEW)->>''target_id'' ELSE to_jsonb(NEW)->>''entry_id'' END; END IF;\n  FOR v IN SELECT recognition_id FROM recognition_review_revisions WHERE apply_xid=pg_current_xact_id()\n   AND CASE WHEN TG_TABLE_NAME=''audit_log'' THEN review_id IN (old_key,new_key) ELSE target_entry_id IN (old_key,new_key) END LOOP\n   PERFORM r1_assert_recognition_agreement(v.recognition_id);\n  END LOOP;\n END IF;\n RETURN NULL;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"r1_truncate_guard","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nBEGIN\n IF TG_TABLE_NAME IN (''recognition_review_revisions'',''recognition_review_requests'')\n  OR (TG_TABLE_NAME=''transaction_invoice_recognitions'' AND EXISTS(SELECT 1 FROM recognition_review_revisions))\n  OR EXISTS(SELECT 1 FROM recognition_review_revisions WHERE apply_xid=pg_current_xact_id()) THEN\n  RAISE EXCEPTION ''R1 protected transaction/history cannot be truncated'' USING ERRCODE=''23514'';\n END IF;\n RETURN NULL;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"reject_vat_filing_document_mutation","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nBEGIN\n  RAISE EXCEPTION ''VAT filing documents are immutable; update, delete and truncate are prohibited'' USING ERRCODE = ''23514'';\nEND;\n","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_assert_finalization_open","rows":"0","binary":null,"config":null,"result":"void","source":"\nDECLARE conflicts jsonb;\nBEGIN\n  IF p_period_kind=''final'' THEN PERFORM vat_finalization_fence(p_period_year,p_period_term); END IF;\n  conflicts:=vat_finalization_conflicts(p_subject_id,p_period_year,p_period_term,p_period_kind,p_application_path);\n  IF jsonb_array_length(conflicts)>0\n  THEN RAISE EXCEPTION ''VAT finalization conflict across filing paths''\n    USING ERRCODE=''23514'',DETAIL=conflicts::text; END IF;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_subject_id text, p_period_year integer, p_period_term integer, p_period_kind text, p_application_path text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"text, integer, integer, text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_basis_finalization_boundary","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE basis vat_filing_basis_snapshots%ROWTYPE;\nBEGIN\n  PERFORM pg_advisory_xact_lock(1296256326,1);\n  SELECT * INTO STRICT basis FROM vat_filing_basis_snapshots WHERE snapshot_id=NEW.basis_snapshot_id;\n  PERFORM vat_assert_finalization_open(basis.subject_id,basis.period_year,basis.period_term,basis.period_kind,''basis'');\n  RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_filing_append_only","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nBEGIN RAISE EXCEPTION ''VAT filing evidence is append-only: %'', TG_TABLE_NAME USING ERRCODE=''23514''; END ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_filing_complete_plan","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE actual jsonb; expected jsonb;\nBEGIN\n  SELECT COALESCE(jsonb_agg(jsonb_build_object(''factId'',fact_id,''revisionId'',revision_id,''kind'',kind,''amount'',amount) ORDER BY fact_id,kind),''[]''::jsonb)\n    INTO actual FROM vat_filing_basis_consumptions WHERE snapshot_id=NEW.snapshot_id;\n  SELECT COALESCE(jsonb_agg(p ORDER BY p->>''factId'',p->>''kind''),''[]''::jsonb) INTO expected FROM jsonb_array_elements(NEW.consumption_plan) p;\n  IF actual IS DISTINCT FROM expected THEN\n    RAISE EXCEPTION ''VAT sealed basis and consumption ledger must commit together'' USING ERRCODE=''23514'';\n  END IF;\n  IF NEW.scope_json->>''noticeFactId'' IS NOT NULL AND NOT EXISTS(\n    SELECT 1 FROM vat_filing_basis_consumptions c WHERE c.snapshot_id=NEW.snapshot_id AND c.kind=''notice''\n      AND c.fact_id=NEW.scope_json->>''noticeFactId'' AND c.amount=(NEW.scope_json->>''noticeDeduction'')::bigint\n  ) THEN\n    RAISE EXCEPTION ''VAT notice deduction lacks matching ledger consumption'' USING ERRCODE=''23514'';\n  END IF;\n  RETURN NULL;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_filing_return_guard","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE basis vat_filing_basis_snapshots%ROWTYPE; previous vat_filing_return_revisions%ROWTYPE;\n  current_return vat_filing_return_revisions%ROWTYPE; period jsonb; metadata jsonb;\n  field text; number_value numeric; manual_delta numeric; payable numeric;\nBEGIN\n  PERFORM pg_advisory_xact_lock(1296256326,1);\n  INSERT INTO vat_filing_return_fences(basis_snapshot_id,generation) VALUES(NEW.basis_snapshot_id,1)\n    ON CONFLICT(basis_snapshot_id) DO UPDATE SET generation=vat_filing_return_fences.generation+1;\n  SELECT * INTO STRICT basis FROM vat_filing_basis_snapshots WHERE snapshot_id=NEW.basis_snapshot_id FOR UPDATE;\n  IF TG_TABLE_NAME=''vat_filing_return_confirmations'' THEN\n    SELECT * INTO STRICT current_return FROM vat_filing_return_revisions WHERE return_id=NEW.return_id;\n    IF current_return.calculation_hash IS DISTINCT FROM NEW.calculation_hash\n      OR current_return.basis_snapshot_id IS DISTINCT FROM NEW.basis_snapshot_id\n      OR jsonb_array_length(current_return.form_json->''blockingIssues'')<>0\n      OR current_return.form_json->''filingBasis''->>''verificationStatus'' IS DISTINCT FROM ''complete''\n      OR EXISTS(SELECT 1 FROM vat_filing_return_revisions WHERE basis_snapshot_id=NEW.basis_snapshot_id AND revision>current_return.revision)\n    THEN RAISE EXCEPTION ''VAT return confirmation evidence mismatch'' USING ERRCODE=''23514''; END IF;\n    RETURN NEW;\n  END IF;\n  IF EXISTS(SELECT 1 FROM vat_filing_return_confirmations WHERE basis_snapshot_id=NEW.basis_snapshot_id)\n  THEN RAISE EXCEPTION ''VAT basis already used by a confirmed return'' USING ERRCODE=''23514''; END IF;\n  SELECT * INTO previous FROM vat_filing_return_revisions WHERE basis_snapshot_id=NEW.basis_snapshot_id ORDER BY revision DESC LIMIT 1;\n  IF NEW.revision<>COALESCE(previous.revision,0)+1 OR NEW.previous_return_id IS DISTINCT FROM previous.return_id\n  THEN RAISE EXCEPTION ''VAT return revision chain conflict'' USING ERRCODE=''23514''; END IF;\n  period:=NEW.form_json->''period''; metadata:=NEW.form_json->''filingBasis'';\n  IF NEW.scope_hash IS DISTINCT FROM basis.scope_hash\n    OR metadata->>''subjectId'' IS DISTINCT FROM basis.subject_id\n    OR metadata->>''mode'' IS DISTINCT FROM basis.scope_json->>''mode''\n    OR metadata->>''noticeDeduction'' IS NULL\n    OR (metadata->>''noticeDeduction'')::bigint IS DISTINCT FROM (basis.scope_json->>''noticeDeduction'')::bigint\n    OR period->>''year'' IS NULL OR (period->>''year'')::integer<>basis.period_year\n    OR period->>''term'' IS NULL OR (period->>''term'')::integer<>basis.period_term\n    OR period->>''kind'' IS DISTINCT FROM (CASE basis.period_kind WHEN ''preliminary'' THEN ''pre'' ELSE ''final'' END)\n    OR period->>''from'' IS DISTINCT FROM basis.date_from OR period->>''to'' IS DISTINCT FROM basis.date_to\n    OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.form_json->''manual'') f WHERE f->>''key'' IS NULL OR f->>''key'' NOT IN(''etaxCredit'',''penalty''))\n  THEN RAISE EXCEPTION ''VAT return scope or notice basis mismatch'' USING ERRCODE=''23514''; END IF;\n  FOREACH field IN ARRAY ARRAY[''sales,total,tax'',''sales,invoiceTaxable,tax'',''sales,deemedRent,tax'',\n    ''purchases,totalDeductibleTax'',''purchases,invoiceGeneral,tax'',''purchases,nonDeductible,tax'',\n    ''purchases,invoiceUndecided,tax'',''purchases,cardDeductible,tax'',''taxDue'',''finalTaxDue''] LOOP\n    IF jsonb_typeof(NEW.form_json #> string_to_array(field,'','')) IS DISTINCT FROM ''number''\n    THEN RAISE EXCEPTION ''VAT required tax amount missing'' USING ERRCODE=''23514''; END IF;\n    number_value:=(NEW.form_json #>> string_to_array(field,'',''))::numeric;\n    IF number_value<>trunc(number_value) OR abs(number_value)>9007199254740991\n    THEN RAISE EXCEPTION ''VAT tax amount outside integer range'' USING ERRCODE=''23514''; END IF;\n  END LOOP;\n  IF jsonb_typeof(metadata->''sourceManifest'') IS DISTINCT FROM ''array''\n    OR COALESCE(metadata->>''sourceManifestHash'','''') !~ ''^[0-9a-f]{64}$''\n    OR NEW.form_json->''sourceEvidence''->>''version'' IS DISTINCT FROM ''g03b-v1''\n    OR jsonb_typeof(NEW.form_json->''ledgerSnapshot''->''rows'') IS DISTINCT FROM ''array''\n    OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.form_json->''manual'') f WHERE jsonb_typeof(f->''amount'') IS DISTINCT FROM ''number''\n      OR (f->>''amount'')::numeric<>trunc((f->>''amount'')::numeric) OR (f->>''amount'')::numeric<0 OR (f->>''amount'')::numeric>9007199254740991)\n    OR (SELECT count(*)<>count(DISTINCT f->>''key'') FROM jsonb_array_elements(NEW.form_json->''manual'') f)\n  THEN RAISE EXCEPTION ''VAT source or manual evidence incomplete'' USING ERRCODE=''23514''; END IF;\n  IF (NEW.form_json#>>''{sales,total,tax}'')::numeric<>(NEW.form_json#>>''{sales,invoiceTaxable,tax}'')::numeric+(NEW.form_json#>>''{sales,deemedRent,tax}'')::numeric\n    OR (NEW.form_json#>>''{purchases,totalDeductibleTax}'')::numeric<>(NEW.form_json#>>''{purchases,invoiceGeneral,tax}'')::numeric-(NEW.form_json#>>''{purchases,nonDeductible,tax}'')::numeric-(NEW.form_json#>>''{purchases,invoiceUndecided,tax}'')::numeric+(NEW.form_json#>>''{purchases,cardDeductible,tax}'')::numeric\n    OR (NEW.form_json->>''taxDue'')::numeric<>(NEW.form_json#>>''{sales,total,tax}'')::numeric-(NEW.form_json#>>''{purchases,totalDeductibleTax}'')::numeric\n  THEN RAISE EXCEPTION ''VAT tax subtotal mismatch'' USING ERRCODE=''23514''; END IF;\n  SELECT COALESCE(sum(CASE WHEN f->>''key''=''penalty'' THEN (f->>''amount'')::numeric ELSE -(f->>''amount'')::numeric END),0)\n    INTO manual_delta FROM jsonb_array_elements(NEW.form_json->''manual'') f;\n  payable:=(NEW.form_json->>''taxDue'')::numeric+manual_delta-(metadata->>''noticeDeduction'')::numeric;\n  IF payable>0 THEN payable:=floor(payable/10)*10; END IF;\n  IF (NEW.form_json->>''finalTaxDue'')::numeric<>payable\n  THEN RAISE EXCEPTION ''VAT final tax or notice deduction mismatch'' USING ERRCODE=''23514''; END IF;\n  RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_filing_revision_chain","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE previous_id text; previous_version integer; previous_year integer; previous_term integer; expected_external_key text; document_key_value text; document_owner text;\nBEGIN\n  PERFORM pg_advisory_xact_lock(1296256326,1);\n  IF TG_TABLE_NAME=''vat_filing_subject_revisions'' THEN\n    PERFORM 1 FROM vat_filing_subjects WHERE subject_id=NEW.subject_id FOR UPDATE;\n    SELECT revision_id,version INTO previous_id,previous_version FROM vat_filing_subject_revisions WHERE subject_id=NEW.subject_id ORDER BY version DESC LIMIT 1;\n  ELSE\n    PERFORM 1 FROM vat_filing_facts WHERE fact_id=NEW.fact_id FOR UPDATE;\n    SELECT revision_id,version,period_year,period_term INTO previous_id,previous_version,previous_year,previous_term FROM vat_filing_fact_revisions WHERE fact_id=NEW.fact_id ORDER BY version DESC LIMIT 1;\n    IF previous_id IS NOT NULL AND (previous_year<>NEW.period_year OR previous_term<>NEW.period_term) THEN\n      RAISE EXCEPTION ''VAT fact tax period identity cannot change'' USING ERRCODE=''23514'';\n    END IF;\n    SELECT external_key INTO expected_external_key FROM vat_filing_facts WHERE fact_id=NEW.fact_id;\n    IF NEW.payload_json->''data''->>''externalKey'' IS DISTINCT FROM expected_external_key\n       OR NEW.payload_json->''data''->>''supersedesRevisionId'' IS DISTINCT FROM NEW.previous_revision_id THEN\n      RAISE EXCEPTION ''VAT fact identity/lineage mismatch'' USING ERRCODE=''23514'';\n    END IF;\n    IF EXISTS(SELECT 1 FROM vat_filing_basis_consumptions WHERE fact_id=NEW.fact_id) THEN\n      RAISE EXCEPTION ''VAT fact already consumed; explicit subsequent review required'' USING ERRCODE=''23514'';\n    END IF;\n    document_key_value := CASE NEW.kind WHEN ''notice'' THEN NEW.payload_json->''data''->>''noticeNumber'' WHEN ''filing'' THEN NEW.payload_json->''data''->>''receiptNumber'' ELSE expected_external_key END;\n    document_key_value := upper(regexp_replace(btrim(document_key_value),''\\s'','''',''g''));\n    IF document_key_value IS NULL OR document_key_value='''' THEN\n      RAISE EXCEPTION ''VAT official document identity missing'' USING ERRCODE=''23514'';\n    END IF;\n    INSERT INTO vat_filing_document_keys(subject_id,kind,document_key,fact_id) VALUES(NEW.subject_id,NEW.kind,document_key_value,NEW.fact_id) ON CONFLICT DO NOTHING;\n    SELECT fact_id INTO document_owner FROM vat_filing_document_keys WHERE subject_id=NEW.subject_id AND kind=NEW.kind AND document_key=document_key_value;\n    IF document_owner IS DISTINCT FROM NEW.fact_id THEN\n      RAISE EXCEPTION ''VAT official document already belongs to another fact'' USING ERRCODE=''23514'';\n    END IF;\n  END IF;\n  IF NEW.version<>COALESCE(previous_version,0)+1 OR NEW.previous_revision_id IS DISTINCT FROM previous_id THEN\n    RAISE EXCEPTION ''VAT revision is not the single next head'' USING ERRCODE=''23514'';\n  END IF;\n  RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_filing_validate_consumption","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE snap vat_filing_basis_snapshots%ROWTYPE; fact vat_filing_fact_revisions%ROWTYPE;\nBEGIN\n  PERFORM pg_advisory_xact_lock(1296256326,1);\n  SELECT * INTO STRICT snap FROM vat_filing_basis_snapshots WHERE snapshot_id=NEW.snapshot_id;\n  SELECT * INTO STRICT fact FROM vat_filing_fact_revisions WHERE revision_id=NEW.revision_id;\n  IF snap.subject_id<>NEW.subject_id OR snap.period_year<>fact.period_year OR snap.period_term<>fact.period_term\n     OR fact.state<>''verified'' OR fact.payload_json->''data''->>''amountSemantics'' IS DISTINCT FROM ''total_replacement''\n     OR EXISTS(SELECT 1 FROM vat_filing_fact_revisions WHERE fact_id=NEW.fact_id AND version>fact.version) THEN\n    RAISE EXCEPTION ''VAT consumption subject/period/head mismatch'' USING ERRCODE=''23514'';\n  END IF;\n  IF NEW.kind=''notice'' AND (snap.period_kind<>''final'' OR NEW.amount IS DISTINCT FROM fact.amount) THEN\n    RAISE EXCEPTION ''VAT notice must be consumed in full in the matching final period'' USING ERRCODE=''23514'';\n  END IF;\n  IF NEW.kind=''refund'' THEN\n    RAISE EXCEPTION ''Partial/refund consumption is unsupported in B1'' USING ERRCODE=''23514'';\n  END IF;\n  IF NEW.kind=''filing'' AND (fact.payload_json->''data''->>''sourceReconciliation'' IS DISTINCT FROM ''complete''\n    OR (fact.payload_json->''data''->''declaredTotals''->>''claimedTax'')::bigint IS DISTINCT FROM NEW.amount) THEN\n    RAISE EXCEPTION ''VAT filing consumption requires the complete declared amount'' USING ERRCODE=''23514'';\n  END IF;\n  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(snap.consumption_plan) p WHERE p->>''factId''=NEW.fact_id AND p->>''revisionId''=NEW.revision_id AND p->>''kind''=NEW.kind AND (p->>''amount'')::bigint=NEW.amount) THEN\n    RAISE EXCEPTION ''VAT consumption not in sealed plan'' USING ERRCODE=''23514'';\n  END IF;\n  RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_finalization_basis_identity","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE b vat_filing_basis_snapshots%ROWTYPE; s vat_filing_subject_revisions%ROWTYPE;\n  subject_json jsonb; corp_num text; subject_from date; subject_to date;\n  expected_from text; expected_to text;\nBEGIN\n  SELECT * INTO b FROM vat_filing_basis_snapshots WHERE snapshot_id=p_snapshot_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION ''VAT finalization identity unavailable: basis snapshot missing'' USING ERRCODE=''55000'';\n  END IF;\n  SELECT * INTO s FROM vat_filing_subject_revisions\n    WHERE revision_id=b.subject_revision_id AND subject_id=b.subject_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION ''VAT finalization identity unavailable: subject revision missing'' USING ERRCODE=''55000'';\n  END IF;\n  subject_json:=s.payload_json;\n  corp_num:=subject_json->>''corpNum'';\n  IF jsonb_typeof(subject_json) IS DISTINCT FROM ''object''\n    OR subject_json IS DISTINCT FROM b.scope_json#>''{evidenceSnapshot,subject}''\n    OR subject_json->>''subjectId'' IS DISTINCT FROM b.subject_id\n    OR subject_json->>''revisionId'' IS DISTINCT FROM b.subject_revision_id\n    OR subject_json->''version'' IS DISTINCT FROM to_jsonb(s.version)\n    OR b.scope_json->>''subjectId'' IS DISTINCT FROM b.subject_id\n    OR b.scope_json->>''subjectRevisionId'' IS DISTINCT FROM b.subject_revision_id\n    OR b.scope_json->''year'' IS DISTINCT FROM to_jsonb(b.period_year)\n    OR b.scope_json->''term'' IS DISTINCT FROM to_jsonb(b.period_term)\n    OR b.scope_json->>''kind'' IS DISTINCT FROM b.period_kind\n    OR b.scope_json->>''dateFrom'' IS DISTINCT FROM b.date_from\n    OR b.scope_json->>''dateTo'' IS DISTINCT FROM b.date_to\n    OR b.scope_json->>''status'' IS DISTINCT FROM ''ready''\n    OR subject_json->>''state'' IS DISTINCT FROM ''verified''\n    OR subject_json->>''entityType'' IS DISTINCT FROM ''corporation''\n    OR subject_json->>''vatRegime'' IS DISTINCT FROM ''general''\n    OR subject_json->>''filingUnit'' IS DISTINCT FROM ''single_business_place''\n    OR jsonb_typeof(subject_json->''corpNum'') IS DISTINCT FROM ''string''\n    OR COALESCE(corp_num,'''') !~ ''^[0-9]{10}$'' OR corp_num=''0000000000''\n    OR jsonb_typeof(b.scope_json#>''{evidenceSnapshot,collectionCorpNum}'') IS DISTINCT FROM ''string''\n    OR b.scope_json#>>''{evidenceSnapshot,collectionCorpNum}'' IS DISTINCT FROM corp_num\n  THEN\n    RAISE EXCEPTION ''VAT finalization identity unavailable: stored taxpayer evidence mismatch or unsupported identity'' USING ERRCODE=''55000'';\n  END IF;\n  -- 주체의 최신 판을 조회하지 않는다. 이 보관본의 적용기간과 고정된 판만 대조한다.\n  expected_from:=b.period_year::text||CASE b.period_term WHEN 1 THEN ''-01-01'' ELSE ''-07-01'' END;\n  expected_to:=b.period_year::text||CASE\n    WHEN b.period_kind=''preliminary'' AND b.period_term=1 THEN ''-03-31''\n    WHEN b.period_kind=''preliminary'' THEN ''-09-30''\n    WHEN b.period_term=1 THEN ''-06-30'' ELSE ''-12-31'' END;\n  IF b.date_from IS DISTINCT FROM expected_from OR b.date_to IS DISTINCT FROM expected_to\n    OR COALESCE(subject_json->>''effectiveFrom'','''') !~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}$''\n    OR NOT(subject_json ? ''effectiveTo'')\n    OR (subject_json->''effectiveTo''<>''null''::jsonb AND\n      COALESCE(subject_json->>''effectiveTo'','''') !~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}$'')\n  THEN\n    RAISE EXCEPTION ''VAT finalization identity unavailable: stored taxpayer period mismatch'' USING ERRCODE=''55000'';\n  END IF;\n  BEGIN\n    subject_from:=(subject_json->>''effectiveFrom'')::date;\n    subject_to:=(subject_json->>''effectiveTo'')::date;\n  EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN\n    RAISE EXCEPTION ''VAT finalization identity unavailable: invalid taxpayer effective date'' USING ERRCODE=''55000'';\n  END;\n  IF subject_from::text IS DISTINCT FROM subject_json->>''effectiveFrom''\n    OR (subject_to IS NOT NULL AND subject_to::text IS DISTINCT FROM subject_json->>''effectiveTo'')\n    OR subject_from>b.date_from::date OR (subject_to IS NOT NULL AND subject_to<b.date_to::date)\n  THEN\n    RAISE EXCEPTION ''VAT finalization identity unavailable: taxpayer does not cover stored period'' USING ERRCODE=''55000'';\n  END IF;\n  RETURN jsonb_build_object(''snapshotId'',b.snapshot_id,''subjectId'',b.subject_id,\n    ''subjectRevisionId'',b.subject_revision_id,''taxpayerCorpNum'',corp_num,\n    ''filingUnit'',''single_business_place'',''year'',b.period_year,''term'',b.period_term,''kind'',b.period_kind);\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_snapshot_id text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"text","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_finalization_complete_boundary","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE conflicts jsonb; basis vat_filing_basis_snapshots%ROWTYPE; current_status text;\nBEGIN\n  IF TG_TABLE_NAME=''vat_returns'' THEN\n    SELECT status INTO current_status FROM vat_returns WHERE return_id=NEW.return_id;\n    IF NEW.period_kind<>''final'' OR current_status IS DISTINCT FROM ''confirmed'' THEN RETURN NULL; END IF;\n    conflicts:=vat_finalization_conflicts(NULL,NEW.period_year,NEW.period_term,''final'',''legacy'');\n    IF jsonb_array_length(conflicts)=1 AND conflicts#>>''{0,origin}''=''legacy''\n      AND conflicts#>>''{0,returnId}''=NEW.return_id THEN RETURN NULL; END IF;\n  ELSE\n    SELECT * INTO STRICT basis FROM vat_filing_basis_snapshots WHERE snapshot_id=NEW.basis_snapshot_id;\n    IF basis.period_kind<>''final'' THEN RETURN NULL; END IF;\n    conflicts:=vat_finalization_conflicts(basis.subject_id,basis.period_year,basis.period_term,''final'',''basis'');\n    IF jsonb_array_length(conflicts)=1 AND conflicts#>>''{0,origin}''=''basis_return''\n      AND conflicts#>>''{0,confirmationId}''=NEW.confirmation_id THEN RETURN NULL; END IF;\n  END IF;\n  RAISE EXCEPTION ''VAT finalization commit conflict across filing paths'' USING ERRCODE=''23514'',DETAIL=conflicts::text;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_finalization_conflicts","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE conflicts jsonb:=''[]''::jsonb; target_snapshot_id text; target_identity jsonb;\n  candidate record; candidate_identity jsonb; match_kind text;\nBEGIN\n  IF p_period_year IS NULL OR p_period_year NOT BETWEEN 1000 AND 9999\n    OR p_period_term IS NULL OR p_period_term NOT IN(1,2)\n    OR p_period_kind IS NULL OR p_period_kind NOT IN(''pre'',''preliminary'',''final'')\n    OR p_application_path IS NULL OR p_application_path NOT IN(''legacy'',''basis'')\n  THEN RAISE EXCEPTION ''VAT finalization scope is invalid'' USING ERRCODE=''23514''; END IF;\n  IF p_period_kind<>''final'' THEN RETURN conflicts; END IF;\n  IF p_application_path=''basis'' THEN\n    IF COALESCE(length(btrim(p_subject_id)),0)=0\n    THEN RAISE EXCEPTION ''VAT finalization basis subject is required'' USING ERRCODE=''23514''; END IF;\n    SELECT snapshot_id INTO target_snapshot_id FROM vat_filing_basis_snapshots\n      WHERE subject_id=p_subject_id AND period_year=p_period_year AND period_term=p_period_term AND period_kind=''final'';\n    target_identity:=vat_finalization_basis_identity(target_snapshot_id);\n  END IF;\n  FOR candidate IN\n    SELECT r.return_id,r.period_year,r.period_term FROM vat_returns r\n    WHERE r.period_year=p_period_year AND r.period_term=p_period_term\n      AND r.period_kind=''final'' AND r.status=''confirmed'' ORDER BY r.return_id\n  LOOP\n    conflicts:=conflicts||jsonb_build_array(jsonb_build_object(''origin'',''legacy'',''returnId'',candidate.return_id,\n      ''confirmationId'',NULL,''subjectId'',NULL,''year'',candidate.period_year,''term'',candidate.period_term,\n      ''kind'',''final'',''subjectResolution'',''unresolved_legacy'',''taxpayerCorpNum'',NULL,''filingUnit'',NULL,\n      ''matchKind'',''legacy_unresolved''));\n  END LOOP;\n  FOR candidate IN\n    SELECT c.return_id,c.confirmation_id,b.snapshot_id,b.subject_id,b.period_year,b.period_term\n    FROM vat_filing_return_confirmations c JOIN vat_filing_basis_snapshots b ON b.snapshot_id=c.basis_snapshot_id\n    WHERE b.period_year=p_period_year AND b.period_term=p_period_term AND b.period_kind=''final''\n    ORDER BY c.return_id\n  LOOP\n    candidate_identity:=vat_finalization_basis_identity(candidate.snapshot_id);\n    match_kind:=CASE\n      WHEN p_application_path=''legacy'' THEN ''legacy_global''\n      WHEN candidate.subject_id=p_subject_id THEN ''same_subject''\n      WHEN candidate_identity->>''taxpayerCorpNum''=target_identity->>''taxpayerCorpNum''\n        AND candidate_identity->>''filingUnit''=target_identity->>''filingUnit'' THEN ''same_taxpayer_unit''\n      ELSE NULL END;\n    IF match_kind IS NOT NULL THEN\n      conflicts:=conflicts||jsonb_build_array(jsonb_build_object(''origin'',''basis_return'',''returnId'',candidate.return_id,\n        ''confirmationId'',candidate.confirmation_id,''subjectId'',candidate.subject_id,\n        ''year'',candidate.period_year,''term'',candidate.period_term,''kind'',''final'',''subjectResolution'',''exact'',\n        ''taxpayerCorpNum'',candidate_identity->>''taxpayerCorpNum'',''filingUnit'',candidate_identity->>''filingUnit'',\n        ''matchKind'',match_kind));\n    END IF;\n  END LOOP;\n  SELECT COALESCE(jsonb_agg(item ORDER BY item->>''origin'',item->>''returnId''),''[]''::jsonb)\n    INTO conflicts FROM jsonb_array_elements(conflicts) item;\n  RETURN conflicts;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_subject_id text, p_period_year integer, p_period_term integer, p_period_kind text, p_application_path text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"text, integer, integer, text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_finalization_fence","rows":"0","binary":null,"config":null,"result":"void","source":"\nBEGIN\n  IF p_period_year IS NULL OR p_period_year NOT BETWEEN 1000 AND 9999\n    OR p_period_term IS NULL OR p_period_term NOT IN(1,2)\n  THEN RAISE EXCEPTION ''VAT finalization period is invalid'' USING ERRCODE=''23514''; END IF;\n  PERFORM pg_advisory_xact_lock(1296256326,1);\n  INSERT INTO vat_finalization_fences(key,generation)\n    VALUES(''final:''||p_period_year::text||'':''||p_period_term::text,1)\n    ON CONFLICT(key) DO UPDATE SET generation=vat_finalization_fences.generation+1;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_period_year integer, p_period_term integer","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"integer, integer","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_finalization_identity_version","rows":"0","binary":null,"config":null,"result":"text","source":" SELECT ''vat-finalization-taxpayer-v1''::text ","strict":false,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_assert_consumable","rows":"0","binary":null,"config":null,"result":"void","source":"\nDECLARE rev vat_followup_review_revisions%ROWTYPE; root vat_followup_review_roots%ROWTYPE;\n  p vat_followup_review_pairs%ROWTYPE; b vat_filing_basis_snapshots%ROWTYPE; f vat_filing_fact_revisions%ROWTYPE;\n  subject_json jsonb; archive jsonb; claim jsonb; historical jsonb; current_source jsonb; actual_claims jsonb;\nBEGIN\n  SELECT * INTO STRICT rev FROM vat_followup_review_revisions WHERE revision_id=entry->>''revisionId'';\n  PERFORM vat_followup_fence(''review:''||rev.review_id);\n  SELECT * INTO STRICT root FROM vat_followup_review_roots WHERE review_id=rev.review_id;\n  SELECT * INTO STRICT p FROM vat_followup_review_pairs WHERE revision_id=rev.revision_id AND line_no=(entry->>''pairLineNo'')::integer;\n  IF p.legacy_return_id IS NOT NULL THEN PERFORM vat_followup_fence(''legacy:''||p.legacy_return_id); END IF;\n  IF rev.state<>''verified'' OR EXISTS(SELECT 1 FROM vat_followup_review_revisions r WHERE r.review_id=rev.review_id AND r.version>rev.version)\n    OR EXISTS(SELECT 1 FROM vat_followup_review_consumptions c WHERE c.revision_id=rev.revision_id AND c.pair_line_no=p.line_no)\n    OR rev.payload_json->''application'' IS DISTINCT FROM app OR p.pair_json IS DISTINCT FROM entry->''pair''\n    OR p.pair_json->''issues'' IS DISTINCT FROM ''[]''::jsonb\n    OR p.pair_json->''databaseProof'' IS DISTINCT FROM vat_followup_database_proof(p.card_source_id,p.invoice_source_id,p.legacy_return_id,p.past_basis_snapshot_id,p.past_fact_revision_id)\n    OR NOT vat_followup_server_document(''vat-document:''||p.document_id,p.document_hash,root.subject_id)\n  THEN RAISE EXCEPTION ''VAT followup review is stale, consumed, or not verified'' USING ERRCODE=''23514''; END IF;\n  SELECT payload_json INTO STRICT subject_json FROM vat_filing_subject_revisions\n    WHERE revision_id=app->>''subjectRevisionId'' AND subject_id=root.subject_id;\n  IF vat_followup_hash(subject_json) IS DISTINCT FROM app->>''subjectHash''\n    OR subject_json->>''corpNum'' IS DISTINCT FROM root.collector_corp_num\n    OR subject_json->>''state'' IS DISTINCT FROM ''verified'' OR subject_json->>''entityType'' IS DISTINCT FROM ''corporation''\n    OR subject_json->>''vatRegime'' IS DISTINCT FROM ''general'' OR subject_json->>''filingUnit'' IS DISTINCT FROM ''single_business_place''\n    OR NOT vat_followup_server_document(subject_json->>''evidenceRef'',subject_json->>''evidenceHash'',root.subject_id)\n    OR EXISTS(SELECT 1 FROM vat_filing_subject_revisions r WHERE r.subject_id=root.subject_id AND r.version>(subject_json->>''version'')::integer\n      AND r.payload_json->>''effectiveFrom''<=root.date_to AND (r.payload_json->>''effectiveTo'' IS NULL OR r.payload_json->>''effectiveTo''>=app->>''priorFrom''))\n  THEN RAISE EXCEPTION ''VAT followup current subject evidence mismatch'' USING ERRCODE=''23514''; END IF;\n  claim:=p.pair_json#>''{past,claim}''; historical:=p.pair_json->p.historical_side;\n  current_source:=p.pair_json->(CASE p.historical_side WHEN ''card'' THEN ''invoice'' ELSE ''card'' END);\n  IF NOT vat_followup_money(claim->''claimedTax'') OR (claim->>''claimedTax'')::numeric<=0\n    OR (claim->>''claimedTax'')::numeric>(claim->>''tax'')::numeric\n    OR entry->''priorClaimedTax'' IS DISTINCT FROM claim->''claimedTax''\n    OR historical->''claimedTax'' IS DISTINCT FROM claim->''claimedTax''\n    OR entry->''currentClaimableTax'' IS DISTINCT FROM current_source->''claimTax''\n    OR NOT vat_followup_money(current_source->''claimTax'') OR (current_source->>''claimTax'')::numeric<=0\n  THEN RAISE EXCEPTION ''VAT followup prior/current claim mismatch'' USING ERRCODE=''23514''; END IF;\n  IF p.past_origin=''legacy'' THEN\n    SELECT to_jsonb(r) INTO STRICT archive FROM vat_returns r WHERE r.return_id=p.legacy_return_id;\n    IF archive IS DISTINCT FROM p.pair_json#>''{past,archive}'' OR archive->>''status''<>''confirmed'' OR archive->>''period_kind''<>''pre''\n      OR p.pair_json#>>''{past,evidenceVerification}'' IS DISTINCT FROM ''legacy_internal_snapshot_only''\n    THEN RAISE EXCEPTION ''VAT followup historical legacy evidence changed'' USING ERRCODE=''23514''; END IF;\n    SELECT COALESCE(jsonb_agg(jsonb_build_object(''sourceKind'',e->''kind'',''sourceId'',e->''sourceId'',''canonicalKey'',e->''canonicalKey'',\n      ''sourceHash'',e->''sourceHash'',''direction'',''purchase'',''supply'',e->''supply'',''tax'',e->''tax'',''claimedTax'',e->''tax'',''date'',e->''date'')),''[]''::jsonb)\n      INTO actual_claims FROM jsonb_array_elements(archive#>''{form_json,duplicateReview,claimSources}'') e\n      WHERE e->>''kind''=claim->>''sourceKind'' AND e->>''sourceId''=claim->>''sourceId'';\n  ELSE\n    SELECT * INTO STRICT b FROM vat_filing_basis_snapshots WHERE snapshot_id=p.past_basis_snapshot_id;\n    SELECT * INTO STRICT f FROM vat_filing_fact_revisions WHERE revision_id=p.past_fact_revision_id;\n    IF b.subject_id<>root.subject_id OR b.scope_json IS DISTINCT FROM p.pair_json#>''{past,archive}''\n      OR b.snapshot_id IS DISTINCT FROM root.basis_snapshot_id OR f.state<>''verified'' OR f.kind<>''filing''\n      OR f.payload_json#>>''{data,sourceReconciliation}'' IS DISTINCT FROM ''complete''\n      OR p.pair_json#>>''{past,evidenceVerification}'' IS DISTINCT FROM ''server_document_verified''\n      OR NOT vat_followup_server_document(f.payload_json->>''evidenceRef'',f.payload_json->>''evidenceHash'',root.subject_id)\n      OR NOT EXISTS(SELECT 1 FROM vat_filing_basis_consumptions c WHERE c.consumption_id=p.pair_json#>>''{past,consumptionId}''\n        AND c.snapshot_id=b.snapshot_id AND c.revision_id=f.revision_id AND c.kind=''filing'')\n    THEN RAISE EXCEPTION ''VAT followup historical filing evidence changed'' USING ERRCODE=''23514''; END IF;\n    SELECT payload_json INTO STRICT subject_json FROM vat_filing_subject_revisions WHERE revision_id=b.subject_revision_id;\n    IF NOT vat_followup_server_document(subject_json->>''evidenceRef'',subject_json->>''evidenceHash'',root.subject_id)\n    THEN RAISE EXCEPTION ''VAT followup historical subject document unavailable'' USING ERRCODE=''23514''; END IF;\n    SELECT COALESCE(jsonb_agg(e),''[]''::jsonb) INTO actual_claims FROM jsonb_array_elements(f.payload_json->''sourceCoverage'') e\n      WHERE e->>''canonicalKey''=claim->>''canonicalKey'' AND e->>''sourceKind''=claim->>''sourceKind'' AND e->>''sourceId''=claim->>''sourceId'';\n  END IF;\n  IF actual_claims IS DISTINCT FROM jsonb_build_array(claim)\n  THEN RAISE EXCEPTION ''VAT followup exact historical claimed amount unavailable'' USING ERRCODE=''23514''; END IF;\n  IF EXISTS(SELECT 1 FROM transaction_links l WHERE l.relation IN(''card_invoice'',''distinct'')\n    AND l.left_kind=''card'' AND l.left_id=p.card_source_id AND (l.right_id=p.invoice_source_id OR l.right_snapshot->>''canonicalKey''=p.pair_json#>>''{invoice,canonicalKey}'')\n    AND (l.state=''active'' OR l.relation=''card_invoice'' AND l.state=''cancelled''))\n  THEN RAISE EXCEPTION ''VAT followup pair is already resolved or conflicts with a supply link'' USING ERRCODE=''23514''; END IF;\nEXCEPTION WHEN no_data_found THEN RAISE EXCEPTION ''VAT followup current evidence reference missing'' USING ERRCODE=''23514'';\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"entry jsonb, app jsonb","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"jsonb, jsonb","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_base_projection_v2","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\n  SELECT (form-ARRAY[''generatedAt'',''warnings'',''ledgerSnapshot'',''followupConsumption'',''filingBasis''])\n    || CASE WHEN form ? ''filingBasis'' THEN jsonb_build_object(''filingBasis'',(form->''filingBasis'')-''calculationHash'') ELSE ''{}''::jsonb END\n    || jsonb_build_object(''ledgerRows'',form#>''{ledgerSnapshot,rows}'')\n","strict":true,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"form jsonb","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"jsonb","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_basis_v2_guard","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE r vat_filing_return_revisions%ROWTYPE; fc jsonb; e jsonb;\nBEGIN\n  IF TG_TABLE_NAME=''vat_filing_return_revisions'' THEN r:=NEW;\n  ELSE SELECT * INTO STRICT r FROM vat_filing_return_revisions WHERE return_id=NEW.return_id; END IF;\n  IF r.schema_version=''vat-return-basis-v1'' THEN\n    IF r.form_json ? ''followupConsumption'' THEN RAISE EXCEPTION ''V1 VAT return cannot consume followup review'' USING ERRCODE=''23514''; END IF;\n    RETURN NEW;\n  END IF;\n  fc:=vat_followup_validate_form_v2(r.form_json,''basis'',r.basis_snapshot_id);\n  IF r.calculation_hash IS DISTINCT FROM fc->>''calculationHash''\n  THEN RAISE EXCEPTION ''VAT followup stored calculation hash mismatch'' USING ERRCODE=''23514''; END IF;\n  IF TG_TABLE_NAME=''vat_filing_return_confirmations'' THEN\n    IF r.form_json->''blockingIssues'' IS DISTINCT FROM ''[]''::jsonb\n    THEN RAISE EXCEPTION ''Unresolved VAT followup return cannot be confirmed'' USING ERRCODE=''23514''; END IF;\n    FOR e IN SELECT value FROM jsonb_array_elements(fc->''pairs'') LOOP PERFORM vat_followup_assert_consumable(e,fc->''application''); END LOOP;\n  END IF;\n  RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_canonical_v2","rows":"0","binary":null,"config":null,"result":"text","source":"\nDECLARE result text; n numeric; scalar text;\nBEGIN\n  CASE jsonb_typeof(v)\n    WHEN ''object'' THEN\n      SELECT ''{''||COALESCE(string_agg(vat_followup_canonical_v2(to_jsonb(k))||'':''||vat_followup_canonical_v2(x),'','' ORDER BY k COLLATE \"C\"),'''')||''}''\n        INTO result FROM jsonb_each(v) e(k,x);\n    WHEN ''array'' THEN\n      SELECT ''[''||COALESCE(string_agg(vat_followup_canonical_v2(x),'','' ORDER BY ord),'''')||'']''\n        INTO result FROM jsonb_array_elements(v) WITH ORDINALITY e(x,ord);\n    WHEN ''number'' THEN\n      n:=(v#>>''{}'')::numeric;\n      IF n<>trunc(n) OR abs(n)>9007199254740991\n      THEN RAISE EXCEPTION ''VAT canonical v2 requires safe integers'' USING ERRCODE=''23514''; END IF;\n      result:=trunc(n)::text;\n    WHEN ''string'' THEN\n      scalar:=v#>>''{}'';\n      -- jsonb/UTF8 입력 자체도 NUL과 잘못된 surrogate를 거절한다.\n      IF position(decode(''00'',''hex'') IN convert_to(scalar,''UTF8''))>0\n      THEN RAISE EXCEPTION ''VAT canonical v2 does not allow null characters'' USING ERRCODE=''23514''; END IF;\n      result:=to_json(scalar)::text;\n    WHEN ''boolean'' THEN result:=v::text;\n    WHEN ''null'' THEN result:=''null'';\n    ELSE RAISE EXCEPTION ''Unsupported VAT canonical v2 value'' USING ERRCODE=''23514'';\n  END CASE;\n  RETURN result;\nEND ","strict":true,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"v jsonb","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"jsonb","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_complete_guard","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE r vat_followup_review_revisions%ROWTYPE; request vat_followup_review_requests%ROWTYPE; actual jsonb; rid text;\nBEGIN\n IF TG_TABLE_NAME=''vat_followup_review_roots'' THEN\n  IF NOT EXISTS(SELECT 1 FROM vat_followup_review_revisions WHERE review_id=NEW.review_id)\n  THEN RAISE EXCEPTION ''VAT followup root has no revision'' USING ERRCODE=''23514''; END IF;\n  RETURN NEW;\n ELSIF TG_TABLE_NAME=''vat_followup_review_requests'' THEN\n  SELECT revision_id INTO rid FROM vat_followup_review_revisions WHERE request_id=NEW.request_id;\n ELSE rid:=NEW.revision_id; END IF;\n SELECT * INTO STRICT r FROM vat_followup_review_revisions WHERE revision_id=rid;\n SELECT * INTO STRICT request FROM vat_followup_review_requests WHERE request_id=r.request_id;\n SELECT COALESCE(jsonb_agg(pair_json ORDER BY line_no),''[]''::jsonb) INTO actual FROM vat_followup_review_pairs WHERE revision_id=r.revision_id;\n IF actual IS DISTINCT FROM r.payload_json->''pairs''\n  OR request.actor_user_id<>r.actor_user_id OR request.action IS DISTINCT FROM (CASE r.state WHEN ''withdrawn'' THEN ''withdraw'' ELSE ''save'' END)\n  OR request.result_json->>''reviewId'' IS DISTINCT FROM r.review_id OR request.result_json->>''revisionId'' IS DISTINCT FROM r.revision_id\n  OR request.result_json->>''version'' IS DISTINCT FROM r.version::text OR request.result_json->>''state'' IS DISTINCT FROM r.state\n  OR request.result_json->>''applicationStatus'' IS DISTINCT FROM ''not_integrated_in_ca''\n THEN RAISE EXCEPTION ''VAT followup complete payload/request mismatch'' USING ERRCODE=''23514''; END IF;\n RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_consumption_complete","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE form jsonb; fc jsonb; actual jsonb; target_id text; path text; basis_id text;\nBEGIN\n  IF TG_TABLE_NAME=''vat_returns'' THEN\n    SELECT form_json INTO form FROM vat_returns WHERE return_id=NEW.return_id AND status=''confirmed'';\n    IF form IS NULL OR NOT(form ? ''followupConsumption'') THEN RETURN NULL; END IF;\n    SELECT archive_id INTO target_id FROM vat_followup_legacy_archives WHERE return_id=NEW.return_id;\n    path:=''legacy'';\n  ELSIF TG_TABLE_NAME=''vat_followup_legacy_archives'' THEN target_id:=NEW.archive_id; path:=''legacy'';\n  ELSIF TG_TABLE_NAME=''vat_filing_return_confirmations'' THEN\n    target_id:=NEW.confirmation_id; path:=''basis'';\n  ELSE\n    path:=CASE WHEN NEW.basis_confirmation_id IS NOT NULL THEN ''basis'' ELSE ''legacy'' END;\n    target_id:=COALESCE(NEW.basis_confirmation_id,NEW.legacy_archive_id);\n  END IF;\n  IF target_id IS NULL THEN RAISE EXCEPTION ''Confirmed legacy followup return has no immutable archive'' USING ERRCODE=''23514''; END IF;\n  IF path=''basis'' THEN\n    SELECT r.form_json,r.basis_snapshot_id INTO STRICT form,basis_id FROM vat_filing_return_confirmations c\n      JOIN vat_filing_return_revisions r ON r.return_id=c.return_id WHERE c.confirmation_id=target_id;\n    IF NOT(form ? ''followupConsumption'') THEN RETURN NULL; END IF;\n    SELECT COALESCE(jsonb_agg(c.payload_json ORDER BY c.payload_json->>''revisionId'' COLLATE \"C\",c.pair_line_no),''[]''::jsonb)\n      INTO actual FROM vat_followup_review_consumptions c WHERE c.basis_confirmation_id=target_id;\n  ELSE\n    SELECT a.form_json INTO STRICT form FROM vat_followup_legacy_archives a WHERE a.archive_id=target_id;\n    SELECT COALESCE(jsonb_agg(c.payload_json ORDER BY c.payload_json->>''revisionId'' COLLATE \"C\",c.pair_line_no),''[]''::jsonb)\n      INTO actual FROM vat_followup_review_consumptions c WHERE c.legacy_archive_id=target_id;\n  END IF;\n  fc:=vat_followup_validate_form_v2(form,path,basis_id);\n  IF actual IS DISTINCT FROM fc->''pairs''\n  THEN RAISE EXCEPTION ''Confirmed VAT followup form and consumed pairs do not match exactly'' USING ERRCODE=''23514''; END IF;\n  RETURN NULL;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_consumption_guard","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE form jsonb; fc jsonb; path text; basis_id text; actor text; target_hash text;\nBEGIN\n  PERFORM pg_advisory_xact_lock(1296256326,1);\n  IF NEW.basis_confirmation_id IS NOT NULL THEN\n    SELECT r.form_json,r.basis_snapshot_id,c.confirmed_by,c.calculation_hash INTO STRICT form,basis_id,actor,target_hash\n      FROM vat_filing_return_confirmations c JOIN vat_filing_return_revisions r ON r.return_id=c.return_id\n      WHERE c.confirmation_id=NEW.basis_confirmation_id AND r.schema_version=''vat-return-basis-v2'';\n    path:=''basis'';\n  ELSE\n    SELECT a.form_json,a.created_by,a.calculation_hash INTO STRICT form,actor,target_hash\n      FROM vat_followup_legacy_archives a WHERE a.archive_id=NEW.legacy_archive_id;\n    path:=''legacy''; basis_id:=NULL;\n  END IF;\n  fc:=vat_followup_validate_form_v2(form,path,basis_id);\n  IF NEW.payload_json->>''revisionId'' IS DISTINCT FROM NEW.revision_id\n    OR NEW.payload_json->''pairLineNo'' IS DISTINCT FROM to_jsonb(NEW.pair_line_no)\n    OR NEW.calculation_hash IS DISTINCT FROM target_hash OR NEW.calculation_hash IS DISTINCT FROM fc->>''calculationHash''\n    OR NEW.created_by IS DISTINCT FROM actor OR form->''blockingIssues'' IS DISTINCT FROM ''[]''::jsonb\n    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(fc->''pairs'') e WHERE e=NEW.payload_json)\n  THEN RAISE EXCEPTION ''VAT followup consumption target/pair mismatch'' USING ERRCODE=''23514''; END IF;\n  PERFORM vat_followup_assert_consumable(NEW.payload_json,fc->''application'');\n  RETURN NEW;\nEXCEPTION WHEN no_data_found THEN RAISE EXCEPTION ''VAT followup actual v2 confirmation target missing'' USING ERRCODE=''23514'';\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_consumption_version","rows":"0","binary":null,"config":null,"result":"text","source":" SELECT ''vat-followup-consumption-v2''::text ","strict":false,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_database_proof","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE card_row jsonb; invoice_row jsonb; official text; proof jsonb;\nBEGIN\n SELECT to_jsonb(t) INTO STRICT card_row FROM card_transactions t WHERE t.card_txn_id=vat_followup_database_proof.card_id;\n SELECT to_jsonb(t),btrim(t.nts_send_key) INTO STRICT invoice_row,official FROM hometax_tax_invoices t WHERE t.hti_id=vat_followup_database_proof.invoice_id;\n proof:=jsonb_build_object(''card'',card_row,''invoice'',invoice_row,\n  ''cardReview'',(SELECT to_jsonb(r) FROM card_tax_reviews r WHERE r.card_txn_id=vat_followup_database_proof.card_id),\n  ''merchant'',(SELECT to_jsonb(m) FROM card_merchant_corrections m WHERE m.card_txn_id=vat_followup_database_proof.card_id ORDER BY m.version DESC LIMIT 1),\n  ''refundPeers'',COALESCE((SELECT jsonb_agg(jsonb_build_object(''source'',to_jsonb(t),''review'',to_jsonb(r)) ORDER BY t.card_txn_id)\n   FROM card_transactions t LEFT JOIN card_tax_reviews r ON r.card_txn_id=t.card_txn_id\n   WHERE r.original_card_txn_id=vat_followup_database_proof.card_id OR (t.card_id=card_row->>''card_id'' AND NULLIF(t.approval_num,'''')=NULLIF(card_row->>''approval_num'',''''))),''[]''::jsonb),\n  ''hometaxAliases'',COALESCE((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.hti_id) FROM hometax_tax_invoices t WHERE btrim(t.nts_send_key)=official),''[]''::jsonb),\n  ''appAliases'',COALESCE((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.invoice_id) FROM tax_invoices t WHERE btrim(t.nts_send_key)=official),''[]''::jsonb),\n  ''links'',COALESCE((SELECT jsonb_agg(to_jsonb(l) ORDER BY l.link_id) FROM transaction_links l\n   WHERE (l.left_kind=''card'' AND l.left_id=vat_followup_database_proof.card_id) OR (l.right_kind=''hometax'' AND l.right_id=vat_followup_database_proof.invoice_id)\n     OR l.right_snapshot->>''canonicalKey''=''invoice:''||official),''[]''::jsonb),\n  ''recognitions'',COALESCE((SELECT jsonb_agg(r1_recognition_followup_projection(r) ORDER BY r.recognition_id) FROM transaction_invoice_recognitions r\n   WHERE r.canonical_invoice_key=''invoice:''||official),''[]''::jsonb),\n  ''legacy'',(SELECT to_jsonb(r) FROM vat_returns r WHERE r.return_id=vat_followup_database_proof.legacy_return_id),\n  ''basis'',(SELECT to_jsonb(b) FROM vat_filing_basis_snapshots b WHERE b.snapshot_id=vat_followup_database_proof.basis_snapshot_id),\n  ''fact'',(SELECT to_jsonb(f) FROM vat_filing_fact_revisions f WHERE f.revision_id=vat_followup_database_proof.fact_revision_id),\n  ''consumptions'',COALESCE((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.consumption_id) FROM vat_filing_basis_consumptions c\n   WHERE c.snapshot_id=vat_followup_database_proof.basis_snapshot_id AND c.revision_id=vat_followup_database_proof.fact_revision_id),''[]''::jsonb));\n RETURN jsonb_build_object(''version'',''vat-followup-db-v1'',''digest'',vat_followup_hash(proof));\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"card_id text, invoice_id text, legacy_return_id text DEFAULT NULL::text, basis_snapshot_id text DEFAULT NULL::text, fact_revision_id text DEFAULT NULL::text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"text, text, text, text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_date","rows":"0","binary":null,"config":null,"result":"boolean","source":"\nBEGIN\n RETURN v IS NOT NULL AND v ~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}$''\n   AND left(v,4)::integer BETWEEN 1000 AND 9999 AND v::date::text=v;\nEXCEPTION WHEN OTHERS THEN RETURN false;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"v text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"text","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_fence","rows":"0","binary":null,"config":null,"result":"void","source":"\nBEGIN\n PERFORM pg_advisory_xact_lock(1296256326,1);\n INSERT INTO vat_followup_review_fences(key,generation) VALUES(k,1)\n ON CONFLICT(key) DO UPDATE SET generation=vat_followup_review_fences.generation+1;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"k text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"text","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_hash","rows":"0","binary":null,"config":null,"result":"text","source":"\n SELECT encode(sha256(convert_to(vat_post_canonical(v),''UTF8'')),''hex'')\n","strict":true,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"v jsonb","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"jsonb","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_hash_v2","rows":"0","binary":null,"config":null,"result":"text","source":" SELECT encode(sha256(convert_to(vat_followup_canonical_v2(v),''UTF8'')),''hex'') ","strict":true,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"v jsonb","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"jsonb","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_legacy_archive_guard","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE row_now jsonb; fc jsonb;\nBEGIN\n  PERFORM vat_followup_fence(''legacy:''||NEW.return_id);\n  SELECT to_jsonb(r) INTO STRICT row_now FROM vat_returns r WHERE r.return_id=NEW.return_id;\n  fc:=vat_followup_validate_form_v2(NEW.form_json,''legacy'',NULL);\n  IF row_now IS DISTINCT FROM NEW.row_json OR row_now->''form_json'' IS DISTINCT FROM NEW.form_json\n    OR row_now->>''status'' IS DISTINCT FROM ''confirmed'' OR row_now->>''period_kind'' IS DISTINCT FROM ''final''\n    OR NEW.calculation_hash IS DISTINCT FROM fc->>''calculationHash''\n    OR NEW.created_by IS DISTINCT FROM row_now->>''confirmed_by''\n  THEN RAISE EXCEPTION ''VAT followup immutable legacy archive mismatch'' USING ERRCODE=''23514''; END IF;\n  RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_legacy_write_guard","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE fc jsonb; e jsonb;\nBEGIN\n  IF TG_OP IN(''UPDATE'',''DELETE'') THEN\n    PERFORM vat_followup_fence(''legacy:''||OLD.return_id);\n    IF EXISTS(SELECT 1 FROM vat_followup_legacy_archives a WHERE a.return_id=OLD.return_id)\n      OR EXISTS(SELECT 1 FROM vat_followup_review_consumptions c JOIN vat_followup_review_pairs p ON p.revision_id=c.revision_id AND p.line_no=c.pair_line_no WHERE p.legacy_return_id=OLD.return_id)\n    THEN\n      IF TG_OP=''UPDATE'' AND to_jsonb(NEW) IS NOT DISTINCT FROM to_jsonb(OLD) THEN RETURN NEW; END IF;\n      RAISE EXCEPTION ''Consumed VAT legacy evidence cannot be changed or removed'' USING ERRCODE=''23514'';\n    END IF;\n    IF TG_OP=''DELETE'' THEN RETURN OLD; END IF;\n  END IF;\n  IF NOT(NEW.form_json ? ''followupConsumption'') THEN RETURN NEW; END IF;\n  fc:=vat_followup_validate_form_v2(NEW.form_json,''legacy'',NULL);\n  IF to_jsonb(NEW.period_year) IS DISTINCT FROM fc#>''{application,year}'' OR to_jsonb(NEW.period_term) IS DISTINCT FROM fc#>''{application,term}''\n    OR NEW.period_kind<>''final'' OR NEW.date_from IS DISTINCT FROM fc#>>''{application,dateFrom}'' OR NEW.date_to IS DISTINCT FROM fc#>>''{application,dateTo}''\n  THEN RAISE EXCEPTION ''VAT followup legacy row period mismatch'' USING ERRCODE=''23514''; END IF;\n  IF NEW.status=''confirmed'' THEN\n    IF NEW.form_json->''blockingIssues'' IS DISTINCT FROM ''[]''::jsonb\n    THEN RAISE EXCEPTION ''Unresolved legacy VAT followup return cannot be confirmed'' USING ERRCODE=''23514''; END IF;\n    FOR e IN SELECT value FROM jsonb_array_elements(fc->''pairs'') LOOP PERFORM vat_followup_assert_consumable(e,fc->''application''); END LOOP;\n  END IF;\n  RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_money","rows":"0","binary":null,"config":null,"result":"boolean","source":"\nDECLARE n numeric;\nBEGIN\n IF jsonb_typeof(v) IS DISTINCT FROM ''number'' THEN RETURN false; END IF;\n n:=(v#>>''{}'')::numeric;\n RETURN n>=0 AND n<=9007199254740991 AND n=trunc(n);\nEXCEPTION WHEN OTHERS THEN RETURN false;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"v jsonb","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"jsonb","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_no_consumption","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nBEGIN RAISE EXCEPTION ''C-a review consumption is not supported; C-b confirmation integration is required'' USING ERRCODE=''23514''; END ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_no_mutation","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nBEGIN RAISE EXCEPTION ''VAT followup evidence is immutable: %'',TG_TABLE_NAME USING ERRCODE=''23514''; END ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_pair_guard","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE rev vat_followup_review_revisions%ROWTYPE; root vat_followup_review_roots%ROWTYPE;\n p jsonb; past jsonb; historical jsonb; current_source jsonb; claim jsonb; s jsonb; field text;\n d vat_filing_documents%ROWTYPE; archive jsonb; bs vat_filing_basis_snapshots%ROWTYPE;\n fact vat_filing_fact_revisions%ROWTYPE; sub jsonb; card_row card_transactions%ROWTYPE;\n invoice_row hometax_tax_invoices%ROWTYPE; tax_review card_tax_reviews%ROWTYPE;\n corrected record; effective_corp text; card_supply numeric; card_tax numeric; card_total numeric;\n allocated_supply numeric; allocated_tax numeric; invoice_alloc_supply numeric; invoice_alloc_tax numeric;\n expected_claim jsonb; form jsonb;\nBEGIN\n PERFORM pg_advisory_xact_lock(1296256326,1);\n SELECT * INTO STRICT rev FROM vat_followup_review_revisions WHERE revision_id=NEW.revision_id;\n SELECT * INTO STRICT root FROM vat_followup_review_roots WHERE review_id=rev.review_id;\n p:=NEW.pair_json; past:=p->''past''; claim:=past->''claim'';\n IF rev.payload_json->''pairs''->NEW.line_no IS DISTINCT FROM p\n  OR p->>''pairKey'' IS DISTINCT FROM NEW.pair_key\n  OR NEW.pair_key IS DISTINCT FROM vat_followup_hash(jsonb_build_array(''card'',NEW.card_source_id,''hometax'',NEW.invoice_source_id))\n  OR p#>>''{card,kind}'' IS DISTINCT FROM ''card''\n  OR p#>>''{invoice,kind}'' IS DISTINCT FROM ''hometax''\n  OR p#>>''{card,id}'' IS DISTINCT FROM NEW.card_source_id OR p#>>''{invoice,id}'' IS DISTINCT FROM NEW.invoice_source_id\n  OR p#>>''{card,sourceHash}'' IS DISTINCT FROM NEW.card_source_hash OR p#>>''{invoice,sourceHash}'' IS DISTINCT FROM NEW.invoice_source_hash\n  OR p->>''historicalSide'' IS DISTINCT FROM NEW.historical_side OR past->>''origin'' IS DISTINCT FROM NEW.past_origin\n  OR past->>''legacyReturnId'' IS DISTINCT FROM NEW.legacy_return_id OR past->>''basisSnapshotId'' IS DISTINCT FROM NEW.past_basis_snapshot_id\n  OR past->>''factRevisionId'' IS DISTINCT FROM NEW.past_fact_revision_id OR past->>''subjectId'' IS DISTINCT FROM root.subject_id\n  OR p#>>''{document,documentId}'' IS DISTINCT FROM NEW.document_id OR p#>>''{document,evidenceHash}'' IS DISTINCT FROM NEW.document_hash\n  OR jsonb_typeof(p->''issues'') IS DISTINCT FROM ''array''\n  OR COALESCE(length(btrim(p->>''evidenceLocation'')),0) NOT BETWEEN 1 AND 1000\n  OR COALESCE(length(btrim(p->>''reason'')),0) NOT BETWEEN 1 AND 4000\n THEN RAISE EXCEPTION ''VAT followup pair/payload projection mismatch'' USING ERRCODE=''23514''; END IF;\n -- 철회는 기존 원문을 그대로 보존한다. 현재 원천이 바뀌었다는 이유로 미소비 철회를 막지 않는다.\n IF rev.state=''withdrawn'' THEN\n  IF NOT EXISTS(SELECT 1 FROM vat_followup_review_pairs prior_pair WHERE prior_pair.revision_id=rev.previous_revision_id AND prior_pair.line_no=NEW.line_no AND prior_pair.pair_json=p)\n  THEN RAISE EXCEPTION ''Withdrawal pair differs from previous review'' USING ERRCODE=''23514''; END IF;\n  RETURN NEW;\n END IF;\n SELECT * INTO STRICT d FROM vat_filing_documents WHERE document_id=NEW.document_id;\n IF d.subject_id<>root.subject_id OR d.content_sha256<>NEW.document_hash OR encode(sha256(d.content_bytes),''hex'')<>NEW.document_hash\n  OR octet_length(d.content_bytes)<>d.size_bytes\n THEN RAISE EXCEPTION ''VAT followup evidence document mismatch'' USING ERRCODE=''23514''; END IF;\n IF p->''databaseProof'' IS DISTINCT FROM vat_followup_database_proof(NEW.card_source_id,NEW.invoice_source_id,NEW.legacy_return_id,NEW.past_basis_snapshot_id,NEW.past_fact_revision_id)\n THEN RAISE EXCEPTION ''VAT followup current database proof changed'' USING ERRCODE=''23514''; END IF;\n FOREACH field IN ARRAY ARRAY[''card'',''invoice''] LOOP\n  s:=p->field;\n  IF s->>''direction'' IS DISTINCT FROM ''purchase'' OR s->>''hashVersion'' IS DISTINCT FROM ''transaction-source-v1''\n   OR jsonb_typeof(s->''sourceBasis'') IS DISTINCT FROM ''object'' OR s#>>''{sourceBasis,version}'' IS DISTINCT FROM ''1''\n   OR s#>>''{sourceBasis,kind}'' IS DISTINCT FROM s->>''kind'' OR jsonb_typeof(s#>''{sourceBasis,raw}'') IS DISTINCT FROM ''object''\n   OR NOT vat_followup_date(s->>''date'') OR NOT vat_followup_date(s->>''accountingDate'')\n   OR COALESCE(length(s->>''canonicalKey''),0)=0 OR jsonb_typeof(s->''aliases'') IS DISTINCT FROM ''array''\n   OR NOT vat_followup_money(s->''supply'') OR NOT vat_followup_money(s->''tax'') OR NOT vat_followup_money(s->''total'')\n   OR NOT vat_followup_money(s->''claimSupply'') OR NOT vat_followup_money(s->''claimTax'') OR NOT vat_followup_money(s->''claimTotal'')\n   OR NOT vat_followup_money(s->''claimedTax'')\n   OR (s->>''total'')::numeric<>(s->>''supply'')::numeric+(s->>''tax'')::numeric\n   OR (s->>''claimTotal'')::numeric<>(s->>''claimSupply'')::numeric+(s->>''claimTax'')::numeric\n   OR (s->>''claimSupply'')::numeric>(s->>''supply'')::numeric OR (s->>''claimTax'')::numeric>(s->>''tax'')::numeric\n   OR (s->>''claimedTax'')::numeric>(s->>''claimTax'')::numeric\n  THEN RAISE EXCEPTION ''VAT followup source snapshot shape/amount mismatch'' USING ERRCODE=''23514''; END IF;\n END LOOP;\n IF past->>''archiveHash'' IS DISTINCT FROM vat_followup_hash(past->''archive'')\n  OR past->>''from'' IS DISTINCT FROM rev.payload_json#>>''{application,priorFrom}'' OR past->>''to'' IS DISTINCT FROM rev.payload_json#>>''{application,priorTo}''\n THEN RAISE EXCEPTION ''VAT followup historical archive hash/period mismatch'' USING ERRCODE=''23514''; END IF;\n IF NEW.past_origin=''legacy'' THEN\n  SELECT to_jsonb(r) INTO STRICT archive FROM vat_returns r WHERE r.return_id=NEW.legacy_return_id;\n  IF archive IS DISTINCT FROM past->''archive'' OR past->>''scopeHash'' IS NOT NULL OR past->>''consumptionId'' IS NOT NULL\n   OR archive->>''status'' IS DISTINCT FROM ''confirmed'' OR archive->>''period_kind'' IS DISTINCT FROM ''pre''\n   OR archive->>''period_year'' IS DISTINCT FROM root.period_year::text OR archive->>''period_term'' IS DISTINCT FROM root.period_term::text\n   OR archive->>''date_from'' IS DISTINCT FROM past->>''from'' OR archive->>''date_to'' IS DISTINCT FROM past->>''to''\n  THEN RAISE EXCEPTION ''VAT followup legacy confirmed archive mismatch'' USING ERRCODE=''23514''; END IF;\n ELSE\n  SELECT * INTO STRICT bs FROM vat_filing_basis_snapshots WHERE snapshot_id=NEW.past_basis_snapshot_id;\n  SELECT * INTO STRICT fact FROM vat_filing_fact_revisions WHERE revision_id=NEW.past_fact_revision_id;\n  IF bs.subject_id<>root.subject_id OR bs.period_year<>root.period_year OR bs.period_term<>root.period_term\n   OR bs.scope_json IS DISTINCT FROM past->''archive'' OR bs.scope_hash IS DISTINCT FROM past->>''scopeHash''\n   OR bs.scope_hash IS DISTINCT FROM vat_followup_hash(bs.scope_json-''scopeHash'')\n   OR fact.subject_id<>root.subject_id OR fact.kind<>''filing'' OR fact.state<>''verified''\n   OR fact.date_from<>past->>''from'' OR fact.date_to<>past->>''to''\n   OR NOT EXISTS(SELECT 1 FROM vat_filing_basis_consumptions c WHERE c.consumption_id=past->>''consumptionId''\n      AND c.snapshot_id=bs.snapshot_id AND c.revision_id=fact.revision_id AND c.fact_id=fact.fact_id AND c.subject_id=root.subject_id AND c.kind=''filing'')\n  THEN RAISE EXCEPTION ''VAT followup B1 filing consumption/archive mismatch'' USING ERRCODE=''23514''; END IF;\n END IF;\n IF rev.state<>''verified'' THEN RETURN NEW; END IF;\n IF jsonb_array_length(p->''issues'')<>0 THEN RAISE EXCEPTION ''Unresolved review cannot be verified'' USING ERRCODE=''23514''; END IF;\n IF EXISTS(SELECT 1 FROM vat_followup_review_pairs other_pair\n  JOIN vat_followup_review_revisions other_rev ON other_rev.revision_id=other_pair.revision_id\n  JOIN vat_followup_review_roots other_root ON other_root.review_id=other_rev.review_id\n  WHERE other_root.review_id<>root.review_id AND other_root.subject_id=root.subject_id\n    AND other_root.period_year=root.period_year AND other_root.period_term=root.period_term\n    AND other_root.application_path=root.application_path AND other_root.basis_snapshot_id IS NOT DISTINCT FROM root.basis_snapshot_id\n    AND other_rev.state=''verified'' AND other_pair.pair_key=NEW.pair_key\n    AND NOT EXISTS(SELECT 1 FROM vat_followup_review_revisions newer WHERE newer.review_id=other_rev.review_id AND newer.version>other_rev.version))\n THEN RAISE EXCEPTION ''Exact pair already has a current verified review in this application'' USING ERRCODE=''23514''; END IF;\n historical:=p->NEW.historical_side; current_source:=p->(CASE NEW.historical_side WHEN ''card'' THEN ''invoice'' ELSE ''card'' END);\n IF (current_source->>''claimTax'')::numeric<=0 OR (current_source->>''claimTotal'')::numeric<=0\n THEN RAISE EXCEPTION ''VAT followup current claim must have positive tax and total'' USING ERRCODE=''23514''; END IF;\n IF NOT vat_followup_money(claim->''supply'') OR NOT vat_followup_money(claim->''tax'') OR NOT vat_followup_money(claim->''claimedTax'')\n  OR (claim->>''claimedTax'')::numeric<=0 OR (claim->>''claimedTax'')::numeric>(claim->>''tax'')::numeric\n  OR claim->>''direction'' IS DISTINCT FROM ''purchase'' OR claim->>''canonicalKey'' IS DISTINCT FROM historical->>''canonicalKey''\n  OR claim->>''date'' IS DISTINCT FROM historical->>''date''\n  OR (claim->>''supply'')::numeric<>(historical->>''claimSupply'')::numeric OR (claim->>''tax'')::numeric<>(historical->>''claimTax'')::numeric\n  OR (claim->>''claimedTax'')::numeric<>(historical->>''claimedTax'')::numeric\n  OR historical->>''date''<past->>''from'' OR historical->>''date''>past->>''to''\n  OR current_source->>''date''<rev.payload_json#>>''{application,currentFrom}'' OR current_source->>''date''>root.date_to\n  OR past->>''origin'' IS DISTINCT FROM root.application_path\n  OR (root.application_path=''basis'' AND past->>''basisSnapshotId'' IS DISTINCT FROM root.basis_snapshot_id)\n  OR NOT ((claim->>''sourceKind''=historical->>''kind'' AND claim->>''sourceId''=historical->>''id'' AND claim->>''sourceHash''=historical->>''sourceHash'')\n    OR EXISTS(SELECT 1 FROM jsonb_array_elements(historical->''aliases'') a WHERE a->>''kind''=claim->>''sourceKind'' AND a->>''id''=claim->>''sourceId'' AND a->>''sourceHash''=claim->>''sourceHash'' AND a->''active''=''true''::jsonb))\n THEN RAISE EXCEPTION ''VAT followup prior claimed source mismatch'' USING ERRCODE=''23514''; END IF;\n IF NEW.past_origin=''basis'' THEN\n  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(fact.payload_json->''sourceCoverage'') c WHERE c=claim)\n   OR fact.payload_json#>>''{data,sourceReconciliation}'' IS DISTINCT FROM ''complete''\n   OR past->>''evidenceVerification'' IS DISTINCT FROM ''server_document_verified''\n   OR NOT vat_followup_server_document(fact.payload_json->>''evidenceRef'',fact.payload_json->>''evidenceHash'',root.subject_id)\n  THEN RAISE EXCEPTION ''VAT followup B1 declared claim/server evidence mismatch'' USING ERRCODE=''23514''; END IF;\n  SELECT payload_json INTO STRICT sub FROM vat_filing_subject_revisions WHERE revision_id=bs.subject_revision_id;\n  IF NOT vat_followup_server_document(sub->>''evidenceRef'',sub->>''evidenceHash'',root.subject_id)\n  THEN RAISE EXCEPTION ''VAT followup B1 subject server evidence unavailable'' USING ERRCODE=''23514''; END IF;\n ELSE\n  form:=archive->''form_json'';\n  IF form#>>''{duplicateReview,version}'' IS DISTINCT FROM ''g03b-r0-v1''\n   OR past->>''evidenceVerification'' IS DISTINCT FROM ''legacy_internal_snapshot_only''\n   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(form#>''{duplicateReview,claimSources}'') c\n    WHERE c->>''kind''=claim->>''sourceKind'' AND c->>''sourceId''=claim->>''sourceId'' AND c->>''canonicalKey''=claim->>''canonicalKey''\n     AND c->>''sourceHash''=claim->>''sourceHash'' AND c->>''date''=claim->>''date''\n     AND c->>''supply''=claim->>''supply'' AND c->>''tax''=claim->>''tax'' AND c->>''tax''=claim->>''claimedTax'')\n  THEN RAISE EXCEPTION ''VAT followup legacy claimed source unavailable'' USING ERRCODE=''23514''; END IF;\n END IF;\n -- 현재 DB 금액·주체·공제 핵심값을 별도 검증한다. JS alias/세무엔진 전체의 대체는 아니다.\n SELECT * INTO STRICT card_row FROM card_transactions WHERE card_txn_id=NEW.card_source_id;\n SELECT * INTO STRICT invoice_row FROM hometax_tax_invoices WHERE hti_id=NEW.invoice_source_id;\n SELECT * INTO tax_review FROM card_tax_reviews WHERE card_txn_id=NEW.card_source_id;\n SELECT * INTO corrected FROM card_merchant_corrections WHERE card_txn_id=NEW.card_source_id ORDER BY version DESC LIMIT 1;\n effective_corp:=CASE WHEN corrected.action=''correct'' THEN corrected.corp_num ELSE card_row.store_corp_num END;\n IF effective_corp IS NULL OR effective_corp !~ ''^[0-9[:space:]-]+$'' THEN effective_corp:=NULL;\n ELSE effective_corp:=regexp_replace(effective_corp,''[[:space:]-]'','''',''g''); END IF;\n IF card_row.approval_type<>''승인'' OR COALESCE(card_row.excluded,0)<>0 OR COALESCE(card_row.service_charge,0)<>0\n  OR card_row.supply_amount IS NULL OR card_row.tax_amount IS NULL OR card_row.supply_amount<0 OR card_row.tax_amount<0\n  OR card_row.amount_total<>card_row.supply_amount+card_row.tax_amount\n  OR p#>>''{card,canonicalKey}'' IS DISTINCT FROM ''card:''||NEW.card_source_id\n  OR (p#>>''{card,supply}'')::numeric<>card_row.supply_amount OR (p#>>''{card,tax}'')::numeric<>card_row.tax_amount OR (p#>>''{card,total}'')::numeric<>card_row.amount_total\n  OR p#>>''{card,accountingDate}'' IS DISTINCT FROM left(card_row.approved_at::text,10)\n  OR p#>>''{card,date}'' IS DISTINCT FROM COALESCE(NULLIF(tax_review.tax_date,''''),left(card_row.approved_at::text,10))\n  OR p#>>''{card,partyCorpNum}'' IS DISTINCT FROM effective_corp OR COALESCE(effective_corp,'''') !~ ''^[0-9]{10}$''\n  OR invoice_row.direction<>''purchase'' OR COALESCE(invoice_row.excluded,0)<>0\n  OR invoice_row.vat_deductible IS DISTINCT FROM 1\n  OR (p#>>''{invoice,supply}'')::numeric<>invoice_row.amount_total OR (p#>>''{invoice,tax}'')::numeric<>invoice_row.tax_total OR (p#>>''{invoice,total}'')::numeric<>invoice_row.total_amount\n  OR p#>>''{invoice,canonicalKey}'' IS DISTINCT FROM ''invoice:''||btrim(invoice_row.nts_send_key)\n  OR p#>>''{invoice,date}'' IS DISTINCT FROM left(invoice_row.write_date::text,10)\n  OR p#>>''{invoice,accountingDate}'' IS DISTINCT FROM left(invoice_row.write_date::text,10)\n  OR regexp_replace(COALESCE(invoice_row.invoicee_corp_num,''''),''[[:space:]-]'','''',''g'')<>root.collector_corp_num\n  OR p#>>''{invoice,partyCorpNum}'' IS DISTINCT FROM regexp_replace(COALESCE(invoice_row.invoicer_corp_num,''''),''[[:space:]-]'','''',''g'')\n  OR p#>>''{invoice,partyCorpNum}'' IS DISTINCT FROM p#>>''{card,partyCorpNum}''\n THEN RAISE EXCEPTION ''VAT followup current source amount/identity mismatch'' USING ERRCODE=''23514''; END IF;\n SELECT COALESCE(sum(supply),0),COALESCE(sum(tax),0) INTO allocated_supply,allocated_tax FROM transaction_links\n  WHERE state=''active'' AND relation=''card_invoice'' AND left_kind=''card'' AND left_id=NEW.card_source_id;\n IF (p#>>''{card,claimSupply}'')::numeric<>card_row.supply_amount-allocated_supply\n   OR (p#>>''{card,claimTax}'')::numeric<>card_row.tax_amount-allocated_tax\n   OR (p#>>''{invoice,claimSupply}'')::numeric<>invoice_row.amount_total OR (p#>>''{invoice,claimTax}'')::numeric<>invoice_row.tax_total\n   OR tax_review.decision IS DISTINCT FROM 1 OR NULLIF(btrim(tax_review.reason),'''') IS NULL OR NULLIF(btrim(tax_review.evidence_ref),'''') IS NULL\n THEN RAISE EXCEPTION ''VAT followup current deductible claim mismatch'' USING ERRCODE=''23514''; END IF;\n IF EXISTS(SELECT 1 FROM transaction_links l WHERE l.state=''active'' AND l.relation=''card_invoice''\n    AND l.left_kind=''card'' AND l.left_id=NEW.card_source_id\n    AND (l.right_id=NEW.invoice_source_id OR l.right_snapshot->>''canonicalKey''=p#>>''{invoice,canonicalKey}''))\n THEN RAISE EXCEPTION ''Same-supply allocation conflicts with distinct review'' USING ERRCODE=''23514''; END IF;\n RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_recorded_boundary","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE rev vat_followup_review_revisions%ROWTYPE; root vat_followup_review_roots%ROWTYPE;\n  card_row card_transactions%ROWTYPE; invoice_row hometax_tax_invoices%ROWTYPE;\n  basis vat_filing_basis_snapshots%ROWTYPE; fact vat_filing_fact_revisions%ROWTYPE;\n  p jsonb; past jsonb; historical jsonb; claim jsonb; claims jsonb; expected_claim jsonb;\n  old_subject jsonb; expected_grade text; card_sign integer;\nBEGIN\n  PERFORM pg_advisory_xact_lock(1296256326,1);\n  SELECT * INTO STRICT rev FROM vat_followup_review_revisions WHERE revision_id=NEW.revision_id;\n  IF rev.state<>''recorded'' THEN RETURN NEW; END IF;\n  SELECT * INTO STRICT root FROM vat_followup_review_roots WHERE review_id=rev.review_id;\n  p:=NEW.pair_json; past:=p->''past''; historical:=p->NEW.historical_side; claim:=past->''claim'';\n  SELECT * INTO STRICT card_row FROM card_transactions WHERE card_txn_id=NEW.card_source_id;\n  SELECT * INTO STRICT invoice_row FROM hometax_tax_invoices WHERE hti_id=NEW.invoice_source_id;\n  card_sign:=CASE WHEN btrim(card_row.approval_type) IN(''취소'',''부분취소'',''환불'') THEN -1 ELSE 1 END;\n  IF (p#>>''{card,supply}'')::numeric IS DISTINCT FROM card_sign*abs(card_row.supply_amount)\n    OR (p#>>''{card,tax}'')::numeric IS DISTINCT FROM card_sign*abs(card_row.tax_amount)\n    OR (p#>>''{card,total}'')::numeric IS DISTINCT FROM card_sign*abs(card_row.amount_total)\n    OR (p#>>''{invoice,supply}'')::numeric IS DISTINCT FROM COALESCE(invoice_row.amount_total,0)\n    OR (p#>>''{invoice,tax}'')::numeric IS DISTINCT FROM COALESCE(invoice_row.tax_total,0)\n    OR (p#>>''{invoice,total}'')::numeric IS DISTINCT FROM COALESCE(invoice_row.total_amount,0)\n  THEN RAISE EXCEPTION ''Recorded VAT followup source amount mismatch'' USING ERRCODE=''23514''; END IF;\n\n  IF NEW.past_origin=''legacy'' THEN\n    SELECT COALESCE(jsonb_agg(c),''[]''::jsonb) INTO claims\n    FROM vat_returns r CROSS JOIN LATERAL jsonb_array_elements(r.form_json#>''{duplicateReview,claimSources}'') c\n    WHERE r.return_id=NEW.legacy_return_id AND c->>''kind''=historical->>''kind'' AND c->>''sourceId''=historical->>''id'';\n    IF jsonb_array_length(claims)<>1\n    THEN RAISE EXCEPTION ''Recorded VAT followup historical claim unavailable'' USING ERRCODE=''23514''; END IF;\n    expected_claim:=jsonb_build_object(''sourceKind'',claims->0->''kind'',''sourceId'',claims->0->''sourceId'',\n      ''canonicalKey'',claims->0->''canonicalKey'',''sourceHash'',claims->0->''sourceHash'',''direction'',''purchase'',\n      ''supply'',claims->0->''supply'',''tax'',claims->0->''tax'',''claimedTax'',claims->0->''tax'',''date'',claims->0->''date'');\n    expected_grade:=''legacy_internal_snapshot_only'';\n  ELSE\n    SELECT * INTO STRICT basis FROM vat_filing_basis_snapshots WHERE snapshot_id=NEW.past_basis_snapshot_id;\n    SELECT * INTO STRICT fact FROM vat_filing_fact_revisions WHERE revision_id=NEW.past_fact_revision_id;\n    SELECT COALESCE(jsonb_agg(c),''[]''::jsonb) INTO claims\n    FROM jsonb_array_elements(fact.payload_json->''sourceCoverage'') c\n    WHERE c->>''canonicalKey''=historical->>''canonicalKey'' AND EXISTS(\n      SELECT 1 FROM jsonb_array_elements(historical->''aliases'') a\n      WHERE a->>''kind''=c->>''sourceKind'' AND a->>''id''=c->>''sourceId'');\n    IF jsonb_array_length(claims)<>1\n    THEN RAISE EXCEPTION ''Recorded VAT followup historical claim unavailable'' USING ERRCODE=''23514''; END IF;\n    expected_claim:=claims->0;\n    SELECT payload_json INTO STRICT old_subject FROM vat_filing_subject_revisions WHERE revision_id=basis.subject_revision_id;\n    expected_grade:=CASE WHEN vat_followup_server_document(fact.payload_json->>''evidenceRef'',fact.payload_json->>''evidenceHash'',root.subject_id)\n      AND vat_followup_server_document(old_subject->>''evidenceRef'',old_subject->>''evidenceHash'',root.subject_id)\n      THEN ''server_document_verified'' ELSE ''unverified_declaration'' END;\n  END IF;\n  IF claim IS DISTINCT FROM expected_claim\n    OR historical->''claimedTax'' IS DISTINCT FROM expected_claim->''claimedTax''\n  THEN RAISE EXCEPTION ''Recorded VAT followup historical claim mismatch'' USING ERRCODE=''23514''; END IF;\n  IF past->>''evidenceVerification'' IS DISTINCT FROM expected_grade\n  THEN RAISE EXCEPTION ''Recorded VAT followup evidence grade mismatch'' USING ERRCODE=''23514''; END IF;\n  RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_revision_boundary","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE root vat_followup_review_roots%ROWTYPE; previous_state text;\nBEGIN\n  PERFORM pg_advisory_xact_lock(1296256326,1);\n  SELECT * INTO STRICT root FROM vat_followup_review_roots WHERE review_id=NEW.review_id;\n  IF NEW.state=''withdrawn'' THEN\n    SELECT state INTO previous_state FROM vat_followup_review_revisions WHERE revision_id=NEW.previous_revision_id;\n    IF previous_state=''withdrawn''\n    THEN RAISE EXCEPTION ''VAT followup review is already withdrawn'' USING ERRCODE=''23514''; END IF;\n  ELSE\n    PERFORM vat_assert_finalization_open(root.subject_id,root.period_year,root.period_term,root.period_kind,root.application_path);\n  END IF;\n  RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_revision_guard","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE root vat_followup_review_roots%ROWTYPE; previous vat_followup_review_revisions%ROWTYPE;\n app jsonb; sub jsonb; bs vat_filing_basis_snapshots%ROWTYPE; p jsonb; scope_key text;\nBEGIN\n PERFORM pg_advisory_xact_lock(1296256326,1);\n SELECT * INTO STRICT root FROM vat_followup_review_roots WHERE review_id=NEW.review_id;\n scope_key:=root.subject_id||'':''||root.period_year::text||'':''||root.period_term::text;\n PERFORM vat_followup_fence(''scope:''||scope_key);\n PERFORM vat_followup_fence(''review:''||NEW.review_id);\n FOR p IN SELECT value FROM jsonb_array_elements(NEW.payload_json->''pairs'') ORDER BY value->>''pairKey'' LOOP\n  PERFORM vat_followup_fence(''pair:''||scope_key||'':''||COALESCE(p->>''pairKey'',''''));\n END LOOP;\n SELECT * INTO previous FROM vat_followup_review_revisions WHERE review_id=NEW.review_id ORDER BY version DESC LIMIT 1;\n IF NEW.version<>COALESCE(previous.version,0)+1 OR NEW.previous_revision_id IS DISTINCT FROM previous.revision_id\n   OR (NEW.state=''withdrawn'' AND previous.revision_id IS NULL)\n   OR (NEW.state=''recorded'' AND previous.state=''verified'')\n THEN RAISE EXCEPTION ''VAT followup revision chain/state conflict'' USING ERRCODE=''23514''; END IF;\n IF EXISTS(SELECT 1 FROM vat_followup_review_consumptions c JOIN vat_followup_review_revisions r USING(revision_id) WHERE r.review_id=NEW.review_id)\n THEN RAISE EXCEPTION ''Consumed VAT followup review cannot be replaced'' USING ERRCODE=''23514''; END IF;\n app:=NEW.payload_json->''application'';\n IF app->>''subjectId'' IS DISTINCT FROM root.subject_id OR app->>''collectorCorpNum'' IS DISTINCT FROM root.collector_corp_num\n   OR app->>''year'' IS DISTINCT FROM root.period_year::text OR app->>''term'' IS DISTINCT FROM root.period_term::text\n   OR app->>''kind'' IS DISTINCT FROM root.period_kind OR app->>''path'' IS DISTINCT FROM root.application_path\n   OR app->>''dateFrom'' IS DISTINCT FROM root.date_from OR app->>''dateTo'' IS DISTINCT FROM root.date_to\n   OR app->>''basisSnapshotId'' IS DISTINCT FROM root.basis_snapshot_id\n   OR app->>''priorFrom'' IS DISTINCT FROM root.period_year::text||(CASE root.period_term WHEN 1 THEN ''-01-01'' ELSE ''-07-01'' END)\n   OR app->>''priorTo'' IS DISTINCT FROM root.period_year::text||(CASE root.period_term WHEN 1 THEN ''-03-31'' ELSE ''-09-30'' END)\n   OR app->>''currentFrom'' IS DISTINCT FROM root.period_year::text||(CASE root.period_term WHEN 1 THEN ''-04-01'' ELSE ''-10-01'' END)\n THEN RAISE EXCEPTION ''VAT followup application identity/period mismatch'' USING ERRCODE=''23514''; END IF;\n SELECT payload_json INTO STRICT sub FROM vat_filing_subject_revisions WHERE revision_id=app->>''subjectRevisionId'' AND subject_id=root.subject_id;\n IF app->>''subjectHash'' IS DISTINCT FROM vat_followup_hash(sub) OR sub->>''corpNum'' IS DISTINCT FROM root.collector_corp_num\n THEN RAISE EXCEPTION ''VAT followup subject snapshot mismatch'' USING ERRCODE=''23514''; END IF;\n IF NEW.state=''verified'' AND (\n  sub->>''state'' IS DISTINCT FROM ''verified'' OR sub->>''entityType'' IS DISTINCT FROM ''corporation''\n  OR sub->>''vatRegime'' IS DISTINCT FROM ''general'' OR sub->>''filingUnit'' IS DISTINCT FROM ''single_business_place''\n  OR NOT vat_followup_date(sub->>''effectiveFrom'') OR sub->>''effectiveFrom''>app->>''priorFrom''\n  OR (sub->>''effectiveTo'' IS NOT NULL AND (NOT vat_followup_date(sub->>''effectiveTo'') OR sub->>''effectiveTo''<root.date_to))\n  OR NOT vat_followup_server_document(sub->>''evidenceRef'',sub->>''evidenceHash'',root.subject_id)\n  OR EXISTS(SELECT 1 FROM vat_filing_subject_revisions newer WHERE newer.subject_id=root.subject_id\n     AND newer.version>(sub->>''version'')::integer AND newer.payload_json->>''effectiveFrom''<=root.date_to\n     AND (newer.payload_json->>''effectiveTo'' IS NULL OR newer.payload_json->>''effectiveTo''>=app->>''priorFrom''))\n  OR NEW.evaluation_hash IS DISTINCT FROM vat_followup_hash(''{\"canReview\":true,\"issues\":[],\"taxDelta\":0}''::jsonb)\n ) THEN RAISE EXCEPTION ''VAT followup verified subject/evaluation evidence mismatch'' USING ERRCODE=''23514''; END IF;\n IF root.application_path=''basis'' THEN\n  SELECT * INTO STRICT bs FROM vat_filing_basis_snapshots WHERE snapshot_id=root.basis_snapshot_id;\n  IF bs.subject_id<>root.subject_id OR bs.period_year<>root.period_year OR bs.period_term<>root.period_term\n   OR bs.period_kind<>''final'' OR bs.date_from<>root.date_from OR bs.date_to<>root.date_to\n  THEN RAISE EXCEPTION ''VAT followup basis application mismatch'' USING ERRCODE=''23514''; END IF;\n END IF;\n IF NEW.state=''withdrawn'' THEN\n  IF NEW.payload_json->''pairs'' IS DISTINCT FROM previous.payload_json->''pairs''\n    OR NEW.payload_json->''application'' IS DISTINCT FROM previous.payload_json->''application''\n  THEN RAISE EXCEPTION ''Withdrawal must preserve the previous full review evidence'' USING ERRCODE=''23514''; END IF;\n ELSE\n  IF (root.application_path=''legacy'' AND EXISTS(SELECT 1 FROM vat_returns WHERE period_year=root.period_year AND period_term=root.period_term AND period_kind=''final'' AND status=''confirmed''))\n   OR (root.application_path=''basis'' AND EXISTS(SELECT 1 FROM vat_filing_return_confirmations c\n     JOIN vat_filing_basis_snapshots b ON b.snapshot_id=c.basis_snapshot_id\n     WHERE b.subject_id=root.subject_id AND b.period_year=root.period_year AND b.period_term=root.period_term AND b.period_kind=''final''))\n  THEN RAISE EXCEPTION ''The application return is already confirmed'' USING ERRCODE=''23514''; END IF;\n END IF;\n RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_server_document","rows":"0","binary":null,"config":null,"result":"boolean","source":"\n SELECT ref IS NOT NULL AND ref LIKE ''vat-document:%'' AND expected_hash IS NOT NULL AND EXISTS(\n  SELECT 1 FROM vat_filing_documents d WHERE d.document_id=substr(ref,14) AND d.subject_id=subject\n    AND d.content_sha256=expected_hash AND encode(sha256(d.content_bytes),''hex'')=expected_hash\n    AND octet_length(d.content_bytes)=d.size_bytes)\n","strict":false,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"ref text, expected_hash text, subject text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"text, text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_followup_validate_form_v2","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE fc jsonb; app jsonb; entry jsonb; proofs jsonb:=''[]''::jsonb; expected_order jsonb;\n  rev vat_followup_review_revisions%ROWTYPE; pair_row vat_followup_review_pairs%ROWTYPE;\n  root vat_followup_review_roots%ROWTYPE; current_source jsonb; proof jsonb; computed text; parsed_base jsonb; parsed_plan jsonb;\n  field text; amount numeric; manual_delta numeric; payable numeric;\nBEGIN\n  fc:=form->''followupConsumption''; app:=fc->''application'';\n  IF jsonb_typeof(fc) IS DISTINCT FROM ''object''\n    OR fc-ARRAY[''version'',''canonicalVersion'',''application'',''pairs'',''baseCalculationText'',''baseCalculationHash'',''planText'',''planHash'',''calculationHash'']<>''{}''::jsonb\n    OR fc->>''version'' IS DISTINCT FROM ''vat-followup-consumption-v2''\n    OR fc->>''canonicalVersion'' IS DISTINCT FROM ''vat-canonical-v2''\n    OR jsonb_typeof(fc->''baseCalculationText'') IS DISTINCT FROM ''string''\n    OR jsonb_typeof(fc->''planText'') IS DISTINCT FROM ''string''\n    OR COALESCE(fc->>''baseCalculationHash'','''') !~ ''^[0-9a-f]{64}$''\n    OR COALESCE(fc->>''planHash'','''') !~ ''^[0-9a-f]{64}$''\n    OR COALESCE(fc->>''calculationHash'','''') !~ ''^[0-9a-f]{64}$''\n    OR jsonb_typeof(app) IS DISTINCT FROM ''object''\n    OR jsonb_typeof(fc->''pairs'') IS DISTINCT FROM ''array''\n    OR jsonb_typeof(form->''blockingIssues'') IS DISTINCT FROM ''array''\n    OR jsonb_typeof(form#>''{ledgerSnapshot,rows}'') IS DISTINCT FROM ''array''\n    OR jsonb_typeof(form->''manual'') IS DISTINCT FROM ''array''\n  THEN RAISE EXCEPTION ''VAT followup v2 form shape mismatch'' USING ERRCODE=''23514''; END IF;\n  IF app-ARRAY[''subjectId'',''year'',''term'',''kind'',''path'',''basisSnapshotId'',''collectorCorpNum'',''subjectRevisionId'',''subjectHash'',''dateFrom'',''dateTo'',''priorFrom'',''priorTo'',''currentFrom'']<>''{}''::jsonb\n    OR NOT vat_followup_money(app->''year'') OR (app->>''year'')::numeric NOT BETWEEN 1000 AND 9999\n    OR NOT vat_followup_money(app->''term'') OR (app->>''term'')::numeric NOT IN(1,2)\n    OR NOT(app ? ''basisSnapshotId'')\n    OR jsonb_typeof(app->''basisSnapshotId'') NOT IN(''null'',''string'')\n    OR EXISTS(SELECT 1 FROM unnest(ARRAY[''subjectId'',''kind'',''path'',''collectorCorpNum'',''subjectRevisionId'',''subjectHash'',''dateFrom'',''dateTo'',''priorFrom'',''priorTo'',''currentFrom'']) k\n      WHERE jsonb_typeof(app->k) IS DISTINCT FROM ''string'' OR length(btrim(app->>k))=0)\n    OR application_path NOT IN(''basis'',''legacy'')\n  THEN RAISE EXCEPTION ''VAT followup closed application shape mismatch'' USING ERRCODE=''23514''; END IF;\n  IF jsonb_array_length(fc->''pairs'') NOT BETWEEN 1 AND 100\n    OR app->>''path'' IS DISTINCT FROM application_path OR app->>''kind'' IS DISTINCT FROM ''final''\n    OR app->>''basisSnapshotId'' IS DISTINCT FROM basis_id\n    OR form#>''{period,year}'' IS DISTINCT FROM app->''year'' OR form#>''{period,term}'' IS DISTINCT FROM app->''term''\n    OR form#>>''{period,kind}'' IS DISTINCT FROM ''final''\n    OR form#>>''{period,from}'' IS DISTINCT FROM app->>''dateFrom'' OR form#>>''{period,to}'' IS DISTINCT FROM app->>''dateTo''\n    OR (application_path=''basis'' AND (form#>>''{filingBasis,version}'' IS DISTINCT FROM ''vat-return-basis-v2''\n      OR form#>>''{filingBasis,basisSnapshotId}'' IS DISTINCT FROM basis_id))\n    OR (application_path=''legacy'' AND form ? ''filingBasis'')\n  THEN RAISE EXCEPTION ''VAT followup v2 application mismatch'' USING ERRCODE=''23514''; END IF;\n  BEGIN parsed_base:=(fc->>''baseCalculationText'')::jsonb; parsed_plan:=(fc->>''planText'')::jsonb;\n  EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION ''VAT followup base calculation text is invalid'' USING ERRCODE=''23514''; END;\n  IF parsed_base IS DISTINCT FROM vat_followup_base_projection_v2(form)\n    OR fc->>''baseCalculationHash'' IS DISTINCT FROM encode(sha256(convert_to(fc->>''baseCalculationText'',''UTF8'')),''hex'')\n  THEN RAISE EXCEPTION ''VAT followup base calculation text/hash mismatch'' USING ERRCODE=''23514''; END IF;\n  IF parsed_plan IS DISTINCT FROM jsonb_build_object(''application'',app,''pairs'',fc->''pairs'')\n    OR fc->>''planHash'' IS DISTINCT FROM encode(sha256(convert_to(fc->>''planText'',''UTF8'')),''hex'')\n  THEN RAISE EXCEPTION ''VAT followup plan text/hash mismatch'' USING ERRCODE=''23514''; END IF;\n  FOR entry IN SELECT value FROM jsonb_array_elements(fc->''pairs'') LOOP\n    IF jsonb_typeof(entry) IS DISTINCT FROM ''object''\n      OR entry-ARRAY[''reviewId'',''revisionId'',''pairLineNo'',''pairKey'',''payloadHash'',''pair'',''priorClaimedTax'',''currentClaimableTax'']<>''{}''::jsonb\n      OR EXISTS(SELECT 1 FROM unnest(ARRAY[''reviewId'',''revisionId'',''pairKey'',''payloadHash'']) k WHERE jsonb_typeof(entry->k) IS DISTINCT FROM ''string'' OR length(btrim(entry->>k))=0)\n      OR NOT vat_followup_money(entry->''pairLineNo'') OR (entry->>''pairLineNo'')::numeric>99\n      OR NOT vat_followup_money(entry->''priorClaimedTax'') OR (entry->>''priorClaimedTax'')::numeric<=0\n      OR NOT vat_followup_money(entry->''currentClaimableTax'') OR (entry->>''currentClaimableTax'')::numeric<=0\n    THEN RAISE EXCEPTION ''VAT followup consumption entry shape/amount mismatch'' USING ERRCODE=''23514''; END IF;\n    SELECT * INTO STRICT rev FROM vat_followup_review_revisions WHERE revision_id=entry->>''revisionId'';\n    SELECT * INTO STRICT root FROM vat_followup_review_roots WHERE review_id=rev.review_id;\n    SELECT * INTO STRICT pair_row FROM vat_followup_review_pairs WHERE revision_id=rev.revision_id AND line_no=(entry->>''pairLineNo'')::integer;\n    current_source:=pair_row.pair_json->(CASE pair_row.historical_side WHEN ''card'' THEN ''invoice'' ELSE ''card'' END);\n    IF entry->>''reviewId'' IS DISTINCT FROM rev.review_id OR entry->>''payloadHash'' IS DISTINCT FROM rev.payload_hash\n      OR entry->>''pairKey'' IS DISTINCT FROM pair_row.pair_key OR entry->''pair'' IS DISTINCT FROM pair_row.pair_json\n      OR app IS DISTINCT FROM rev.payload_json->''application''\n      OR entry->''priorClaimedTax'' IS DISTINCT FROM pair_row.pair_json#>''{past,claim,claimedTax}''\n      OR entry->''currentClaimableTax'' IS DISTINCT FROM current_source->''claimTax''\n      OR root.application_path IS DISTINCT FROM application_path OR root.basis_snapshot_id IS DISTINCT FROM basis_id\n    THEN RAISE EXCEPTION ''VAT followup selected stored pair mismatch'' USING ERRCODE=''23514''; END IF;\n    proofs:=proofs||jsonb_build_array(jsonb_build_object(''revisionId'',entry->''revisionId'',''pairLineNo'',entry->''pairLineNo'',\n      ''pairKey'',entry->''pairKey'',''payloadHash'',entry->''payloadHash'',''priorClaimedTax'',entry->''priorClaimedTax'',''currentClaimableTax'',entry->''currentClaimableTax''));\n  END LOOP;\n  SELECT jsonb_agg(e ORDER BY (e->>''revisionId'') COLLATE \"C\",(e->>''pairLineNo'')::integer)\n    INTO expected_order FROM jsonb_array_elements(fc->''pairs'') e;\n  IF expected_order IS DISTINCT FROM fc->''pairs''\n    OR (SELECT count(*)<>count(DISTINCT e->>''pairKey'') FROM jsonb_array_elements(fc->''pairs'') e)\n    OR (SELECT count(*)<>count(DISTINCT (e->>''revisionId'',e->>''pairLineNo'')) FROM jsonb_array_elements(fc->''pairs'') e)\n  THEN RAISE EXCEPTION ''VAT followup selected pair order/uniqueness mismatch'' USING ERRCODE=''23514''; END IF;\n  proof:=jsonb_build_object(''version'',''vat-followup-calculation-v2'',''baseCalculationHash'',fc->''baseCalculationHash'',\n    ''planHash'',fc->''planHash'',''applicationHash'',vat_followup_hash_v2(app),''pairs'',proofs);\n  computed:=vat_followup_hash_v2(proof);\n  IF computed IS DISTINCT FROM fc->>''calculationHash''\n    OR (application_path=''basis'' AND computed IS DISTINCT FROM form#>>''{filingBasis,calculationHash}'')\n  THEN RAISE EXCEPTION ''VAT followup v2 calculation hash mismatch'' USING ERRCODE=''23514''; END IF;\n  -- 기존 계산식 그대로: legacy에도 안전한 정수/합계/수기/끝수 검산을 적용한다.\n  FOREACH field IN ARRAY ARRAY[''sales,total,tax'',''sales,invoiceTaxable,tax'',''sales,deemedRent,tax'',''purchases,totalDeductibleTax'',\n    ''purchases,invoiceGeneral,tax'',''purchases,nonDeductible,tax'',''purchases,invoiceUndecided,tax'',''purchases,cardDeductible,tax'',''taxDue'',''finalTaxDue''] LOOP\n    IF jsonb_typeof(form#>string_to_array(field,'','')) IS DISTINCT FROM ''number''\n    THEN RAISE EXCEPTION ''VAT followup required tax amount missing'' USING ERRCODE=''23514''; END IF;\n    amount:=(form#>>string_to_array(field,'',''))::numeric;\n    IF amount<>trunc(amount) OR abs(amount)>9007199254740991\n    THEN RAISE EXCEPTION ''VAT followup tax amount outside integer range'' USING ERRCODE=''23514''; END IF;\n  END LOOP;\n  IF EXISTS(SELECT 1 FROM jsonb_array_elements(form->''manual'') e WHERE NOT vat_followup_money(e->''amount'')\n      OR e->>''key'' IS NULL OR e->>''key'' NOT IN(''etaxCredit'',''penalty'',''prepaidNotice'',''prepaidUnrefunded''))\n    OR (SELECT count(*)<>count(DISTINCT e->>''key'') FROM jsonb_array_elements(form->''manual'') e)\n    OR (form#>>''{sales,total,tax}'')::numeric<>(form#>>''{sales,invoiceTaxable,tax}'')::numeric+(form#>>''{sales,deemedRent,tax}'')::numeric\n    OR (form#>>''{purchases,totalDeductibleTax}'')::numeric<>(form#>>''{purchases,invoiceGeneral,tax}'')::numeric-(form#>>''{purchases,nonDeductible,tax}'')::numeric-(form#>>''{purchases,invoiceUndecided,tax}'')::numeric+(form#>>''{purchases,cardDeductible,tax}'')::numeric\n    OR (form->>''taxDue'')::numeric<>(form#>>''{sales,total,tax}'')::numeric-(form#>>''{purchases,totalDeductibleTax}'')::numeric\n  THEN RAISE EXCEPTION ''VAT followup tax subtotal/manual mismatch'' USING ERRCODE=''23514''; END IF;\n  SELECT COALESCE(sum(CASE WHEN e->>''key''=''penalty'' THEN (e->>''amount'')::numeric ELSE -(e->>''amount'')::numeric END),0)\n    INTO manual_delta FROM jsonb_array_elements(form->''manual'') e;\n  payable:=(form->>''taxDue'')::numeric+manual_delta-CASE WHEN application_path=''basis'' THEN (form#>>''{filingBasis,noticeDeduction}'')::numeric ELSE 0 END;\n  IF payable>0 THEN payable:=floor(payable/10)*10; END IF;\n  IF payable IS NULL OR (form->>''finalTaxDue'')::numeric<>payable\n  THEN RAISE EXCEPTION ''VAT followup final tax mismatch'' USING ERRCODE=''23514''; END IF;\n  RETURN fc;\nEXCEPTION WHEN no_data_found THEN RAISE EXCEPTION ''VAT followup selected reference missing'' USING ERRCODE=''23514'';\n  WHEN invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION ''VAT followup numeric/reference format invalid'' USING ERRCODE=''23514'';\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"form jsonb, application_path text, basis_id text DEFAULT NULL::text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"jsonb, text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_legacy_confirmed_no_delete","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nBEGIN\n  IF OLD.status=''confirmed'' THEN\n    RAISE EXCEPTION ''Confirmed legacy VAT evidence cannot be deleted'' USING ERRCODE=''23514'';\n  END IF;\n  RETURN OLD;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_legacy_finalization_boundary","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nBEGIN\n  PERFORM pg_advisory_xact_lock(1296256326,1);\n  IF TG_OP=''UPDATE'' AND OLD.status=''confirmed'' THEN\n    -- 기존 명시 해제는 금액/기간/원문을 그대로 두고 확정 표시만 비운다.\n    -- C-b2 소비 후 해제 보호는 별도 계약이며 여기서 소비를 활성화하지 않는다.\n    IF NEW.status=''draft'' AND NEW.confirmed_by IS NULL AND NEW.confirmed_at IS NULL\n      AND (to_jsonb(NEW)-ARRAY[''status'',''confirmed_by'',''confirmed_at'',''updated_at''])\n        IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY[''status'',''confirmed_by'',''confirmed_at'',''updated_at''])\n    THEN\n      IF OLD.period_kind=''final'' THEN PERFORM vat_finalization_fence(OLD.period_year,OLD.period_term); END IF;\n      RETURN NEW;\n    END IF;\n    IF to_jsonb(NEW) IS NOT DISTINCT FROM to_jsonb(OLD) THEN RETURN NEW; END IF;\n    RAISE EXCEPTION ''Confirmed legacy VAT evidence cannot be changed'' USING ERRCODE=''23514'';\n  END IF;\n  PERFORM vat_assert_finalization_open(NULL,NEW.period_year,NEW.period_term,NEW.period_kind,''legacy'');\n  RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_legacy_no_truncate","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nBEGIN\n  RAISE EXCEPTION ''Legacy VAT evidence cannot be truncated'' USING ERRCODE=''23514'';\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_post_bind_guard","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE i vat_filing_post_identities%ROWTYPE; f vat_filing_facts%ROWTYPE; e vat_filing_post_events%ROWTYPE;\nBEGIN\n PERFORM vat_post_fence(''identity:''||NEW.identity_id);\n SELECT * INTO STRICT i FROM vat_filing_post_identities WHERE identity_id=NEW.identity_id;\n IF NEW.fact_id IS NOT NULL THEN\n  SELECT * INTO STRICT f FROM vat_filing_facts WHERE fact_id=NEW.fact_id;\n  IF f.subject_id<>i.subject_id OR f.kind<>i.document_kind OR EXISTS(\n   SELECT 1 FROM vat_filing_post_bindings b LEFT JOIN vat_filing_post_events pe ON pe.event_id=b.event_id\n   WHERE b.identity_id=i.identity_id AND (b.fact_id IS NOT NULL AND b.fact_id<>f.fact_id OR b.event_id IS NOT NULL AND pe.shared_b1_fact_id IS DISTINCT FROM f.fact_id)\n  ) THEN RAISE EXCEPTION ''Official document already has an independent owner'' USING ERRCODE=''23514''; END IF;\n ELSE\n  SELECT * INTO STRICT e FROM vat_filing_post_events WHERE event_id=NEW.event_id;\n  IF e.subject_id<>i.subject_id OR (CASE e.kind WHEN ''receipt'' THEN ''filing'' ELSE e.kind END)<>i.document_kind\n   OR EXISTS(SELECT 1 FROM vat_filing_post_bindings b WHERE b.identity_id=i.identity_id AND (b.event_id IS NOT NULL AND b.event_id<>e.event_id OR b.fact_id IS NOT NULL AND b.fact_id IS DISTINCT FROM e.shared_b1_fact_id))\n   OR (e.shared_b1_fact_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM vat_filing_post_bindings b WHERE b.identity_id=i.identity_id AND b.fact_id=e.shared_b1_fact_id))\n  THEN RAISE EXCEPTION ''Official document requires an explicit same-document reference'' USING ERRCODE=''23514''; END IF;\n END IF;\n RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_post_canonical","rows":"0","binary":null,"config":null,"result":"text","source":"\n SELECT CASE jsonb_typeof(v)\n WHEN ''object'' THEN ''{''||COALESCE((SELECT string_agg(to_json(k)::text||'':''||vat_post_canonical(x),'','' ORDER BY k COLLATE \"C\") FROM jsonb_each(v) e(k,x)),'''')||''}''\n WHEN ''array'' THEN ''[''||COALESCE((SELECT string_agg(vat_post_canonical(x),'','' ORDER BY n) FROM jsonb_array_elements(v) WITH ORDINALITY e(x,n)),'''')||'']''\n ELSE v::text END\n","strict":true,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"v jsonb","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"jsonb","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_post_claim_b1_key","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE iid text; normalized text;\nBEGIN\n normalized:=vat_post_key(NEW.document_key);\n iid:=''vpi-''||md5(NEW.subject_id||chr(31)||NEW.kind||chr(31)||normalized);\n PERFORM vat_post_fence(''official:''||NEW.subject_id||'':''||NEW.kind||'':''||normalized);\n INSERT INTO vat_filing_post_identities(identity_id,subject_id,document_kind,document_key)\n VALUES(iid,NEW.subject_id,NEW.kind,normalized) ON CONFLICT(subject_id,document_kind,document_key) DO NOTHING;\n SELECT identity_id INTO STRICT iid FROM vat_filing_post_identities WHERE subject_id=NEW.subject_id AND document_kind=NEW.kind AND document_key=normalized;\n INSERT INTO vat_filing_post_bindings(binding_id,identity_id,fact_id) VALUES(''vpb-''||md5(iid||chr(31)||NEW.fact_id),iid,NEW.fact_id)\n ON CONFLICT(identity_id,fact_id) DO NOTHING;\n RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_post_complete_revision","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE r vat_filing_post_revisions%ROWTYPE; e vat_filing_post_events%ROWTYPE; actual jsonb; expected jsonb; a record; targetref jsonb; t record; amount_sum numeric; used numeric;\nBEGIN\n SELECT * INTO STRICT r FROM vat_filing_post_revisions WHERE revision_id=NEW.revision_id;\n SELECT * INTO STRICT e FROM vat_filing_post_events WHERE event_id=r.event_id;\n SELECT COALESCE(jsonb_agg(jsonb_build_object(''target'',jsonb_build_object(''kind'',CASE WHEN notice_consumption_id IS NOT NULL THEN ''notice'' ELSE ''return'' END,''id'',COALESCE(notice_consumption_id,return_confirmation_id)),''amount'',amount) ORDER BY line_no),''[]'') INTO actual FROM vat_filing_post_allocations WHERE revision_id=r.revision_id;\n expected:=COALESCE(r.payload_json#>''{payment,allocations}'',''[]'');\n IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION ''VAT post complete allocation plan required'' USING ERRCODE=''23514''; END IF;\n IF e.kind=''payment'' THEN\n  SELECT COALESCE(sum(amount),0) INTO amount_sum FROM vat_filing_post_allocations WHERE revision_id=r.revision_id;\n  IF e.shared_b1_fact_id IS NULL AND r.payload_json#>>''{payment,actualTotal}'' IS NOT NULL AND amount_sum+(r.payload_json#>>''{payment,additionalCharges}'')::numeric+(r.payload_json#>>''{payment,otherAmount}'')::numeric+(r.payload_json#>>''{payment,unallocatedAmount}'')::numeric<>(r.payload_json#>>''{payment,actualTotal}'')::numeric\n  THEN RAISE EXCEPTION ''VAT post cash components do not equal original total'' USING ERRCODE=''23514''; END IF;\n  IF e.shared_b1_fact_id IS NOT NULL AND (amount_sum<>0 OR (r.payload_json#>>''{payment,additionalCharges}'')::numeric<>0 OR (r.payload_json#>>''{payment,otherAmount}'')::numeric<>0 OR (r.payload_json#>>''{payment,unallocatedAmount}'')::numeric<>0)\n  THEN RAISE EXCEPTION ''B1 reference cannot create new cash components'' USING ERRCODE=''23514''; END IF;\n  FOR a IN SELECT * FROM vat_filing_post_allocations WHERE revision_id=r.revision_id LOOP\n   targetref:=jsonb_build_object(''kind'',CASE WHEN a.notice_consumption_id IS NOT NULL THEN ''notice'' ELSE ''return'' END,''id'',COALESCE(a.notice_consumption_id,a.return_confirmation_id));\n   PERFORM vat_post_fence(''target:''||(targetref->>''kind'')||'':''||(targetref->>''id''));\n   SELECT * INTO STRICT t FROM vat_post_target(targetref->>''kind'',targetref->>''id'');\n   IF t.subject_id<>e.subject_id THEN RAISE EXCEPTION ''VAT allocation belongs to another subject'' USING ERRCODE=''23514''; END IF;\n   IF r.state=''verified'' AND e.shared_b1_fact_id IS NULL THEN\n    SELECT COALESCE(sum(pa.amount),0) INTO used FROM vat_filing_post_allocations pa JOIN vat_filing_post_revisions pr ON pr.revision_id=pa.revision_id JOIN vat_filing_post_events pe ON pe.event_id=pr.event_id\n     WHERE pr.state=''verified'' AND pe.shared_b1_fact_id IS NULL AND NOT EXISTS(SELECT 1 FROM vat_filing_post_revisions nx WHERE nx.event_id=pr.event_id AND nx.version>pr.version)\n      AND pa.notice_consumption_id IS NOT DISTINCT FROM a.notice_consumption_id AND pa.return_confirmation_id IS NOT DISTINCT FROM a.return_confirmation_id;\n    IF NOT t.baseline_known OR t.baseline_paid+used>greatest(t.target_amount,0)\n    THEN RAISE EXCEPTION ''VAT post allocation exceeds known target balance'' USING ERRCODE=''23514''; END IF;\n   END IF;\n  END LOOP;\n ELSIF e.kind=''reconciliation'' AND r.state=''verified'' THEN\n  targetref:=r.payload_json#>''{reconciliation,target}'';\n  SELECT * INTO STRICT t FROM vat_post_target(targetref->>''kind'',targetref->>''id'',r.payload_json#>>''{reconciliation,throughDate}'');\n  SELECT COALESCE(sum(pa.amount),0) INTO used FROM vat_filing_post_allocations pa JOIN vat_filing_post_revisions pr ON pr.revision_id=pa.revision_id JOIN vat_filing_post_events pe ON pe.event_id=pr.event_id\n   WHERE pr.state=''verified'' AND pe.shared_b1_fact_id IS NULL AND pr.occurred_on<=(r.payload_json#>>''{reconciliation,throughDate}'')\n    AND NOT EXISTS(SELECT 1 FROM vat_filing_post_revisions nx WHERE nx.event_id=pr.event_id AND nx.version>pr.version)\n    AND CASE targetref->>''kind'' WHEN ''notice'' THEN pa.notice_consumption_id=targetref->>''id'' ELSE pa.return_confirmation_id=targetref->>''id'' END;\n  IF NOT t.baseline_known OR jsonb_typeof(r.payload_json#>''{reconciliation,observedPaidTotal}'') IS DISTINCT FROM ''number'' OR (r.payload_json#>>''{reconciliation,observedPaidTotal}'')::numeric IS DISTINCT FROM t.baseline_paid+used\n  THEN RAISE EXCEPTION ''VAT post reconciliation is incomplete'' USING ERRCODE=''23514''; END IF;\n END IF;\n RETURN NULL;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_post_confirmed_return_hash","rows":"0","binary":null,"config":null,"result":"text","source":"\nDECLARE c record; fc jsonb; actual_pairs jsonb;\nBEGIN\n SELECT rr.*,rc.calculation_hash AS confirmed_hash,rc.basis_snapshot_id AS confirmed_basis,\n   rc.confirmed_by,bs.subject_id AS basis_subject_id,bs.scope_hash AS basis_scope_hash,\n   bs.period_year,bs.period_term,bs.period_kind,bs.date_from,bs.date_to\n INTO STRICT c FROM vat_filing_return_confirmations rc\n  JOIN vat_filing_return_revisions rr ON rr.return_id=rc.return_id\n  JOIN vat_filing_basis_snapshots bs ON bs.snapshot_id=rr.basis_snapshot_id\n WHERE rc.confirmation_id=p_confirmation_id;\n IF c.schema_version=''vat-return-basis-v1'' THEN\n  -- 정상 v1의 232 투영과 canonical 해시를 그대로 유지한다.\n  IF c.form_json#>>''{filingBasis,version}'' IS DISTINCT FROM ''vat-return-basis-v1''\n   OR c.form_json ? ''followupConsumption''\n   OR c.calculation_hash IS DISTINCT FROM c.confirmed_hash OR c.basis_snapshot_id IS DISTINCT FROM c.confirmed_basis\n   OR c.calculation_hash IS DISTINCT FROM encode(sha256(convert_to(vat_post_canonical(\n    (c.form_json-ARRAY[''generatedAt'',''warnings'',''ledgerSnapshot'',''filingBasis''])||jsonb_build_object(''filingBasis'',(c.form_json->''filingBasis'')-''calculationHash'',''ledgerRows'',c.form_json#>''{ledgerSnapshot,rows}'')\n   ),''UTF8'')),''hex'')\n   OR jsonb_typeof(c.form_json->''finalTaxDue'') IS DISTINCT FROM ''number''\n   OR (c.form_json->>''finalTaxDue'')::numeric<>trunc((c.form_json->>''finalTaxDue'')::numeric)\n   OR abs((c.form_json->>''finalTaxDue'')::numeric)>9007199254740991\n  THEN RAISE EXCEPTION ''Stored confirmed return integrity unavailable'' USING ERRCODE=''23514''; END IF;\n  RETURN c.calculation_hash;\n ELSIF c.schema_version IS DISTINCT FROM ''vat-return-basis-v2'' THEN\n  RAISE EXCEPTION ''Stored post return version is unsupported'' USING ERRCODE=''55000'';\n END IF;\n\n BEGIN\n  -- 保存専用検算: 最新/未消費/current DBproof/server source を再検査しない。\n  fc:=vat_followup_validate_form_v2(c.form_json,''basis'',c.basis_snapshot_id);\n  IF c.calculation_hash IS DISTINCT FROM c.confirmed_hash\n    OR c.calculation_hash IS DISTINCT FROM fc->>''calculationHash''\n    OR c.basis_snapshot_id IS DISTINCT FROM c.confirmed_basis\n    OR c.scope_hash IS DISTINCT FROM c.basis_scope_hash\n    OR c.form_json#>>''{filingBasis,scopeHash}'' IS DISTINCT FROM c.basis_scope_hash\n    OR c.form_json#>>''{filingBasis,subjectId}'' IS DISTINCT FROM c.basis_subject_id\n    OR fc#>>''{application,subjectId}'' IS DISTINCT FROM c.basis_subject_id\n    OR c.form_json#>''{period,year}'' IS DISTINCT FROM to_jsonb(c.period_year)\n    OR c.form_json#>''{period,term}'' IS DISTINCT FROM to_jsonb(c.period_term)\n    OR c.period_kind IS DISTINCT FROM ''final''\n    OR c.form_json#>>''{period,from}'' IS DISTINCT FROM c.date_from\n    OR c.form_json#>>''{period,to}'' IS DISTINCT FROM c.date_to\n    OR c.form_json->''blockingIssues'' IS DISTINCT FROM ''[]''::jsonb\n    OR c.form_json#>>''{filingBasis,verificationStatus}'' IS DISTINCT FROM ''complete''\n  THEN RAISE EXCEPTION ''Stored v2 confirmation metadata mismatch'' USING ERRCODE=''55000''; END IF;\n\n  SELECT COALESCE(jsonb_agg(x.payload_json ORDER BY (x.payload_json->>''revisionId'') COLLATE \"C\",x.pair_line_no),''[]''::jsonb)\n   INTO actual_pairs FROM vat_followup_review_consumptions x WHERE x.basis_confirmation_id=p_confirmation_id;\n  IF actual_pairs IS DISTINCT FROM fc->''pairs''\n    OR EXISTS(SELECT 1 FROM vat_followup_review_consumptions x\n      WHERE x.basis_confirmation_id=p_confirmation_id AND (\n       x.legacy_archive_id IS NOT NULL OR x.calculation_hash IS DISTINCT FROM c.calculation_hash\n       OR x.created_by IS DISTINCT FROM c.confirmed_by\n       OR x.payload_json->>''revisionId'' IS DISTINCT FROM x.revision_id\n       OR x.payload_json->''pairLineNo'' IS DISTINCT FROM to_jsonb(x.pair_line_no)))\n    OR EXISTS(SELECT 1 FROM vat_followup_review_consumptions x\n      JOIN vat_followup_review_revisions r ON r.revision_id=x.revision_id\n      WHERE x.basis_confirmation_id=p_confirmation_id AND (\n       r.schema_version IS DISTINCT FROM ''vat-followup-review-v1'' OR r.state IS DISTINCT FROM ''verified''\n       OR r.payload_hash IS DISTINCT FROM vat_followup_hash(r.payload_json)\n       OR r.payload_json#>ARRAY[''pairs'',x.pair_line_no::text] IS DISTINCT FROM x.payload_json->''pair''))\n  THEN RAISE EXCEPTION ''Stored v2 confirmed consumption mismatch'' USING ERRCODE=''55000''; END IF;\n  RETURN c.calculation_hash;\n EXCEPTION\n  WHEN serialization_failure OR deadlock_detected THEN RAISE;\n  WHEN OTHERS THEN\n   RAISE EXCEPTION ''Stored v2 post return integrity unavailable''\n     USING ERRCODE=''55000'',DETAIL=SQLSTATE||'': ''||SQLERRM;\n END;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_confirmation_id text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"text","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_post_fence","rows":"0","binary":null,"config":null,"result":"void","source":"\nBEGIN\n PERFORM pg_advisory_xact_lock(1296256326,1);\n INSERT INTO vat_filing_post_fences(key,generation) VALUES(k,1)\n ON CONFLICT(key) DO UPDATE SET generation=vat_filing_post_fences.generation+1;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"k text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"text","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_post_key","rows":"0","binary":null,"config":null,"result":"text","source":"\n SELECT upper(regexp_replace(btrim(v),''\\s'','''',''g''))\n","strict":true,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"v text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"text","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_post_reconciliation_hash","rows":"0","binary":null,"config":null,"result":"text","source":"\nDECLARE baseline_hash text; payments jsonb;\nBEGIN\n IF k=''notice'' THEN SELECT s.scope_hash INTO STRICT baseline_hash FROM vat_filing_basis_consumptions c JOIN vat_filing_basis_snapshots s ON s.snapshot_id=c.snapshot_id WHERE c.consumption_id=target;\n ELSIF k=''return'' THEN baseline_hash:=vat_post_confirmed_return_hash(target);\n ELSE RAISE EXCEPTION ''Unknown reconciliation target'' USING ERRCODE=''23514''; END IF;\n SELECT COALESCE(jsonb_agg(jsonb_build_object(''eventId'',r.event_id,''revisionId'',r.revision_id,''date'',r.occurred_on,''amount'',a.amount) ORDER BY r.event_id,r.revision_id),''[]'') INTO payments\n FROM vat_filing_post_allocations a JOIN vat_filing_post_revisions r ON r.revision_id=a.revision_id JOIN vat_filing_post_events e ON e.event_id=r.event_id\n WHERE r.state=''verified'' AND e.shared_b1_fact_id IS NULL AND r.occurred_on<=through_day\n  AND NOT EXISTS(SELECT 1 FROM vat_filing_post_revisions n WHERE n.event_id=r.event_id AND n.version>r.version)\n  AND CASE k WHEN ''notice'' THEN a.notice_consumption_id=target ELSE a.return_confirmation_id=target END;\n RETURN encode(sha256(convert_to(vat_post_canonical(jsonb_build_object(''kind'',k,''target'',target,''throughDate'',through_day,''baselineHash'',baseline_hash,''payments'',payments)),''UTF8'')),''hex'');\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"k text, target text, through_day text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"text, text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_post_revision_guard","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE e vat_filing_post_events%ROWTYPE; p vat_filing_post_revisions%ROWTYPE; d vat_filing_documents%ROWTYPE;\n i vat_filing_post_identities%ROWTYPE; f record; a jsonb; t record; keyvalue text; targetref jsonb; n numeric;\nBEGIN\n PERFORM vat_post_fence(''event:''||NEW.event_id);\n SELECT * INTO STRICT e FROM vat_filing_post_events WHERE event_id=NEW.event_id;\n SELECT * INTO p FROM vat_filing_post_revisions WHERE event_id=NEW.event_id ORDER BY version DESC LIMIT 1;\n IF NEW.version<>COALESCE(p.version,0)+1 OR NEW.previous_revision_id IS DISTINCT FROM p.revision_id\n  OR p.state=''verified'' AND NEW.state=''recorded'' OR p.revision_id IS NULL AND NEW.state=''withdrawn''\n THEN RAISE EXCEPTION ''VAT post revision head/state conflict'' USING ERRCODE=''23514''; END IF;\n IF NEW.payload_json->>''kind'' IS DISTINCT FROM e.kind OR NEW.payload_json->>''sharedB1FactId'' IS DISTINCT FROM e.shared_b1_fact_id\n THEN RAISE EXCEPTION ''VAT post event identity mismatch'' USING ERRCODE=''23514''; END IF;\n SELECT * INTO STRICT d FROM vat_filing_documents WHERE document_id=NEW.document_id;\n IF d.subject_id<>e.subject_id OR d.content_sha256<>NEW.document_hash OR encode(sha256(d.content_bytes),''hex'')<>NEW.document_hash OR octet_length(d.content_bytes)<>d.size_bytes\n THEN RAISE EXCEPTION ''VAT post document mismatch'' USING ERRCODE=''23514''; END IF;\n keyvalue:=vat_post_key(NEW.payload_json->>''officialKey'');\n IF keyvalue IS NOT NULL THEN\n  SELECT * INTO STRICT i FROM vat_filing_post_identities WHERE identity_id=NEW.identity_id;\n  IF i.subject_id<>e.subject_id OR i.document_kind<>(CASE e.kind WHEN ''receipt'' THEN ''filing'' ELSE e.kind END) OR i.document_key<>keyvalue\n   OR NOT EXISTS(SELECT 1 FROM vat_filing_post_bindings b WHERE b.identity_id=i.identity_id AND b.event_id=e.event_id)\n  THEN RAISE EXCEPTION ''VAT post official identity mismatch'' USING ERRCODE=''23514''; END IF;\n ELSIF NEW.identity_id IS NOT NULL OR NEW.state=''verified'' AND e.kind IN(''receipt'',''payment'') THEN\n  RAISE EXCEPTION ''VAT post official identity required'' USING ERRCODE=''23514'';\n END IF;\n IF e.shared_b1_fact_id IS NOT NULL THEN\n  SELECT r.*,ff.external_key FROM vat_filing_fact_revisions r JOIN vat_filing_facts ff ON ff.fact_id=r.fact_id WHERE r.fact_id=e.shared_b1_fact_id ORDER BY r.version DESC LIMIT 1 INTO f;\n  IF f.fact_id IS NULL OR f.subject_id<>e.subject_id OR f.kind<>(CASE e.kind WHEN ''receipt'' THEN ''filing'' ELSE e.kind END)\n   OR f.state<>''verified'' OR f.payload_json->>''evidenceHash'' IS DISTINCT FROM NEW.document_hash\n   OR NOT EXISTS(SELECT 1 FROM vat_filing_documents bd WHERE ''vat-document:''||bd.document_id=f.payload_json->>''evidenceRef''\n     AND bd.subject_id=e.subject_id AND bd.content_sha256=NEW.document_hash AND encode(sha256(bd.content_bytes),''hex'')=NEW.document_hash AND octet_length(bd.content_bytes)=bd.size_bytes)\n   OR vat_post_key(CASE f.kind WHEN ''filing'' THEN f.payload_json#>>''{data,receiptNumber}'' ELSE f.external_key END) IS DISTINCT FROM keyvalue\n   OR e.kind=''payment'' AND (jsonb_array_length(NEW.payload_json#>''{payment,allocations}'')<>0 OR (NEW.payload_json#>>''{payment,actualTotal}'')::numeric IS DISTINCT FROM f.amount::numeric)\n  THEN RAISE EXCEPTION ''B1 document reference is not identical/reference-only'' USING ERRCODE=''23514''; END IF;\n  IF e.kind=''receipt'' AND NOT EXISTS(\n   SELECT 1 FROM vat_filing_return_confirmations rc JOIN vat_filing_basis_snapshots bs ON bs.snapshot_id=rc.basis_snapshot_id\n   WHERE rc.confirmation_id=NEW.return_confirmation_id AND bs.subject_id=e.subject_id\n    AND bs.period_year=(f.payload_json->>''year'')::integer AND bs.period_term=(f.payload_json->>''term'')::integer\n    AND bs.date_from=(f.payload_json->>''from'') AND bs.date_to=(f.payload_json->>''to'')\n    AND (f.amount IS NULL OR (NEW.payload_json#>>''{receipt,declaredTax}'')::numeric IS NOT DISTINCT FROM f.amount::numeric)\n  ) THEN RAISE EXCEPTION ''Shared B1 receipt period/declared amount mismatch'' USING ERRCODE=''23514''; END IF;\n END IF;\n targetref:=CASE e.kind WHEN ''receipt'' THEN NEW.payload_json#>''{receipt,target}'' WHEN ''reconciliation'' THEN NEW.payload_json#>''{reconciliation,target}'' WHEN ''other'' THEN NEW.payload_json#>''{other,target}'' ELSE NULL END;\n IF NEW.notice_consumption_id IS DISTINCT FROM (CASE WHEN targetref->>''kind''=''notice'' THEN targetref->>''id'' ELSE NULL END)\n  OR NEW.return_confirmation_id IS DISTINCT FROM (CASE WHEN targetref->>''kind''=''return'' THEN targetref->>''id'' ELSE NULL END)\n THEN RAISE EXCEPTION ''VAT post header target FK mismatch'' USING ERRCODE=''23514''; END IF;\n IF targetref IS NOT NULL AND targetref<>''null''::jsonb THEN\n  PERFORM vat_post_fence(''target:''||(targetref->>''kind'')||'':''||(targetref->>''id''));\n  SELECT * INTO STRICT t FROM vat_post_target(targetref->>''kind'',targetref->>''id'');\n  IF t.subject_id<>e.subject_id OR e.kind=''receipt'' AND targetref->>''kind''<>''return''\n  THEN RAISE EXCEPTION ''VAT post target subject/kind mismatch'' USING ERRCODE=''23514''; END IF;\n ELSIF e.kind IN(''receipt'',''reconciliation'') THEN RAISE EXCEPTION ''VAT post target required'' USING ERRCODE=''23514''; END IF;\n IF e.kind=''payment'' THEN\n  IF jsonb_typeof(NEW.payload_json#>''{payment,allocations}'') IS DISTINCT FROM ''array''\n  THEN RAISE EXCEPTION ''VAT post allocation array required'' USING ERRCODE=''23514''; END IF;\n  FOR keyvalue IN SELECT DISTINCT ''target:''||(x->''target''->>''kind'')||'':''||(x->''target''->>''id'') FROM jsonb_array_elements(COALESCE(NEW.payload_json#>''{payment,allocations}'',''[]'')||COALESCE(p.payload_json#>''{payment,allocations}'',''[]'')) x ORDER BY 1 LOOP PERFORM vat_post_fence(keyvalue); END LOOP;\n  FOREACH keyvalue IN ARRAY ARRAY[''actualTotal'',''additionalCharges'',''otherAmount'',''unallocatedAmount''] LOOP\n   a:=NEW.payload_json->''payment''->keyvalue;\n   IF keyvalue=''actualTotal'' AND a=''null''::jsonb AND NEW.state<>''verified'' THEN CONTINUE; END IF;\n   IF jsonb_typeof(a) IS DISTINCT FROM ''number'' THEN RAISE EXCEPTION ''VAT payment component missing'' USING ERRCODE=''23514''; END IF;\n   n:=(a#>>''{}'')::numeric;\n   IF n<0 OR n<>trunc(n) OR n>9007199254740991 THEN RAISE EXCEPTION ''VAT payment component invalid'' USING ERRCODE=''23514''; END IF;\n  END LOOP;\n ELSE\n  a:=CASE e.kind WHEN ''receipt'' THEN NEW.payload_json#>''{receipt,declaredTax}'' WHEN ''reconciliation'' THEN NEW.payload_json#>''{reconciliation,observedPaidTotal}'' ELSE NEW.payload_json#>''{other,amount}'' END;\n  IF a IS NULL OR (a=''null''::jsonb AND NEW.state=''verified'' AND e.kind<>''other'') OR (a<>''null''::jsonb AND (jsonb_typeof(a)<>''number'' OR (a#>>''{}'')::numeric<>trunc((a#>>''{}'')::numeric) OR abs((a#>>''{}'')::numeric)>9007199254740991 OR (e.kind<>''receipt'' AND (a#>>''{}'')::numeric<0)))\n  THEN RAISE EXCEPTION ''VAT post observed amount invalid'' USING ERRCODE=''23514''; END IF;\n  IF e.kind=''reconciliation'' THEN\n   keyvalue:=NEW.payload_json#>>''{reconciliation,throughDate}'';\n   IF keyvalue IS NULL OR keyvalue::date::text IS DISTINCT FROM keyvalue OR keyvalue>NEW.occurred_on\n    OR (NEW.state=''verified'' AND NEW.reconciliation_hash IS DISTINCT FROM vat_post_reconciliation_hash(targetref->>''kind'',targetref->>''id'',keyvalue))\n   THEN RAISE EXCEPTION ''VAT reconciliation date/evidence mismatch'' USING ERRCODE=''23514''; END IF;\n  END IF;\n END IF;\n RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_post_target","rows":"1000","binary":null,"config":null,"result":"TABLE(subject_id text, target_amount bigint, baseline_paid numeric, baseline_known boolean)","source":"\nDECLARE c record; s jsonb; f jsonb; paid numeric:=0; known boolean:=true;\nBEGIN\n IF k=''notice'' THEN\n  SELECT bc.*,bs.scope_json,bs.scope_hash,bs.schema_version,bs.period_year,bs.period_term,\n    fr.amount AS fact_amount,fr.state AS fact_state,fr.payload_json AS fact_json\n  INTO STRICT c FROM vat_filing_basis_consumptions bc JOIN vat_filing_basis_snapshots bs ON bs.snapshot_id=bc.snapshot_id\n    JOIN vat_filing_fact_revisions fr ON fr.revision_id=bc.revision_id\n  WHERE bc.consumption_id=target;\n  s:=c.scope_json;\n  IF c.kind<>''notice'' OR c.fact_state<>''verified'' OR c.amount IS DISTINCT FROM c.fact_amount OR c.amount<0\n   OR c.schema_version<>''vat-filing-basis-v1'' OR s->>''scopeHash'' IS DISTINCT FROM c.scope_hash\n   OR c.scope_hash IS DISTINCT FROM encode(sha256(convert_to(vat_post_canonical(s-''scopeHash''),''UTF8'')),''hex'')\n   OR s->>''subjectId'' IS DISTINCT FROM c.subject_id OR s->>''noticeFactId'' IS DISTINCT FROM c.fact_id\n   OR jsonb_typeof(s->''effectiveFactRevisionIds'') IS DISTINCT FROM ''array'' OR jsonb_typeof(s#>''{evidenceSnapshot,facts}'') IS DISTINCT FROM ''array''\n  THEN RAISE EXCEPTION ''Stored notice basis integrity unavailable'' USING ERRCODE=''23514''; END IF;\n  FOR f IN SELECT value FROM jsonb_array_elements(s#>''{evidenceSnapshot,facts}'') LOOP\n   IF f->>''kind''=''payment'' AND f->>''state''=''verified'' AND s->''effectiveFactRevisionIds'' ? (f->>''revisionId'') AND f#>>''{data,targetNoticeFactId}''=c.fact_id THEN\n    IF f->>''subjectId'' IS DISTINCT FROM c.subject_id OR f#>>''{data,amountSemantics}'' IS DISTINCT FROM ''total_replacement''\n      OR f->>''amount'' IS NULL OR jsonb_typeof(f->''amount'') IS DISTINCT FROM ''number''\n      OR (f->>''amount'')::numeric<0 OR (f->>''amount'')::numeric<>trunc((f->>''amount'')::numeric)\n      OR (f->>''amount'')::numeric>9007199254740991 OR f#>>''{data,paidAt}'' IS NULL\n      OR f->>''year'' IS DISTINCT FROM c.period_year::text OR f->>''term'' IS DISTINCT FROM c.period_term::text\n      OR f->>''from'' IS DISTINCT FROM c.fact_json->>''from'' OR f->>''to'' IS DISTINCT FROM c.fact_json->>''to''\n      OR (f#>>''{data,paidAt}'')::date::text IS DISTINCT FROM f#>>''{data,paidAt}'' THEN known:=false;\n    ELSIF through_day IS NULL OR f#>>''{data,paidAt}''<=through_day THEN paid:=paid+(f->>''amount'')::numeric; END IF;\n   END IF;\n  END LOOP;\n  IF paid>c.amount THEN known:=false; END IF;\n  RETURN QUERY SELECT c.subject_id::text,c.amount::bigint,CASE WHEN known THEN paid ELSE NULL::numeric END,known;\n ELSIF k=''return'' THEN\n  PERFORM vat_post_confirmed_return_hash(target);\n  SELECT bs.subject_id,rr.form_json INTO STRICT c FROM vat_filing_return_confirmations rc\n   JOIN vat_filing_return_revisions rr ON rr.return_id=rc.return_id\n   JOIN vat_filing_basis_snapshots bs ON bs.snapshot_id=rr.basis_snapshot_id WHERE rc.confirmation_id=target;\n  RETURN QUERY SELECT c.subject_id::text,(c.form_json->>''finalTaxDue'')::bigint,0::numeric,true;\n ELSE RAISE EXCEPTION ''Unknown VAT post target'' USING ERRCODE=''23514''; END IF;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"k text, target text, through_day text DEFAULT NULL::text","leakProof":false,"parsedBody":null,"returnsSet":true,"transforms":null,"volatility":"v","argumentTypes":"text, text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"vat_post_target_version","rows":"0","binary":null,"config":null,"result":"text","source":" SELECT ''vat-post-target-v2''::text ","strict":false,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"vo