BEGIN
 IF p_schema IS NULL OR p_schema !~ '^[a-z][a-z0-9_]*$' OR p_schema LIKE 'pg_%' OR pg_catalog.current_setting('server_version_num')::integer/10000<>17
  OR pg_catalog.current_setting('session_replication_role')<>'origin' OR (pg_catalog.current_schemas(false))[1] IS DISTINCT FROM p_schema
  OR pg_catalog.array_position(pg_catalog.current_schemas(true),'pg_catalog')>pg_catalog.array_position(pg_catalog.current_schemas(true),p_schema) THEN
  RAISE EXCEPTION 'R1 trusted schema/environment unavailable' USING ERRCODE='55000'; END IF;
 FOR e IN SELECT value FROM pg_catalog.jsonb_array_elements(expected->'functions') LOOP
  SELECT pg_catalog.jsonb_build_object(
 'name',p.proname,'argumentTypes',pg_catalog.oidvectortypes(p.proargtypes),
 'arguments',pg_catalog.pg_get_function_arguments(p.oid),'result',pg_catalog.pg_get_function_result(p.oid),
 'language',(SELECT l.lanname FROM pg_catalog.pg_language l WHERE l.oid=p.prolang),
 'source',p.prosrc,'binary',p.probin,'parsedBody',p.prosqlbody::text,
 'kind',p.prokind::text,'securityDefiner',p.prosecdef,'leakProof',p.proleakproof,
 'strict',p.proisstrict,'returnsSet',p.proretset,'volatility',p.provolatile::text,
 'parallel',p.proparallel::text,'config',p.proconfig,'cost',p.procost::text,'rows',p.prorows::text,
 'support',p.prosupport::oid::text,'variadic',p.provariadic::text,'transforms',p.protrftypes::text),p.oid INTO actual,row_oid FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace
   WHERE n.nspname=p_schema AND p.proname=e->>'name' AND pg_catalog.oidvectortypes(p.proargtypes)=e->>'argumentTypes';
  IF actual IS DISTINCT FROM e THEN RAISE EXCEPTION 'R1 dependency definition mismatch: %',e->>'name' USING ERRCODE='55000'; END IF;
  resolved:=pg_catalog.to_regprocedure(pg_catalog.format('%I(%s)',e->>'name',e->>'argumentTypes'));
  IF resolved IS DISTINCT FROM row_oid THEN RAISE EXCEPTION 'R1 dependency binding mismatch: %',e->>'name' USING ERRCODE='55000'; END IF;
 END LOOP;
 SELECT pg_catalog.count(*) INTO actual_count FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace
  WHERE n.nspname=p_schema AND p.proname IN(SELECT value->>'name' FROM pg_catalog.jsonb_array_elements(expected->'functions'));
 expected_count:=pg_catalog.jsonb_array_length(expected->'functions');
 IF actual_count<>expected_count OR EXISTS(SELECT 1 FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname<>p_schema AND n.nspname=ANY(pg_catalog.current_schemas(true)) AND p.proname IN(SELECT value->>'name' FROM pg_catalog.jsonb_array_elements(expected->'functions'))) THEN RAISE EXCEPTION 'R1 dependency overload mismatch' USING ERRCODE='55000'; END IF;
 FOR table_name IN SELECT value FROM pg_catalog.jsonb_array_elements_text(expected->'tables') LOOP
  row_oid:=pg_catalog.to_regclass(pg_catalog.format('%I.%I',p_schema,table_name)); resolved:=pg_catalog.to_regclass(pg_catalog.format('%I',table_name));
  IF row_oid IS NULL OR row_oid IS DISTINCT FROM resolved THEN RAISE EXCEPTION 'R1 relation binding mismatch: %',table_name USING ERRCODE='55000'; END IF;
 END LOOP;
 EXECUTE pg_catalog.format('SELECT %I.r1_installation_catalog($1,$2,$3)',p_schema) INTO actual USING p_schema,ARRAY(SELECT value FROM pg_catalog.jsonb_array_elements_text(expected->'tables')),ARRAY(SELECT value FROM pg_catalog.jsonb_array_elements_text(expected->'strictRelations'));
 IF actual IS DISTINCT FROM expected->'installation' THEN RAISE EXCEPTION 'R1 column/constraint/index/trigger/rule/RLS installation mismatch' USING ERRCODE='55000'; END IF;
 RETURN pg_catalog.jsonb_build_object('version','r1-recognition-installation-v1','contractHash','d08f25f7bc06dbb21a299cfbf837e870c3828fc82d226d7d78def0bd4cb94404','schema',p_schema,'functionCount',expected_count,'relationCount',pg_catalog.jsonb_array_length(expected->'tables'),'structureCount',pg_catalog.jsonb_array_length(expected->'strictRelations'));
EXCEPTION WHEN serialization_failure OR deadlock_detected THEN RAISE; WHEN OTHERS THEN RAISE EXCEPTION 'R1 installation unavailable: %',SQLERRM USING ERRCODE='55000';
END $r1$;
